window.ID_SEARCH_DATA = {"free": [{"group": "Start", "title": "Overview", "section": "InstancedDungeons", "snippet": "InstancedDungeons runs isolated dungeon instances for solo players and parties on Paper servers. When a party starts a run, the plugin clones your configured templat...", "text": "InstancedDungeons runs isolated dungeon instances for solo players and parties on Paper servers. When a party starts a run, the plugin clones your configured template world into a temporary instance world, runs your stages, mob spawners, loot chests, and boss or trigger objectives, and deletes the temporary world when the run ends.", "url": "index.html"}, {"group": "Start", "title": "Overview", "section": "Quick Start", "snippet": "Create a template world, set spawn, exit, and objective points in editor mode, and validate before opening to players: /dg world create dragon_template flat normal 5...", "text": "Create a template world, set spawn, exit, and objective points in editor mode, and validate before opening to players: /dg world create dragon_template flat normal 500 /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon setexit /dungeon setboss /dungeon save /dungeon reload /dungeon validate dragon_lair Players can then open a party, invite members, and start an instance: /dungeon open dragon_lair /dungeon join <code> /dungeon start", "url": "index.html#quick-start"}, {"group": "Start", "title": "Overview", "section": "Core Architecture", "snippet": "| [Template Worlds](getting-started.md) | Create flat template worlds directly with `/dg world create` or use existing server worlds. Instances inherit gamerules, `W...", "text": "| [Template Worlds](getting-started.md) | Create flat template worlds directly with `/dg world create` or use existing server worlds. Instances inherit gamerules, `WorldBorder` settings, and WorldGuard regions/flags. | | [Objectives](objectives.md) | Complete runs by defeating a configured boss (`boss.yml`) or activating a completion button/pressure plate (`trigger.yml`). | | [Stages and Gates](stages.md) | Lock sections of a dungeon behind block gates that open after clearing `REGION`, `KILL_MOBS`, `LEVER`, `BUTTON`, `PRESSURE_PLATE`, `REQUIRED_KEY`, `TIME`, `SACRIFICE`, `MONEY_PAYMENT`, or `ITEM_PAYMENT` missions. | | [Spawners and Mobs](spawners-and-mobs.md) | Trigger Vanilla or MythicMobs pools on instance start or player proximity, with configurable delays and mob lifetime rules. | | [Loot and Rewards](loot-and-rewards.md) | Place tagged loot chests in the template world, distribute stage mission keys, and configure boss or trigger completion rewards. | | [Towers](towers.md) | Link a `FIRST` entry dungeon to a `LAST` final dungeon so parties automatically progress between floors. | | [Event Commands](event-commands.md) | Run console or player commands on party creation, run start, stage completion, gate opening, mob/boss kills, completion, or failure. | | [Validation](commands.md#core-admin-commands) | Run `/dungeon validate <id|all>` to check YAML syntax, locations, item IDs, stage order continuity, and tower links before opening dungeons to players. |", "url": "index.html#core-architecture"}, {"group": "Start", "title": "Overview", "section": "Configuration Layout", "snippet": "plugins/InstancedDungeons/ ├── config.yml ├── messages.yml ├── data/ │ ├── template-worlds.dat │ └── instance-worlds.dat └── dungeons/ └── &lt;dungeon_id&gt;/ ├── config.y...", "text": "plugins/InstancedDungeons/ ├── config.yml ├── messages.yml ├── data/ │ ├── template-worlds.dat │ └── instance-worlds.dat └── dungeons/ └── <dungeon_id>/ ├── config.yml ├── boss.yml / trigger.yml ├── commands.yml ├── command-blacklist.txt ├── spawners/ ├── loot-chests/ └── stages/", "url": "index.html#configuration-layout"}, {"group": "Start", "title": "Getting Started", "section": "Getting Started", "snippet": "This guide creates a working dungeon from a template world.", "text": "This guide creates a working dungeon from a template world.", "url": "getting-started/index.html"}, {"group": "Start", "title": "Getting Started", "section": "Requirements", "snippet": "| Paper 1.21.x | 21+ | Built-in (`/dg world`) | | Paper 26.1.x / 26.2.x / 26.3.x | 25+ | Built-in (`/dg world`) | One universal plugin JAR supports both Paper 1.21.x...", "text": "| Paper 1.21.x | 21+ | Built-in (`/dg world`) | | Paper 26.1.x / 26.2.x / 26.3.x | 25+ | Built-in (`/dg world`) | One universal plugin JAR supports both Paper 1.21.x and Paper 26.1.x / 26.2.x / 26.3.x. Optional integrations: WorldGuard for copying template world regions and flags into dungeon instances. MythicMobs for custom mobs and bosses. MythicMobs items through `MYTHIC_ITEM`. ItemsAdder, Oraxen, or Nexo for custom item IDs. Vault plus an economy plugin for money costs and payment missions. Multiverse-Core for optional compatibility with external server worlds.", "url": "getting-started/index.html#requirements"}, {"group": "Start", "title": "Getting Started", "section": "Install", "snippet": "Stop the server. Put the plugin `.jar` into the `plugins` folder. Start the server once. Configure dungeons in `plugins/InstancedDungeons/dungeons/`. Run `/dungeon r...", "text": "Stop the server. Put the plugin `.jar` into the `plugins` folder. Start the server once. Configure dungeons in `plugins/InstancedDungeons/dungeons/`. Run `/dungeon reload` after YAML edits. Current dungeons use the 2.0 config format. Older 1.0.x dungeons should be recreated or kept with the legacy documentation.", "url": "getting-started/index.html#install"}, {"group": "Start", "title": "Getting Started", "section": "Create a Boss Dungeon", "snippet": "Create a clean flat template world (or use an existing server world). Example: /dg world create dragon_template flat normal 500 Then configure the dungeon: /dungeon ...", "text": "Create a clean flat template world (or use an existing server world). Example: /dg world create dragon_template flat normal 500 Then configure the dungeon: /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon setexit /dungeon setboss /dungeon save /dungeon reload Validate before players use it: /dungeon validate dragon_lair", "url": "getting-started/index.html#create-a-boss-dungeon"}, {"group": "Start", "title": "Getting Started", "section": "Create a Trigger Dungeon", "snippet": "Trigger dungeons complete when players activate one configured button or pressure plate. /dg world create puzzle_template /dungeon create puzzle_room puzzle_template...", "text": "Trigger dungeons complete when players activate one configured button or pressure plate. /dg world create puzzle_template /dungeon create puzzle_room puzzle_template trigger /dungeon edit puzzle_room /dungeon setspawn /dungeon setexit /dungeon settrigger STONE_BUTTON /dungeon trigger reward edit /dungeon save /dungeon reload", "url": "getting-started/index.html#create-a-trigger-dungeon"}, {"group": "Start", "title": "Getting Started", "section": "Start as a Player", "snippet": "/dungeon open dragon_lair /dungeon join &lt;code&gt; /dungeon start `/dungeon open` only suggests standalone dungeons and tower `FIRST` stages. Middle and last tower stage...", "text": "/dungeon open dragon_lair /dungeon join <code> /dungeon start `/dungeon open` only suggests standalone dungeons and tower `FIRST` stages. Middle and last tower stage IDs are entered through tower progression.", "url": "getting-started/index.html#start-as-a-player"}, {"group": "Start", "title": "Updating", "section": "Before Updating", "snippet": "Stop the server. Back up `plugins/InstancedDungeons/dungeons/`, `config.yml`, `messages.yml`, and `data/`. Replace the plugin JAR in `plugins/` (one JAR supports bot...", "text": "Stop the server. Back up `plugins/InstancedDungeons/dungeons/`, `config.yml`, `messages.yml`, and `data/`. Replace the plugin JAR in `plugins/` (one JAR supports both Paper 1.21.x and Paper 26.x). Start the server, check `/dg status`, and run `/dg validate all`. Test a dungeon before allowing players to enter. InstancedDungeons does not create automatic backups.", "url": "updating/index.html#before-updating"}, {"group": "Start", "title": "Updating", "section": "Automatic Config and Message Updates", "snippet": "**Configs (`config.yml` and `dungeons/&lt;id&gt;/config.yml`)**: Missing settings are added automatically beside related options with safe defaults. Existing administrator...", "text": "**Configs (`config.yml` and `dungeons/<id>/config.yml`)**: Missing settings are added automatically beside related options with safe defaults. Existing administrator values, unknown keys, unrelated sections, and comments are preserved. **Messages (`messages.yml`)**: Missing message keys are appended to the update section at the end of existing files without overwriting your custom translations. **Internal Data (`plugins/InstancedDungeons/data/`)**: Runtime data files (`template-worlds.dat` and `instance-worlds.dat`) are stored under `data/` and migrated automatically from legacy root `.yml` files on startup. Administrators joining during the first few minutes after an update receive a one-time notice if any configuration files should be reviewed. Validation (`/dg validate all`) reports the exact file and field whenever manual attention is needed.", "url": "updating/index.html#automatic-config-and-message-updates"}, {"group": "Start", "title": "Examples", "section": "Examples", "snippet": "Examples for boss dungeons, trigger puzzles, towers, stage keys, and event commands.", "text": "Examples for boss dungeons, trigger puzzles, towers, stage keys, and event commands.", "url": "examples/index.html"}, {"group": "Start", "title": "Examples", "section": "Example 1: Simple Boss Dungeon", "snippet": "Use this when you want a classic dungeon that ends after a boss dies. /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /d...", "text": "Use this when you want a classic dungeon that ends after a boss dies. /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon setexit /dungeon setboss /dungeon boss reward edit /dungeon save /dungeon reload /dungeon validate dragon_lair Recommended flow: Build the template world. Set spawn near the entrance. Set exit in your server hub or dungeon lobby. Set boss spawn in the final room. Add rewards with `/dungeon boss reward edit`. Validate before letting players start the run. Minimal boss behavior in `config.yml`: completion-objective: BOSS fire-spread: false boss: must-die-to-complete: true countdown-after-death: 30", "url": "examples/index.html#example-1-simple-boss-dungeon"}, {"group": "Start", "title": "Examples", "section": "Example 2: Trigger Puzzle Dungeon", "snippet": "Use this for puzzle rooms, parkour endings, escape rooms, or dungeons that complete from a button or pressure plate. /dungeon create puzzle_room puzzle_template trig...", "text": "Use this for puzzle rooms, parkour endings, escape rooms, or dungeons that complete from a button or pressure plate. /dungeon create puzzle_room puzzle_template trigger /dungeon edit puzzle_room /dungeon setspawn /dungeon setexit /dungeon settrigger STONE_BUTTON /dungeon trigger reward edit /dungeon save /dungeon reload /dungeon validate puzzle_room Trigger reward example: rewards: enabled: true items: - type: VANILLA item: DIAMOND amount: 2 chance: 100.0 Trigger blocks work even when normal dungeon interactions are blocked.", "url": "examples/index.html#example-2-trigger-puzzle-dungeon"}, {"group": "Start", "title": "Examples", "section": "Example 3: Two-Stage Tower", "snippet": "Use this when one party should clear a first dungeon and then automatically enter a final dungeon. First dungeon: dungeon-type: tower tower-stage-type: first next-du...", "text": "Use this when one party should clear a first dungeon and then automatically enter a final dungeon. First dungeon: dungeon-type: tower tower-stage-type: first next-dungeon: \"tower_final\" announce-complete: true announce-fail: true Final dungeon: dungeon-type: tower tower-stage-type: last next-dungeon: \"\" Rules to remember: Players open only the `FIRST` stage directly. `/dungeon list` hides the final stage as a public dungeon. Final completion broadcasts use the final dungeon name. Announcement settings come from the entry dungeon.", "url": "examples/index.html#example-3-two-stage-tower"}, {"group": "Start", "title": "Examples", "section": "Example 4: Stage Gate With a Key", "snippet": "Use this when players must find a mission key before a gate opens. /dungeon edit dragon_lair /dungeon stage create entrance_gate /dungeon stage entrance_gate gate cr...", "text": "Use this when players must find a mission key before a gate opens. /dungeon edit dragon_lair /dungeon stage create entrance_gate /dungeon stage entrance_gate gate create /dungeon gate save /dungeon stage entrance_gate mission required_key 1 /dungeon stage entrance_gate gate hologram create Add a mission key to a loot chest: loot-table: - type: MISSION item: KEY stage: 1 quantity: 1 lore: - \"&7A key used to unlock a dungeon stage.\"", "url": "examples/index.html#example-4-stage-gate-with-a-key"}, {"group": "Start", "title": "Examples", "section": "Example 5: Event Command Reward Broadcast", "snippet": "Use this when you want automation after completion. commands: - event: on-party-complete-dungeon-command enabled: true executor: CONSOLE audience: NONE commands: - &quot;...", "text": "Use this when you want automation after completion. commands: - event: on-party-complete-dungeon-command enabled: true executor: CONSOLE audience: NONE commands: - \"broadcast <party_leader>'s party completed <dungeon_name>\" For towers, use: commands: - event: on-party-complete-tower-command enabled: true executor: CONSOLE audience: NONE commands: - \"broadcast <party_leader>'s party completed the tower\"", "url": "examples/index.html#example-5-event-command-reward-broadcast"}, {"group": "Start", "title": "Examples", "section": "Validation Checklist", "snippet": "Before publishing a dungeon to players: Run `/dungeon validate &lt;id&gt;`. Confirm the template world exists and is loaded. Confirm spawn and exit are set. Confirm boss o...", "text": "Before publishing a dungeon to players: Run `/dungeon validate <id>`. Confirm the template world exists and is loaded. Confirm spawn and exit are set. Confirm boss or trigger objective exists. Confirm tower `next-dungeon` links are valid. Confirm loot chest IDs match placed loot chest items. Confirm stage order is continuous.", "url": "examples/index.html#validation-checklist"}, {"group": "Start", "title": "Commands", "section": "Commands", "snippet": "Use `/dungeon` or its alias `/dg`.", "text": "Use `/dungeon` or its alias `/dg`.", "url": "commands/index.html"}, {"group": "Start", "title": "Commands", "section": "Player Commands", "snippet": "| `/dungeon help` | Shows player and admin help. | | `/dungeon list` | Lists available dungeons. Tower last-stage dungeons are hidden. | | `/dungeon open &lt;id&gt;` | Cre...", "text": "| `/dungeon help` | Shows player and admin help. | | `/dungeon list` | Lists available dungeons. Tower last-stage dungeons are hidden. | | `/dungeon open <id>` | Creates a party for a standalone dungeon or tower `FIRST` stage. | | `/dungeon join <code>` | Joins an open party. | | `/dungeon leave` | Leaves an open party. | | `/dg kick <player>` | Removes another member before the dungeon starts. | | `/dungeon start` | Starts the dungeon as party leader. | | `/dungeon exit` | Leaves the active dungeon instance. | | `/dungeon spectate <leader>` | Spectates the active dungeon led by that party leader. | | `/dungeon spectator exit` | Leaves external spectator mode and restores inventory and gamemode. | `/dg kick <player>` removes a member from the leader's open party. Tab completion suggests only other members of that party. The leader cannot kick themselves, players outside the party, or anyone after dungeon preparation has begun. The removed player and the remaining party receive configurable messages. No extra permission is required beyond being that party's leader. Kicking removes the current membership; it does not ban the player from joining an open party again.", "url": "commands/index.html#player-commands"}, {"group": "Start", "title": "Commands", "section": "World Management Commands", "snippet": "| `/dg world create &lt;name&gt; [flat] [normal\\|nether\\|the_end] [worldborder]` | Creates a structure-free flat template world with an optional environment and initial wo...", "text": "| `/dg world create <name> [flat] [normal\\|nether\\|the_end] [worldborder]` | Creates a structure-free flat template world with an optional environment and initial world border size (default `500`). | | `/dg world list` | Lists available server and template worlds (excludes active dungeon instances) and highlights worlds created by the plugin. | | `/dg world tp <name>` | Teleports to a template or server world. | | `/dg world delete <name>` | Deletes a plugin-created template world after confirmation if no dungeon uses it. | Newly created template worlds apply the defaults from `template-worlds` in the main `config.yml` and set an initial world border (`500` by default, or the number passed at the end of `/dg world create`). You can later adjust the template world's border with vanilla `/worldborder` commands, and each dungeon instance copies that border automatically.", "url": "commands/index.html#world-management-commands"}, {"group": "Start", "title": "Commands", "section": "Core Admin Commands", "snippet": "| `/dungeon create &lt;id&gt; &lt;template-world&gt; &lt;boss\\|trigger&gt;` | Creates a dungeon using the current config format. | | `/dungeon edit &lt;id&gt;` | Enters editor mode. | | `/d...", "text": "| `/dungeon create <id> <template-world> <boss\\|trigger>` | Creates a dungeon using the current config format. | | `/dungeon edit <id>` | Enters editor mode. | | `/dungeon save` | Exits editor mode. | | `/dungeon reload` | Reloads configs and validation. | | `/dungeon validate <id>` | Validates one dungeon. | | `/dungeon validate all` | Validates every dungeon. | | `/dungeon delete <id>` | Deletes a dungeon after confirmation. | | `/dungeon instances` | Shows active parties and instances. | | `/dungeon status` | Shows detected integration and economy status. |", "url": "commands/index.html#core-admin-commands"}, {"group": "Start", "title": "Commands", "section": "Objective Commands", "snippet": "| `/dungeon setspawn` | Sets the dungeon spawn at your location. | | `/dungeon setexit` | Sets the dungeon exit at your location. | | `/dungeon setboss` | Sets the b...", "text": "| `/dungeon setspawn` | Sets the dungeon spawn at your location. | | `/dungeon setexit` | Sets the dungeon exit at your location. | | `/dungeon setboss` | Sets the boss spawn for boss-objective dungeons. | | `/dungeon boss reward edit` | Opens the boss reward editor GUI. | | `/dungeon settrigger <button\\|pressure_plate>` | Gives the trigger item for trigger-objective dungeons. | | `/dungeon trigger reward edit` | Opens the trigger reward editor GUI. |", "url": "commands/index.html#objective-commands"}, {"group": "Start", "title": "Commands", "section": "Loot Commands", "snippet": "| `/dungeon addlootchest &lt;id&gt;` | Creates a loot chest config at your location. | | `/dungeon lootchest give &lt;id&gt;` | Gives a placeable loot chest item. | | `/dungeon ...", "text": "| `/dungeon addlootchest <id>` | Creates a loot chest config at your location. | | `/dungeon lootchest give <id>` | Gives a placeable loot chest item. | | `/dungeon lootchest loot <id> add` | Adds the item in your main hand to the loot chest config. |", "url": "commands/index.html#loot-commands"}, {"group": "Start", "title": "Commands", "section": "Stage Commands", "snippet": "| `/dungeon stage create &lt;stage_id&gt;` | Creates a stage file. | | `/dungeon stage list` | Lists stages in the current editor dungeon. | | `/dungeon stage &lt;stage_id&gt; o...", "text": "| `/dungeon stage create <stage_id>` | Creates a stage file. | | `/dungeon stage list` | Lists stages in the current editor dungeon. | | `/dungeon stage <stage_id> order <number>` | Moves a stage to another order. Equal orders run in parallel. | | `/dungeon stage <stage_id> delete` | Deletes a stage after confirmation. | | `/dungeon stage <stage_id> gate create` | Starts gate block creation mode. | | `/dungeon stage <stage_id> gate edit` | Edits existing gate blocks. | | `/dungeon stage <stage_id> gate delete` | Deletes a gate after confirmation. | | `/dungeon stage <stage_id> gate stick` | Gives the gate edit stick. | | `/dungeon gate save` | Saves the active gate edit session. | | `/dungeon stage <stage_id> gate hologram create` | Adds a stage hologram. | | `/dungeon stage <stage_id> gate hologram delete` | Removes the nearest hologram within 3 blocks. |", "url": "commands/index.html#stage-commands"}, {"group": "Start", "title": "Commands", "section": "Stage Mission Commands", "snippet": "/dg stage &lt;stage_id&gt; mission region /dg stage &lt;stage_id&gt; mission region pos1 /dg stage &lt;stage_id&gt; mission region pos2 /dg stage &lt;stage_id&gt; mission region delete /dun...", "text": "/dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 /dg stage <stage_id> mission region pos2 /dg stage <stage_id> mission region delete /dungeon stage <stage_id> mission kill_mobs <amount> /dungeon stage <stage_id> mission lever /dungeon stage <stage_id> mission button <button_material> /dungeon stage <stage_id> mission pressure_plate <plate_material> /dungeon stage <stage_id> mission required_key <amount> /dungeon stage <stage_id> mission time <seconds> /dungeon stage <stage_id> mission sacrifice [LEADER_SELECTS|PARTY_VOTE|FIRST_PLAYER_DECISION] [drop_items] /dungeon stage <stage_id> mission money_payment <amount> [ANY_PLAYER|LEADER_ONLY] /dungeon stage <stage_id> mission item_payment /dungeon stage <stage_id> mission <type> delete Run `region` to create the mission, then stand at each corner in the template world and run `pos1` or `pos2`. `delete` removes the mission. Configure `region.mode` and `region.whole-party` in the stage YAML. See [Region Missions](stages.md#region-missions). Dungeon IDs, template worlds, stage IDs, loot chest IDs, trigger materials, mission materials, validation targets, and integration item IDs are tab-completed where supported.", "url": "commands/index.html#stage-mission-commands"}, {"group": "Start", "title": "Commands", "section": "RAM Analysis", "snippet": "`/dungeon ram analysis` toggles memory reports. Requires `instanceddungeons.admin`. See [RAM Analysis](ram-analysis.md).", "text": "`/dungeon ram analysis` toggles memory reports. Requires `instanceddungeons.admin`. See [RAM Analysis](ram-analysis.md).", "url": "commands/index.html#ram-analysis"}, {"group": "Start", "title": "Permissions", "section": "Permissions", "snippet": "| `instanceddungeons.admin` | op | Allows all admin setup commands. | | `instanceddungeons.open` | true | Allows `/dungeon open`. | | `instanceddungeons.open.&lt;dungeo...", "text": "| `instanceddungeons.admin` | op | Allows all admin setup commands. | | `instanceddungeons.open` | true | Allows `/dungeon open`. | | `instanceddungeons.open.<dungeon_id>` | true | Allows opening one specific dungeon. | | `instanceddungeons.join` | true | Allows `/dungeon join`. | | `instanceddungeons.join.<dungeon_id>` | true | Allows joining one specific dungeon. | | `instanceddungeons.spectate` | true | Allows spectator commands. | | `instanceddungeons.bypass.limit` | op | Bypasses instance limits. | | `instanceddungeons.bypass.cost` | op | Bypasses dungeon entry costs. | Both global and dungeon-specific permissions must allow the action. Example: instanceddungeons.open instanceddungeons.open.dragon_lair", "url": "permissions/index.html"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Dungeon Config", "snippet": "Every dungeon has a main config file: plugins/InstancedDungeons/dungeons/&lt;dungeon_id&gt;/config.yml The current dungeon format requires: v: 2.0 Dungeons without this ma...", "text": "Every dungeon has a main config file: plugins/InstancedDungeons/dungeons/<dungeon_id>/config.yml The current dungeon format requires: v: 2.0 Dungeons without this marker are blocked from opening. The optional `ram-analysis.yml` is a plugin-level diagnostic file, not a dungeon config. It is created only after an administrator runs `/dungeon ram analysis`; see [RAM Analysis](ram-analysis.md).", "url": "configuration/index.html"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Core Fields", "snippet": "dungeon-type: single tower-stage-type: first next-dungeon: &quot;&quot; completion-objective: BOSS display-name: &quot;Dragon Lair&quot; template-world: &quot;dragon_template&quot; min-players: 1...", "text": "dungeon-type: single tower-stage-type: first next-dungeon: \"\" completion-objective: BOSS display-name: \"Dragon Lair\" template-world: \"dragon_template\" min-players: 1 max-players: 5 time-limit: 1800 | `dungeon-type` | `single` or `tower`. | | `tower-stage-type` | `first` or `last`. Used only for tower dungeons. | | `next-dungeon` | Next dungeon ID for tower transitions. | | `completion-objective` | `BOSS` or `TRIGGER`. | | `template-world` | Source world copied for each instance. | | `time-limit` | Run time in seconds. |", "url": "configuration/index.html#core-fields"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Template World Defaults and Inheritance", "snippet": "When creating new template worlds with `/dg world create`, the plugin applies the default rules from `plugins/InstancedDungeons/config.yml`: template-worlds: freeze-...", "text": "When creating new template worlds with `/dg world create`, the plugin applies the default rules from `plugins/InstancedDungeons/config.yml`: template-worlds: freeze-ticks: true freeze-time: true freeze-weather: true natural-mob-spawning: false `freeze-ticks: true` sets the template world's random tick speed to `0` so leaves, ice, and crops do not decay or grow while building or running the dungeon. `freeze-time: true`, `freeze-weather: true`, and `natural-mob-spawning: false` disable daylight progression, weather changes, and natural mob spawns on newly created template worlds. All gamerules, the `WorldBorder` center/size/damage settings, and any **WorldGuard** regions and flags configured on the template world are automatically copied to every dungeon instance and cleaned up when the instance ends.", "url": "configuration/index.html#template-world-defaults-and-inheritance"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Spawn and Exit", "snippet": "Spawn and exit are normally set in-game: /dungeon edit &lt;id&gt; /dungeon setspawn /dungeon setexit Players enter the instance at the dungeon spawn. Players are sent to t...", "text": "Spawn and exit are normally set in-game: /dungeon edit <id> /dungeon setspawn /dungeon setexit Players enter the instance at the dungeon spawn. Players are sent to the exit when they leave, fail, or complete the run.", "url": "configuration/index.html#spawn-and-exit"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Announcements", "snippet": "announce-start: false announce-complete: false announce-fail: false `announce-start` broadcasts when a run starts. `announce-complete` broadcasts when a standalone d...", "text": "announce-start: false announce-complete: false announce-fail: false `announce-start` broadcasts when a run starts. `announce-complete` broadcasts when a standalone dungeon completes. In towers, this is controlled by the entry dungeon and is broadcast only after the final tower stage completes. `announce-fail` broadcasts when a standalone dungeon or whole tower fails. Tower complete/fail announcements use the entry dungeon's `announce-*` settings. Middle and last tower stage configs do not control global tower announcements.", "url": "configuration/index.html#announcements"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Entry Costs", "snippet": "costs: money: 1000 items: - type: VANILLA item: DIAMOND amount: 2 If `require-all-players-pay` is `false`, only the leader pays. If it is `true`, every party member ...", "text": "costs: money: 1000 items: - type: VANILLA item: DIAMOND amount: 2 If `require-all-players-pay` is `false`, only the leader pays. If it is `true`, every party member must meet the cost. Tower rule: only `FIRST` tower stages may have entry costs.", "url": "configuration/index.html#entry-costs"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Protection", "snippet": "allow-block-break: false allow-block-place: false allow-fluid-place: false allow-fluid-take: false allow-interactions: true allow-party-pvp: true allow-fly: false fi...", "text": "allow-block-break: false allow-block-place: false allow-fluid-place: false allow-fluid-take: false allow-interactions: true allow-party-pvp: true allow-fly: false fire-spread: false `allow-fly: true` leaves flight already granted by a game mode, permission, or another plugin untouched. It never grants flight by itself. `false` forces flight off for active Survival and Adventure dungeon players and restores their previous flight state when they leave the dungeon. Creative and Spectator modes are exempt. Trigger objectives and mission blocks can still work when normal interactions are blocked. `fire-spread: false` disables fire spreading in the template world and copied instances. Set it to `true` to allow spreading. Older 1.21.x uses `doFireTick`; from 1.21.11 the plugin uses `minecraft:fire_spread_radius_around_player`, with zero to disable spreading.", "url": "configuration/index.html#protection"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Item Restrictions", "snippet": "Dungeons can block movement, teleport, combat, and consumable items inside an active instance: item-restrictions: block-elytra: false block-ender-pearls: false block...", "text": "Dungeons can block movement, teleport, combat, and consumable items inside an active instance: item-restrictions: block-elytra: false block-ender-pearls: false block-chorus-fruit: false block-enchanted-golden-apples: false block-wind-charges: false block-firework-rockets: false block-mace: false block-trident: false All restrictions default to `false`. | `block-elytra` | Starting or continuing elytra flight. | | `block-ender-pearls` | Throwing an ender pearl and the resulting teleport. | | `block-chorus-fruit` | Eating chorus fruit and the resulting teleport. | | `block-enchanted-golden-apples` | Consuming enchanted golden apples. | | `block-wind-charges` | Using or launching wind charges. | | `block-firework-rockets` | Using, launching, or firing firework rockets from a crossbow. | | `block-mace` | Using a mace in melee combat. | | `block-trident` | Using a trident in melee combat or throwing it. | Restrictions apply only while the player belongs to an active dungeon instance and is physically inside its world. Configure them in the dungeon YAML. Missing restriction keys are appended with `false` without replacing existing dungeon settings.", "url": "configuration/index.html#item-restrictions"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Death Behavior", "snippet": "lives: scope: PLAYER amount: 1 death-behavior: ELIMINATE_AS_SPECTATOR fail-if-all-players-dead: true | `ELIMINATE_AS_SPECTATOR` | Eliminated players become dungeon s...", "text": "lives: scope: PLAYER amount: 1 death-behavior: ELIMINATE_AS_SPECTATOR fail-if-all-players-dead: true | `ELIMINATE_AS_SPECTATOR` | Eliminated players become dungeon spectators. | | `ELIMINATE_TO_EXIT` | Eliminated players are sent to the dungeon exit. | `scope: PLAYER` gives each player their own lives. `scope: TEAM` makes lives shared by the party.", "url": "configuration/index.html#death-behavior"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Timer Bossbar", "snippet": "timer-bossbar: enabled: true color: GREEN style: SOLID show-time-left: true", "text": "timer-bossbar: enabled: true color: GREEN style: SOLID show-time-left: true", "url": "configuration/index.html#timer-bossbar"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Timer Alerts", "snippet": "timer-alerts: 10-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 5-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 1-minute: enabled: true sound: ENTITY_EX...", "text": "timer-alerts: 10-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 5-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 1-minute: enabled: true sound: ENTITY_EXPERIENCE_ORB_PICKUP", "url": "configuration/index.html#timer-alerts"}, {"group": "Configuration", "title": "Objectives", "section": "Objectives", "snippet": "Every dungeon completes through one objective type: completion-objective: BOSS or: completion-objective: TRIGGER", "text": "Every dungeon completes through one objective type: completion-objective: BOSS or: completion-objective: TRIGGER", "url": "objectives/index.html"}, {"group": "Configuration", "title": "Objectives", "section": "Boss Objective", "snippet": "Boss dungeons use: dungeons/&lt;id&gt;/boss.yml Set the boss spawn in editor mode: /dungeon edit dragon_lair /dungeon setboss Common config: boss: must-die-to-complete: tr...", "text": "Boss dungeons use: dungeons/<id>/boss.yml Set the boss spawn in editor mode: /dungeon edit dragon_lair /dungeon setboss Common config: boss: must-die-to-complete: true countdown-after-death: 30 When `must-die-to-complete` is `true`, the dungeon completion countdown starts after the boss dies.", "url": "objectives/index.html#boss-objective"}, {"group": "Configuration", "title": "Objectives", "section": "Trigger Objective", "snippet": "Trigger dungeons use: dungeons/&lt;id&gt;/trigger.yml Set the trigger item and place it in the template world: /dungeon edit puzzle_room /dungeon settrigger STONE_BUTTON S...", "text": "Trigger dungeons use: dungeons/<id>/trigger.yml Set the trigger item and place it in the template world: /dungeon edit puzzle_room /dungeon settrigger STONE_BUTTON Supported trigger blocks are Minecraft buttons and pressure plates. Example: material: STONE_BUTTON location: world: \"puzzle_template\" x: 120 y: 65 z: 220 rewards: enabled: true items: - type: VANILLA item: DIAMOND amount: 2 chance: 100.0 Only one trigger can exist per dungeon. Placing a new trigger replaces the previous one. Trigger blocks ignore normal dungeon interaction blocking. They can still complete the run when regular interactions are disabled.", "url": "objectives/index.html#trigger-objective"}, {"group": "Configuration", "title": "Towers", "section": "Towers", "snippet": "Tower dungeons chain multiple dungeon templates into one run. dungeon-type: tower tower-stage-type: first next-dungeon: &quot;tower_final&quot;", "text": "Tower dungeons chain multiple dungeon templates into one run. dungeon-type: tower tower-stage-type: first next-dungeon: \"tower_final\"", "url": "towers/index.html"}, {"group": "Configuration", "title": "Towers", "section": "Stage Types", "snippet": "| `first` | Entry point. Can be opened by command and may have entry costs. | | `last` | Final tower dungeon. Completing it completes the tower. |", "text": "| `first` | Entry point. Can be opened by command and may have entry costs. | | `last` | Final tower dungeon. Completing it completes the tower. |", "url": "towers/index.html#stage-types"}, {"group": "Configuration", "title": "Towers", "section": "Free Version Limit", "snippet": "The free version supports: FIRST -&gt; LAST", "text": "The free version supports: FIRST -> LAST", "url": "towers/index.html#free-version-limit"}, {"group": "Configuration", "title": "Towers", "section": "Behavior", "snippet": "Players open only the `FIRST` dungeon directly. Completing `FIRST` moves the same party into `next-dungeon`. `FIRST` uses tower transition messages instead of normal...", "text": "Players open only the `FIRST` dungeon directly. Completing `FIRST` moves the same party into `next-dungeon`. `FIRST` uses tower transition messages instead of normal completion messages. Completing `LAST` completes the tower and sends players to exit. Failure in any tower stage fails the whole tower. Entry costs are allowed only on `FIRST`.", "url": "towers/index.html#behavior"}, {"group": "Configuration", "title": "Towers", "section": "Announcements", "snippet": "Tower global announcements are controlled by the entry dungeon. # In the FIRST dungeon config announce-complete: true announce-fail: true `announce-complete` is broa...", "text": "Tower global announcements are controlled by the entry dungeon. # In the FIRST dungeon config announce-complete: true announce-fail: true `announce-complete` is broadcast only after the final tower stage completes. The broadcast uses the final stage dungeon name. Set `announce-complete` in the FIRST dungeon. The same setting in LAST does not control tower announcements.", "url": "towers/index.html#announcements"}, {"group": "Configuration", "title": "Towers", "section": "Spectators During Tower Transitions", "snippet": "Players who become dungeon spectators through death or sacrifice stay with the party as spectators when the tower moves to the next stage. External spectators from `...", "text": "Players who become dungeon spectators through death or sacrifice stay with the party as spectators when the tower moves to the next stage. External spectators from `/dungeon spectate <leader>` move to the next stage with the party. Their original inventory and game mode are restored when they stop spectating or the run ends.", "url": "towers/index.html#spectators-during-tower-transitions"}, {"group": "Configuration", "title": "Towers", "section": "Visibility", "snippet": "`/dungeon list` and `/dungeon open` tab completion hide tower last-stage dungeon IDs. Players reach those dungeons through tower progression.", "text": "`/dungeon list` and `/dungeon open` tab completion hide tower last-stage dungeon IDs. Players reach those dungeons through tower progression.", "url": "towers/index.html#visibility"}, {"group": "Configuration", "title": "Complete Reference", "section": "Complete Reference", "snippet": "InstancedDungeons is a Paper plugin for creating isolated dungeon runs from template worlds. Each party gets a copied instance world, independent mobs, loot, objecti...", "text": "InstancedDungeons is a Paper plugin for creating isolated dungeon runs from template worlds. Each party gets a copied instance world, independent mobs, loot, objectives, stages, timers, protection rules, and cleanup after the run ends.", "url": "complete-reference/index.html"}, {"group": "Configuration", "title": "Complete Reference", "section": "Table of Contents", "snippet": "Requirements Installation Core Concepts Quick Start Commands Permissions Dungeon Config Boss Objectives Trigger Objectives Towers Spawners Loot Chests Boss Rewards E...", "text": "Requirements Installation Core Concepts Quick Start Commands Permissions Dungeon Config Boss Objectives Trigger Objectives Towers Spawners Loot Chests Boss Rewards Entry Costs Parties and Instances Lives and Death Behavior Stages and Gates Stage Missions Event Commands Messages and Placeholders Validation Free Version Limits Compatibility Notes Troubleshooting", "url": "complete-reference/index.html#table-of-contents"}, {"group": "Configuration", "title": "Complete Reference", "section": "Requirements", "snippet": "| Paper 1.21.x | Java 21+ | Built-in (/dg world) | | Paper 26.1.x / 26.2.x / 26.3.x | Java 25+ | Built-in (/dg world) | One universal plugin JAR supports both Paper ...", "text": "| Paper 1.21.x | Java 21+ | Built-in (/dg world) | | Paper 26.1.x / 26.2.x / 26.3.x | Java 25+ | Built-in (/dg world) | One universal plugin JAR supports both Paper 1.21.x and Paper 26.1.x / 26.2.x / 26.3.x. Optional integrations: WorldGuard for copying template world regions and flags into dungeon instances. MythicMobs 5.0+ for custom mobs and bosses. MythicMobs item support through `MYTHIC_ITEM` entries. ItemsAdder 3.0+ for custom items. Oraxen custom item support. Nexo custom item support. Vault plus an economy plugin for money entry costs and stage money missions.", "url": "complete-reference/index.html#requirements"}, {"group": "Configuration", "title": "Complete Reference", "section": "Installation", "snippet": "Stop the server. Install the required Multiverse-Core version. Place `InstancedDungeons.jar` in `plugins/`. Start the server once so configs are generated. Configure...", "text": "Stop the server. Install the required Multiverse-Core version. Place `InstancedDungeons.jar` in `plugins/`. Start the server once so configs are generated. Configure dungeons in `plugins/InstancedDungeons/dungeons/`. Use `/dungeon reload` after YAML edits.", "url": "complete-reference/index.html#installation"}, {"group": "Configuration", "title": "Complete Reference", "section": "Core Concepts", "snippet": "Template world: the original world that admins build in. It is copied for every run. Instance world: the temporary copied world used by one active party. Dungeon ID:...", "text": "Template world: the original world that admins build in. It is copied for every run. Instance world: the temporary copied world used by one active party. Dungeon ID: folder name under `dungeons/<id>`. This is used by commands, permissions, towers, and event commands. Party: players open or join a party before entering. Parties stay tracked while the run is active and close only after completion, failure, or abandonment cleanup. Objective: the condition that completes a dungeon. Supported objective types are `BOSS` and `TRIGGER`. Stage: an optional progression gate inside a dungeon. A stage can require missions before its gate opens. Tower: a chain of dungeons. The free version supports a two-step tower: `FIRST -> LAST`.", "url": "complete-reference/index.html#core-concepts"}, {"group": "Configuration", "title": "Complete Reference", "section": "Quick Start", "snippet": "Create a boss dungeon: /dg world create dragon_template /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon setexit...", "text": "Create a boss dungeon: /dg world create dragon_template /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon setexit /dungeon setboss /dungeon save /dungeon reload Create a trigger dungeon: /dungeon create puzzle_room puzzle_template trigger /dungeon edit puzzle_room /dungeon setspawn /dungeon setexit /dungeon settrigger STONE_BUTTON /dungeon save /dungeon reload Start as a player: /dungeon open dragon_lair /dungeon join <code> /dungeon start", "url": "complete-reference/index.html#quick-start"}, {"group": "Configuration", "title": "Complete Reference", "section": "Commands", "snippet": "Player commands: | `/dungeon help` | Shows player and admin help. | | `/dungeon list` | Lists available dungeons. Tower last-stage dungeons are hidden. | | `/dungeon...", "text": "Player commands: | `/dungeon help` | Shows player and admin help. | | `/dungeon list` | Lists available dungeons. Tower last-stage dungeons are hidden. | | `/dungeon open <id>` | Creates a party for a dungeon. Only standalone dungeons and tower `FIRST` stages are suggested/openable directly. | | `/dungeon join <code>` | Joins an open party. | | `/dungeon leave` | Leaves an open party. | | `/dungeon start` | Starts the party dungeon as the leader. | | `/dungeon exit` | Leaves the current dungeon instance. | | `/dungeon spectate <leader>` | Spectates the active dungeon led by that party leader. | | `/dungeon spectator exit` | Leaves external spectator mode and restores inventory/gamemode. | Admin commands: | `/dungeon create <id> <template-world> <boss\\|trigger>` | Creates a dungeon using the current config format. | | `/dungeon edit <id>` | Enters editor mode. Template teleport is controlled by `editor.teleport-to-template-on-edit` in `config.yml`. | | `/dungeon save` | Exits editor mode. | | `/dungeon setspawn` | Sets the dungeon spawn in editor mode. | | `/dungeon setexit` | Sets the exit location. | | `/dungeon setboss` | Sets the boss spawn for boss-objective dungeons. | | `/dungeon boss reward edit` | Opens the boss reward editor GUI. | | `/dungeon settrigger <button\\|pressure_plate>` | Gives the trigger block item for trigger-objective dungeons. | | `/dungeon trigger reward edit` | Opens the trigger reward editor GUI. | | `/dungeon addspawner <id>` | Creates a spawner config at the admin location. | | `/dungeon addlootchest <id>` | Creates a loot chest config. | | `/dungeon lootchest give <id>` | Gives a placeable loot chest item. | | `/dungeon lootchest loot <id> add` | Adds the item in your main hand to the loot chest config. Works only in editor mode. | | `/dungeon addcost` | Opens the entry cost editor. | | `/dungeon validate <id>` | Validates one dungeon and prints a summary. | | `/dungeon validate all` | Validates every dungeon. | | `/dungeon reload` | Reloads configs and validation. | | `/dungeon instances` | Shows active parties and instances. | | `/dg status` | Shows supported integration plugins, detected versions, and economy hook status. | | `/dungeon mythicmob [mobId]` | Lists or checks MythicMobs mob IDs. | | `/dungeon mythicitem [itemId]` | Lists or checks MythicMobs item IDs for `MYTHIC_ITEM` config entries. | | `/dungeon itemsadder [itemId]` | Lists or checks ItemsAdder IDs. | | `/dungeon oraxen [itemId]` | Lists or checks Oraxen IDs. | | `/dungeon nexo [itemId]` | Lists or checks Nexo IDs. | | `/dungeon delete <id>` | Deletes a dungeon after confirmation. | Stage commands: | `/dungeon stage create <stage_id>` | Creates a stage file. | | `/dungeon stage list` | Lists stages in the current editor dungeon with order, gate block count, and mission count. | | `/dungeon stage <stage_id> order <number>` | Moves a stage to another order. Multiple stages may share the same order and run in parallel. | | `/dungeon stage <stage_id> delete` | Deletes a stage after confirmation, including its missions, hologram config, gate blocks, and active gate edit session. | | `/dungeon stage <stage_id> gate create` | Starts gate block creation mode. | | `/dungeon stage <stage_id> gate edit` | Edits existing gate blocks. | | `/dungeon stage <stage_id> gate delete` | Deletes a gate after confirmation. | | `/dungeon stage <stage_id> gate stick` | Gives a gate edit stick during gate create/edit mode. Left-click adds one existing block, right-click removes one selected gate block, and sneak-click affects connected same-material blocks. | | `/dungeon gate save` | Saves the active gate edit session. | | `/dungeon stage <stage_id> gate hologram create` | Adds a stage hologram at your location in the dungeon template world. | | `/dungeon stage <stage_id> gate hologram delete` | Removes the nearest hologram for that stage within 3 blocks. | | `/dg stage <stage_id> mission region` | Creates the mission and shows the corner-selection commands. | | `/dg stage <stage_id> mission region pos1` | Saves your current template-world block as corner 1. | | `/dg stage <stage_id> mission region pos2` | Saves your current template-world block as corner 2. | | `/dg stage <stage_id> mission region delete` | Removes the region mission. | | `/dungeon stage <stage_id> mission lever` | Gives a mission lever. | | `/dungeon stage <stage_id> mission button <material>` | Gives a mission button. | | `/dungeon stage <stage_id> mission pressure_plate <material>` | Gives a mission pressure plate. | Loot chest IDs, dungeon IDs, stage IDs, trigger materials, mission materials, and validation targets are completed where the command supports them. `/dungeon open` completion hides tower last-stage dungeon IDs because those stages are entered only through tower progression.", "url": "complete-reference/index.html#commands"}, {"group": "Configuration", "title": "Complete Reference", "section": "Permissions", "snippet": "| `instanceddungeons.admin` | op | Admin/editor commands and admin-only warnings. | | `instanceddungeons.open` | true | Allows `/dungeon open`. | | `instanceddungeon...", "text": "| `instanceddungeons.admin` | op | Admin/editor commands and admin-only warnings. | | `instanceddungeons.open` | true | Allows `/dungeon open`. | | `instanceddungeons.join` | true | Allows `/dungeon join`. | | `instanceddungeons.open.<dungeon_id>` | true | Allows opening a specific dungeon. | | `instanceddungeons.join.<dungeon_id>` | true | Allows joining a specific dungeon. | | `instanceddungeons.spectate` | true | Allows spectator commands. | | `instanceddungeons.bypass.cost` | op | Bypasses item and money entry costs. | | `instanceddungeons.bypass.limit` | op | Bypasses normal active-instance start checks. | Both global and dungeon-specific open/join permissions must allow the action.", "url": "complete-reference/index.html#permissions"}, {"group": "Configuration", "title": "Complete Reference", "section": "Global Config", "snippet": "Main file: plugins/InstancedDungeons/config.yml Useful global options: debug: false editor: teleport-to-template-on-edit: false instances: max-active-global: 0 templ...", "text": "Main file: plugins/InstancedDungeons/config.yml Useful global options: debug: false editor: teleport-to-template-on-edit: false instances: max-active-global: 0 template-worlds: freeze-ticks: true freeze-time: true freeze-weather: true natural-mob-spawning: false `debug` enables additional console logging, including gate block add/remove messages while an admin is building gates. `editor.teleport-to-template-on-edit` controls `/dungeon edit <id>` teleport behavior. When `true`, the admin is teleported to the dungeon spawn if it is configured, otherwise to the template world's spawn. When `false`, editor mode starts without moving the admin. In the free edition, `instances.max-active-global` is always capped at 6. A value of `0` means \"use the free-edition cap\", not unlimited. Values below 6 can lower the server limit, but values above 6 are reduced to 6. Tower transitions reserve the current global instance slot while the next tower stage is being prepared. This prevents another party from taking the slot during the short handoff between tower stages. Instance world cleanup: Every dungeon run creates a temporary instance world copied from the template world. Normal completion, failure, abandon, and shutdown paths unload and delete the temporary world. The plugin marks the instance worlds it creates so cleanup can identify them. Automatic cleanup checks for leftover instance worlds in the background. Automatic cleanup deletes only worlds identified by an instance marker or an exact plugin world registration. Unmarked legacy folders are not automatically deleted. Worlds with players inside are skipped.", "url": "complete-reference/index.html#global-config"}, {"group": "Configuration", "title": "Complete Reference", "section": "Dungeon Config", "snippet": "Main file: plugins/InstancedDungeons/dungeons/&lt;id&gt;/config.yml Important top-level fields: v: 2.0 dungeon-type: single tower-stage-type: first next-dungeon: &quot;&quot; comple...", "text": "Main file: plugins/InstancedDungeons/dungeons/<id>/config.yml Important top-level fields: v: 2.0 dungeon-type: single tower-stage-type: first next-dungeon: \"\" completion-objective: BOSS display-name: \"dragon_lair\" template-world: \"dragon_template\" max-players: 5 min-players: 1 time-limit: 1800 max-instances: 3 difficulty: NORMAL `dungeon-type` can be `single` or `tower`. `tower-stage-type` accepts `first` or `last`. `completion-objective` can be `BOSS` or `TRIGGER`. Protection: allow-block-break: false allow-block-place: false allow-fluid-place: false allow-fluid-take: false allow-interactions: true allow-party-pvp: true allow-fly: false fire-spread: false tnt-mode: VANILLA Allowing block breaking, block placement, or fluid placement does not remove protection from dungeon-owned gameplay blocks. Gates, mission blocks, completion triggers, and loot chests cannot be broken or replaced, and fluid flow is cancelled before reaching them. `allow-fly: true` leaves flight already granted by a game mode, permission, or another plugin untouched. It never grants flight by itself. `false` forces flight off for active Survival and Adventure dungeon players and restores their previous flight state when they leave the dungeon. Creative and Spectator modes are exempt. `tnt-mode` options: `VANILLA`: normal TNT behavior. `ONLY_DMG`: TNT deals damage but does not break blocks. `DISABLED`: TNT is blocked. `fire-spread: false` disables fire spreading in the template world and copied instances. Set it to `true` to allow spreading. Older 1.21.x uses `doFireTick`; from 1.21.11 the plugin uses `minecraft:fire_spread_radius_around_player`, with zero to disable spreading. Item restrictions: item-restrictions: block-elytra: false block-ender-pearls: false block-chorus-fruit: false block-enchanted-golden-apples: false block-wind-charges: false block-firework-rockets: false block-mace: false block-trident: false All values default to `false`. See [Dungeon Config](configuration.md#item-restrictions) for the behavior controlled by each field. Timer: timer-bossbar: enabled: true color: GREEN style: SOLID show-time-left: true timer-alerts: 10-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 5-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 1-minute: enabled: true sound: ENTITY_EXPERIENCE_ORB_PICKUP Validation warnings: validation-warnings: chat: true Console validation warnings are always logged. Chat validation warnings are sent only to admins and can be disabled per dungeon.", "url": "complete-reference/index.html#dungeon-config"}, {"group": "Configuration", "title": "Complete Reference", "section": "Boss Objectives", "snippet": "Boss dungeons are created with: /dungeon create &lt;id&gt; &lt;template-world&gt; boss Use `/dungeon setboss` to create or update `boss.yml` at your location. Boss completion be...", "text": "Boss dungeons are created with: /dungeon create <id> <template-world> boss Use `/dungeon setboss` to create or update `boss.yml` at your location. Boss completion behavior: boss: must-die-to-complete: true countdown-after-death: 30 `must-die-to-complete` defaults to `true` in new configs. Boss reward editing: /dungeon boss reward edit The GUI stores every slot as an independent reward entry. For example, 4 diamonds in one slot and 2 diamonds in another slot become two separate rewards and can have different chances in config.", "url": "complete-reference/index.html#boss-objectives"}, {"group": "Configuration", "title": "Complete Reference", "section": "Trigger Objectives", "snippet": "Trigger dungeons are created with: /dungeon create &lt;id&gt; &lt;template-world&gt; trigger Trigger dungeons do not generate a boss file. Instead, they use: dungeons/&lt;id&gt;/trigg...", "text": "Trigger dungeons are created with: /dungeon create <id> <template-world> trigger Trigger dungeons do not generate a boss file. Instead, they use: dungeons/<id>/trigger.yml The trigger is placed with: /dungeon settrigger <material> Supported trigger materials are Minecraft buttons and pressure plates. The trigger ignores dungeon interaction blocking so it can complete the run even when normal interactions are disabled. Only one trigger can exist per dungeon. Placing a new trigger replaces the previous one. After activation, the trigger is completed and further clicks do not run completion again. Trigger reward editing: /dungeon trigger reward edit Trigger rewards are saved in `trigger.yml` under `rewards`.", "url": "complete-reference/index.html#trigger-objectives"}, {"group": "Configuration", "title": "Complete Reference", "section": "Towers", "snippet": "Tower dungeons chain multiple dungeon templates. dungeon-type: tower tower-stage-type: first next-dungeon: &quot;tower_final&quot; Stage types: `first`: entry point. Can be op...", "text": "Tower dungeons chain multiple dungeon templates. dungeon-type: tower tower-stage-type: first next-dungeon: \"tower_final\" Stage types: `first`: entry point. Can be opened by command and may have entry costs. `last`: final tower dungeon. Completing it finishes the tower. Free version tower limit: Only two tower dungeons are supported: `FIRST -> LAST`. Free-limit warnings are sent only to admins. Tower behavior: Completing `FIRST` teleports the same party to `next-dungeon`. `FIRST` uses tower transition messages instead of normal dungeon completion messages. Global tower completion/failure announcements use the `announce-*` settings from the tower entry dungeon (`FIRST`) only. `announce-complete` is broadcast only after the final tower stage completes, and the announcement uses the final stage dungeon name. Dungeon players who became spectators through death or sacrifice stay spectators when the party moves to the next tower stage. Entry costs are allowed only on `FIRST`. Failure in any tower stage fails the whole tower and teleports players to that stage's exit.", "url": "complete-reference/index.html#towers"}, {"group": "Configuration", "title": "Complete Reference", "section": "Spawners", "snippet": "Spawner files live in: dungeons/&lt;id&gt;/spawners/&lt;spawner_id&gt;.yml Example: location: world: dragon_template x: 100.5 y: 64.0 z: 200.5 trigger: ON_PLAYER_NEAR trigger-di...", "text": "Spawner files live in: dungeons/<id>/spawners/<spawner_id>.yml Example: location: world: dragon_template x: 100.5 y: 64.0 z: 200.5 trigger: ON_PLAYER_NEAR trigger-distance: 20 trigger-time: 5 lifetime-behavior: PERSIST lifetime-seconds: 0 mob-pools: - type: VANILLA mob-id: ZOMBIE count: 5 chance: 100.0 - type: MYTHIC mob-id: SkeletonKing count: 1 chance: 35.0 Trigger modes: `ON_START`: spawn when the instance starts. This mode is not recommended for regular spawners because it can spawn every configured mob immediately at dungeon startup; prefer `ON_PLAYER_NEAR` for normal gameplay. `ON_PLAYER_NEAR`: spawn when a player enters `trigger-distance`. `ON_DELAY`: spawn after `trigger-time`. `ON_PLAYER_NEAR_ON_DELAY`: start `trigger-time` after a player enters `trigger-distance`. Spawners default to `ON_PLAYER_NEAR` with `trigger-distance: 20`. The selected trigger determines whether `trigger-distance`, `trigger-time`, or both apply. Mob pools can mix vanilla and MythicMobs entries in one spawner.", "url": "complete-reference/index.html#spawners"}, {"group": "Configuration", "title": "Complete Reference", "section": "Mob Lifetime", "snippet": "lifetime-behavior: PERSIST lifetime-seconds: 0 `PERSIST` and `PERSIST_UNTIL_DUNGEON_END` prevent natural distance despawning during the instance. This also applies t...", "text": "lifetime-behavior: PERSIST lifetime-seconds: 0 `PERSIST` and `PERSIST_UNTIL_DUNGEON_END` prevent natural distance despawning during the instance. This also applies to `ON_START` mobs spawned far from players. Entities are saved across chunk unloading and reloading. Both modes still remove mobs when the instance is cleaned up or its world is deleted; neither keeps an instance running after it ends. `DESPAWN_AFTER_TIME` removes the mob after a positive `lifetime-seconds` duration. Its deadline is retained through chunk unloading and mob transformations. Keep `lifetime-seconds` positive when using this mode. These settings cover Vanilla and MythicMobs spawned by the dungeon. Another plugin that explicitly removes an entity can still remove it.", "url": "complete-reference/index.html#mob-lifetime"}, {"group": "Configuration", "title": "Complete Reference", "section": "Loot Chests", "snippet": "Loot chest files live in: dungeons/&lt;id&gt;/loot-chests/&lt;loot_id&gt;.yml Use: /dungeon addlootchest treasure_room /dungeon lootchest give treasure_room /dungeon lootchest l...", "text": "Loot chest files live in: dungeons/<id>/loot-chests/<loot_id>.yml Use: /dungeon addlootchest treasure_room /dungeon lootchest give treasure_room /dungeon lootchest loot treasure_room add `/dungeon lootchest loot <id> add` adds the item in your main hand to the loot table. It detects vanilla items, supported custom item providers, potions, tipped arrows, and enchanted books. The new entry uses `min-amount: 1`, `max-amount: 1`, and `chance: 100.0`. Example: min-items-per-drop: 2 max-items-per-drop: 4 loot-table: - type: VANILLA item: DIAMOND min-amount: 1 max-amount: 3 chance: 75.0 - type: ITEMSADDER item: coins:bronze_coin min-amount: 1 max-amount: 3 chance: 25.0 Supported item providers: `VANILLA` `ITEMSADDER` `ORAXEN` `NEXO` `MYTHIC_ITEM` `MISSION`, for stage keys Mission key loot entry: # - type: MISSION # item: KEY # stage: 1 # quantity: 1 # lore: # - \"&7A key used to unlock a dungeon stage.\" `MISSION KEY` entries are guaranteed key supply entries, not random loot rolls. They ignore `chance` and do not count toward `min-items-per-drop` or `max-items-per-drop`. `quantity` means how many keys this loot chest definition should provide per dungeon instance. When an instance starts, the plugin chooses random physical loot chests of that loot chest ID and assigns the keys to those chests. If chunks are not loaded yet, the assignment is refreshed shortly after start and can fall back to the opened chest of the matching loot chest ID. If `quantity` is higher than the number of physical chests of that ID, selected chests can contain more than one key. Free version example: if a `REQUIRED_KEY` mission needs 1 key, configure the stage mission with `required: 1`, then put `quantity: 1` in the loot chest config that should provide the key. Mission key loot entries should normally be in loot chests reachable before the related gate. Mission keys are bound to the instance where they dropped and are removed when the player leaves that instance.", "url": "complete-reference/index.html#loot-chests"}, {"group": "Configuration", "title": "Complete Reference", "section": "Boss Rewards", "snippet": "Boss rewards are configured per dungeon and support custom items from the same providers as loot where available. Reward entries are independent. Stacked items in se...", "text": "Boss rewards are configured per dungeon and support custom items from the same providers as loot where available. Reward entries are independent. Stacked items in separate GUI slots stay separate reward entries and can have separate chance values in the config. `reward-logic` controls whether rolled boss rewards go to inventories or form a public pile at the boss spawn. Recipient and delivery combinations are validated before the dungeon can open. See [Loot and Rewards](loot-and-rewards.md#boss-rewards). Edit boss rewards while editing a boss-objective dungeon: /dungeon boss reward edit Common fields: boss-rewards: enabled: true rewards: - type: VANILLA item: DIAMOND amount: 4 chance: 100.0", "url": "complete-reference/index.html#boss-rewards"}, {"group": "Configuration", "title": "Complete Reference", "section": "Trigger Rewards", "snippet": "Trigger rewards are configured in `dungeons/&lt;id&gt;/trigger.yml` and are distributed according to its `reward-logic` when the trigger completes the dungeon. Edit trigge...", "text": "Trigger rewards are configured in `dungeons/<id>/trigger.yml` and are distributed according to its `reward-logic` when the trigger completes the dungeon. Edit trigger rewards while editing a trigger-objective dungeon: /dungeon trigger reward edit The trigger reward GUI follows the same independent-entry behavior as boss rewards: separate inventory slots become separate reward entries with separate chances in config.", "url": "complete-reference/index.html#trigger-rewards"}, {"group": "Configuration", "title": "Complete Reference", "section": "Entry Costs", "snippet": "Entry costs are stored in the dungeon config: costs: money: 1000 items: - type: VANILLA item: DIAMOND amount: 2 If `require-all-players-pay` is `false`, the leader p...", "text": "Entry costs are stored in the dungeon config: costs: money: 1000 items: - type: VANILLA item: DIAMOND amount: 2 If `require-all-players-pay` is `false`, the leader pays. If it is `true`, every party member must meet the cost. Tower rule: only `FIRST` tower dungeons may have entry costs.", "url": "complete-reference/index.html#entry-costs"}, {"group": "Configuration", "title": "Complete Reference", "section": "Special Vanilla Item IDs", "snippet": "Special vanilla item IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. They can also be captured automatically fr...", "text": "Special vanilla item IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. They can also be captured automatically from the cost editor GUI, reward editor GUI, and `/dungeon lootchest loot <id> add`. Potions, splash potions, lingering potions, and tipped arrows use: - type: VANILLA item: POTION_LONG_POISON min-amount: 1 max-amount: 3 chance: 100.0 The first part is one of: `POTION` `SPLASH_POTION` `LINGERING_POTION` `TIPPED_ARROW` The effect part is one of: `LONG_` variants use Minecraft's extended-duration potion type. `STRONG_` variants use Minecraft's upgraded stronger potion type where vanilla provides one. NIGHT_VISION LONG_NIGHT_VISION INVISIBILITY LONG_INVISIBILITY LEAPING LONG_LEAPING STRONG_LEAPING FIRE_RESISTANCE LONG_FIRE_RESISTANCE SWIFTNESS LONG_SWIFTNESS STRONG_SWIFTNESS SLOWNESS LONG_SLOWNESS STRONG_SLOWNESS WATER_BREATHING LONG_WATER_BREATHING HEALING STRONG_HEALING HARMING STRONG_HARMING POISON LONG_POISON STRONG_POISON REGENERATION LONG_REGENERATION STRONG_REGENERATION STRENGTH LONG_STRENGTH STRONG_STRENGTH WEAKNESS LONG_WEAKNESS LUCK SLOW_FALLING LONG_SLOW_FALLING TURTLE_MASTER LONG_TURTLE_MASTER STRONG_TURTLE_MASTER INFESTED OOZING WEAVING WIND_CHARGED Examples: - type: VANILLA item: SPLASH_POTION_STRONG_HEALING min-amount: 1 max-amount: 1 chance: 100.0 - type: VANILLA item: TIPPED_ARROW_SLOW_FALLING min-amount: 4 max-amount: 8 chance: 50.0 Enchanted books use: ENCHANTED_BOOK_<ENCHANTMENT>_<LEVEL> Example: - type: VANILLA item: ENCHANTED_BOOK_SHARPNESS_4 min-amount: 1 max-amount: 1 chance: 100.0 The level cannot be higher than the vanilla max level of that enchantment. For example, `ENCHANTED_BOOK_SHARPNESS_5` is valid, but `ENCHANTED_BOOK_SHARPNESS_6` is rejected by validation. Common enchanted book IDs: ENCHANTED_BOOK_SHARPNESS_5 ENCHANTED_BOOK_PROTECTION_4 ENCHANTED_BOOK_EFFICIENCY_5 ENCHANTED_BOOK_UNBREAKING_3 ENCHANTED_BOOK_MENDING_1 ENCHANTED_BOOK_FORTUNE_3 ENCHANTED_BOOK_LOOTING_3 ENCHANTED_BOOK_POWER_5 ENCHANTED_BOOK_PIERCING_4 ENCHANTED_BOOK_DENSITY_5 Supported enchantment names are taken from the server enchantment registry. On the Paper 26.x build line this includes: PROTECTION FIRE_PROTECTION FEATHER_FALLING BLAST_PROTECTION PROJECTILE_PROTECTION RESPIRATION AQUA_AFFINITY THORNS DEPTH_STRIDER FROST_WALKER BINDING_CURSE SHARPNESS SMITE BANE_OF_ARTHROPODS KNOCKBACK FIRE_ASPECT LOOTING SWEEPING_EDGE EFFICIENCY SILK_TOUCH UNBREAKING FORTUNE POWER PUNCH FLAME INFINITY LUCK_OF_THE_SEA LURE LOYALTY IMPALING RIPTIDE CHANNELING MULTISHOT QUICK_CHARGE PIERCING DENSITY BREACH WIND_BURST MENDING VANISHING_CURSE SOUL_SPEED SWIFT_SNEAK LUNGE Special vanilla drops follow their vanilla stack limits. Potions, splash potions, lingering potions, and enchanted books are split into one-item stacks, while tipped arrows can stack normally up to their item stack limit. The cost and reward editors save enchanted non-book items as their base vanilla material.", "url": "complete-reference/index.html#special-vanilla-item-ids"}, {"group": "Configuration", "title": "Complete Reference", "section": "Parties and Instances", "snippet": "Party states in 2.0: `OPEN`: players can join and the leader can start. `PREPARING_START`: instance world is being prepared and countdown is running. `IN_DUNGEON`: p...", "text": "Party states in 2.0: `OPEN`: players can join and the leader can start. `PREPARING_START`: instance world is being prepared and countdown is running. `IN_DUNGEON`: players are inside an active run. `COMPLETED`: run completed and party is closing. `ABANDONED`: run failed or was abandoned and party is closing. Parties close when the run ends, the party times out or disbands, or the server shuts down. Players who are not part of the active instance are removed if they enter an instance world through external plugins, vehicles, teleports, or other non-dungeon mechanics.", "url": "complete-reference/index.html#parties-and-instances"}, {"group": "Configuration", "title": "Complete Reference", "section": "Remove a Party Member", "snippet": "`/dg kick &lt;player&gt;` removes a member from the leader&#x27;s open party. Tab completion suggests only other members of that party. The leader cannot kick themselves, playe...", "text": "`/dg kick <player>` removes a member from the leader's open party. Tab completion suggests only other members of that party. The leader cannot kick themselves, players outside the party, or anyone after dungeon preparation has begun. The removed player and the remaining party receive configurable messages. No extra permission is required beyond being that party's leader. Kicking removes the current membership; it does not ban the player from joining an open party again.", "url": "complete-reference/index.html#remove-a-party-member"}, {"group": "Configuration", "title": "Complete Reference", "section": "Lives and Death Behavior", "snippet": "Lives config: lives: scope: PLAYER amount: 0 `amount: 0` means unlimited lives. `scope: PLAYER` means each player has their own death counter. `scope: TEAM` means de...", "text": "Lives config: lives: scope: PLAYER amount: 0 `amount: 0` means unlimited lives. `scope: PLAYER` means each player has their own death counter. `scope: TEAM` means deaths are shared by the whole party. Death behavior: `INFINITE_RESPAWN`: respawn at the dungeon start when lives are unlimited. `ELIMINATE_AS_SPECTATOR`: after the configured player/team lives run out, eliminated players become dungeon spectators. `ELIMINATE_TO_EXIT`: after the configured player/team lives run out, eliminated players are sent to the dungeon exit. Legacy values `ONE_LIFE_SPECTATOR` and `ONE_LIFE_KICK` are still read for compatibility, but current configs should use the names above. Death announcements follow the configured lives scope. With `scope: PLAYER`, the party sees the dead player's remaining lives. With `scope: TEAM`, the party sees the remaining shared team lives. When lives reach zero, the message also reflects whether the player became a spectator or was sent to the exit. Death spectators and external spectators are different systems: Death spectators are still dungeon participants, but they are marked as eliminated and are excluded from alive-player checks and sacrifice mission target lists. If all real dungeon players are eliminated and `fail-if-all-players-dead: true`, the dungeon or tower fails. Death spectators keep items only when the dungeon or world death rules preserve their inventory. Items lost on death are not restored at the end of the run. Death spectators and sacrificed players who were original dungeon players are sent to the dungeon exit when they leave the run or when the run ends. External spectators who joined with `/dungeon spectate <leader>` are not participants, cannot progress missions, and receive their saved inventory/gamemode back when they exit or the run ends.", "url": "complete-reference/index.html#lives-and-death-behavior"}, {"group": "Configuration", "title": "Complete Reference", "section": "Stages and Gates", "snippet": "Stages live in: dungeons/&lt;id&gt;/stages/&lt;stage_id&gt;.yml dungeons/&lt;id&gt;/stages/&lt;stage_id&gt;-hologram.yml Every stage has an order: stage-id: entrance stage-order: 1 gate: di...", "text": "Stages live in: dungeons/<id>/stages/<stage_id>.yml dungeons/<id>/stages/<stage_id>-hologram.yml Every stage has an order: stage-id: entrance stage-order: 1 gate: disappear-seconds: 6 missions: - type: LEVER required: 1 # Saved at the bottom because large gates can contain many coordinates. gate-blocks: - x: 10 y: 64 z: 20 Stage orders are progression priorities. Order `1` is the lowest and unlocks first. Multiple stages may share the same order, which means they can be progressed in parallel. Higher order stages unlock only after every lower-order stage has opened. Used order groups must still be continuous: `1`, `2`, `3`, and so on. For example, using orders `1` and `3` without any order `2` is invalid. Use the stage file ID in admin commands, even when several stages share an order. For example: /dungeon stage entrance gate create Use `/dungeon stage list` in editor mode to see the current order. New stages get the next order automatically based on creation order. To change order without editing YAML, use: /dungeon stage <stage_id> order <number> If the target order is already used, the moved stage joins that order group instead of swapping. Stages with the same order can be completed in any order, but every stage in that order must open before the next order unlocks. Gate editing: /dungeon stage entrance gate create place gate blocks /dungeon gate save While gate edit mode is active, the action bar turns purple and selected gate blocks show subtle purple dust particles to admins editing that dungeon. Multiple admins can join the same stage gate edit session and work on the same gate together. During an active gate create/edit session, `/dungeon stage <stage_id> gate stick` gives an enchanted gate edit stick. Left-click adds the clicked existing block to the active gate without placing a new block. Right-click removes the clicked block from the active gate selection without breaking it. Sneak-left-click adds connected same-material blocks, and sneak-right-click removes connected same-material blocks from the selection. Split large connected-block selections into smaller operations. The final selection is still saved with `/dungeon gate save`. Manual block placement and breaking are tracked immediately. WorldEdit `//set` is also supported during active gate create/edit mode: after the command runs, the plugin reads the admin's current WorldEdit selection and adds every non-air block in that selection to the active gate selection. Split large WorldEdit selections into smaller operations. Changes made with vanilla `/setblock` and `/fill` near the gate are also detected. Replacing existing blocks with the same material through commands is still best handled by WorldEdit `//set` selection sync or the gate stick. Gate holograms: /dungeon stage entrance gate hologram create The hologram shows live mission progress. Completed missions turn green and receive the configured completed prefix. Clickable missions such as `SACRIFICE`, `MONEY_PAYMENT`, and `ITEM_PAYMENT` add an instruction line that explains who should right-click a gate block, for example `Leader must right-click a gate block for Sacrifice.` or per-mission action lines when multiple clickable missions are active. You can create multiple holograms for the same stage by running the create command again at another location. The delete command removes the nearest hologram for that stage within 3 blocks. Locked higher-order holograms show the missing previous stage names, for example `Complete Entrance first.` The create command must be run while standing in the dungeon template world. If editor mode is configured not to teleport admins automatically, move to the template world first before creating stage holograms. The hologram appears above your position. In editor mode, stage holograms are also visible in the template world. Previews show the title and configured missions, and refresh after hologram or mission changes. If the stage has no missions yet, only the hologram title is shown.", "url": "complete-reference/index.html#stages-and-gates"}, {"group": "Configuration", "title": "Complete Reference", "section": "Stage Missions", "snippet": "Free version limits: Maximum 2 stages per dungeon. Maximum 2 missions per stage. Maximum 1 sacrifice mission per dungeon. Maximum 1 money payment mission per dungeon...", "text": "Free version limits: Maximum 2 stages per dungeon. Maximum 2 missions per stage. Maximum 1 sacrifice mission per dungeon. Maximum 1 money payment mission per dungeon. Maximum 1 item payment mission per dungeon. Maximum 1 region mission per dungeon. Mission levers belonging to locked future stages cannot be pulled. They become available when their stage unlocks. Mission types: | `REGION` | Enter or remain in a selected cuboid, individually or as a party. | | `KILL_MOBS` | Party must kill a configured number of mobs. | | `LEVER` | Party must pull all placed mission levers. Free limit: 3 per stage. | | `BUTTON` | Party must press all mission buttons at the same time. Free limit: 3 per stage. | | `PRESSURE_PLATE` | Party must activate all mission plates at the same time. Free limit: 2 per stage. | | `REQUIRED_KEY` | Players must submit mission keys by right-clicking any block of the gate with the key in hand. `required` is the number of keys needed to unlock the gate. Free limit: 1 key required per stage. | | `TIME` | Waits a configured number of seconds after the active stage starts. | | `SACRIFICE` | Requires selecting players to eliminate through the mission GUI. Open it by right-clicking any block of the stage gate. `sacrifice-outcome` controls whether the sacrificed player becomes a spectator or is kicked out of the dungeon, independently from dungeon death behavior. `sacrifice-drop-items: false` keeps the player's inventory; `true` drops storage, armor, and offhand items on the ground. | | `MONEY_PAYMENT` | Requires a Vault money payment. Open it by right-clicking any block of the stage gate. Cannot be added unless Vault and an economy provider are detected. | | `ITEM_PAYMENT` | Requires configured items. Open it by right-clicking any block of the stage gate during a run. Configure required items with `/dungeon stage <stage_id> mission item_payment`, which opens an editor GUI and saves the inserted supported items into the stage config. Free limit: max 3 item types and max 1 item payment mission per dungeon. | Mission creation commands: /dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 /dg stage <stage_id> mission region pos2 /dg stage <stage_id> mission region delete /dungeon stage <stage_id> mission kill_mobs <amount> /dungeon stage <stage_id> mission lever /dungeon stage <stage_id> mission button <button_material> /dungeon stage <stage_id> mission pressure_plate <plate_material> /dungeon stage <stage_id> mission required_key <amount> /dungeon stage <stage_id> mission time <seconds> /dungeon stage <stage_id> mission sacrifice [LEADER_SELECTS|PARTY_VOTE|FIRST_PLAYER_DECISION] [drop_items] /dungeon stage <stage_id> mission money_payment <amount> [ANY_PLAYER|LEADER_ONLY] /dungeon stage <stage_id> mission item_payment /dungeon stage <stage_id> mission <type> delete The `ITEM_PAYMENT` command opens a 27-slot item editor. Add vanilla, ItemsAdder, Oraxen, Nexo, or MythicMobs items, then close it to save. Run the command again to edit the saved items. Set `payment-mode` to `ANY_PLAYER` or `LEADER_ONLY` in the stage config. Mission lever/button/pressure-plate blocks can be moved while in editor mode. Break the mission block to remove it from the stage, then place a new mission block where you want it. If the last block for that mission is removed, the mission is removed from the stage file too. Mission YAML is saved with only the fields that apply to that mission type: | `REGION` | `type`, `region`, optional `lore` | | `KILL_MOBS` | `type`, `required`, `only-dungeon-spawner-mobs`, `count-baby-variants` | | `LEVER` | `type`, `required`, `blocks` | | `BUTTON` | `type`, `required`, `blocks` | | `PRESSURE_PLATE` | `type`, `required`, `blocks` | | `REQUIRED_KEY` | `type`, `required` | | `TIME` | `type`, `duration-seconds` | | `SACRIFICE` | `type`, `required`, `sacrifice-mode`, `sacrifice-outcome`, `sacrifice-drop-items`, optional `lore` | | `MONEY_PAYMENT` | `type`, `payment-mode`, `money-amount`, optional `lore` | | `ITEM_PAYMENT` | `type`, `payment-mode`, `items`, optional `lore` | Mission GUI: Mission items cannot be moved. Sacrifice selection opens a second GUI with player heads. Sacrifice announces the chosen player. If the sacrificed player is the current leader, a random alive dungeon player becomes the new leader and the party is notified. The same leader reassignment is used when the leader loses all lives. Player-facing mission names come from `messages.yml` under `mission-names`. Config files and commands still use internal mission IDs such as `REQUIRED_KEY`. Each mission can define custom GUI icon lore with a `lore:` list in the stage file. Mission lore placeholders: `%mission%`, `%current%`, `%required%`, `%money%`, `%items%`. For `REQUIRED_KEY`, configure how many keys must be found in each loot chest type with `MISSION KEY` entries in the related loot chest configs. Example mission lore: missions: - type: MONEY_PAYMENT required: 1 payment-mode: ANY_PLAYER money-amount: 500 lore: - \"&7Pay &6500 &7coins to unlock the gate.\" - \"&8Progress: %current%/%required%\" Stage progress isolation: Only unlocked stages receive kill/time/payment progress. Stages with the same order can receive progress at the same time. Later stage holograms stay locked until every lower-order stage opens and show the missing previous stage names. If a player bypasses a gate, later holograms show the locked previous-stage message.", "url": "complete-reference/index.html#stage-missions"}, {"group": "Configuration", "title": "Complete Reference", "section": "Region Missions", "snippet": "A REGION mission uses a cuboid selected by two opposite block corners in the dungeon template. The corner blocks are included, and either selection order is accepted...", "text": "A REGION mission uses a cuboid selected by two opposite block corners in the dungeon template. The corner blocks are included, and either selection order is accepted. Progress starts only after the stage unlocks. /dg edit <dungeon_id> /dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 # move to the opposite corner in the template world /dg stage <stage_id> mission region pos2 Run `/dg stage <stage_id> mission region` first to add the mission. The confirmation shows the two commands for selecting its corners. Then stand at each corner in the template world and run `pos1` or `pos2`; each command saves your current block as that corner. Running the creation command again preserves the existing corners and settings. Do not use the generated instance world name in the stage config. In editor mode, cyan particles mark `pos1` and pink particles mark `pos2`. Markers are visible only to the editing admin within 50 blocks of a corner. missions: - type: REGION region: mode: ENTER_ONCE whole-party: false pos1: {x: 10, y: 60, z: 10} pos2: {x: 20, y: 70, z: 20} | `ENTER_ONCE` | Any participant enters once. | Each required participant enters once; their visits may happen at different times. | | `STAY_UNTIL_COMPLETE` | At least one participant is currently inside until all stage missions complete. | All required participants are inside at the same time until all stage missions complete. | Spectators do not count. A dead or offline participant does not count as currently inside. For the stay mode, the same player does not have to remain throughout: the configured number of participants must currently satisfy the condition. Leaving before the gate opens makes the stay condition incomplete again. Opening the gate finishes the stage permanently. With `whole-party: true`, the requirement uses the actual participants in the run, not the dungeon's maximum capacity. A solo run in a dungeon configured for 1–5 players requires only that solo player. In `STAY_UNTIL_COMPLETE`, the hologram shows the region as complete while the required participants are inside and returns to pending if they leave before the stage opens. The mission completion message and sound occur only when all stage missions are satisfied and the gate opens. In `ENTER_ONCE`, completion is announced as soon as the required visits are recorded and stays complete after players leave. Set `region.mode` and `region.whole-party` in the stage YAML. These settings have no command variants. Use `/dg stage <stage_id> mission region delete` to remove the mission. Validation rejects missing corners or invalid settings. One REGION mission is supported per dungeon.", "url": "complete-reference/index.html#region-missions"}, {"group": "Configuration", "title": "Complete Reference", "section": "Kill Mobs Filters", "snippet": "New `KILL_MOBS` missions include both options: missions: - type: KILL_MOBS required: 20 only-dungeon-spawner-mobs: true count-baby-variants: true `only-dungeon-spawn...", "text": "New `KILL_MOBS` missions include both options: missions: - type: KILL_MOBS required: 20 only-dungeon-spawner-mobs: true count-baby-variants: true `only-dungeon-spawner-mobs` counts only mobs spawned by this dungeon instance's configured spawners, including vanilla and MythicMobs pools. Friendly summons from enchantments or other plugins, natural mobs, and mobs already stored in the template do not count. Bosses remain excluded from stage kill missions. Dungeon-spawned mobs still count after transformations, such as a zombie becoming a drowned. Set `only-dungeon-spawner-mobs: false` to count mobs from other sources inside the instance. Kills must be credited to a player. Mobs summoned separately by a Mythic skill are not automatically treated as dungeon spawner mobs. `count-baby-variants` includes baby versions of eligible mobs, including zombies, drowned, piglins, and other ageable mobs. Set it to `false` to exclude babies. The spawner-source filter still applies. To control which variants spawn, use the spawner settings. Both options default to `true` when omitted, including in existing missions. Changing the required amount through a command or the editor preserves these filters. Save the mission to write the fields, or add them manually and reload.", "url": "complete-reference/index.html#kill-mobs-filters"}, {"group": "Configuration", "title": "Complete Reference", "section": "Event Commands", "snippet": "Event commands let server owners run commands when dungeon events happen. They are per dungeon and disabled by default. Admins configure them in each dungeon&#x27;s comma...", "text": "Event commands let server owners run commands when dungeon events happen. They are per dungeon and disabled by default. Admins configure them in each dungeon's command file: plugins/InstancedDungeons/dungeons/<dungeon_id>/commands.yml Default file: enabled: false default-executor: CONSOLE commands: # - event: on-player-death-command # executor: CONSOLE # audience: NONE # run: # - \"say <player> died in <dungeon_name>\" # # - event: on-player-death-command # executor: CONSOLE # audience: PARTY # run: # - \"tell <target> <player> died in <dungeon_name>\" # # - event: on-player-death-command # executor: CONSOLE # audience: ALIVE_PARTY # run: # - \"msg <target> <player> has died.\" # # - event: on-party-complete-dungeon-command # executor: CONSOLE # audience: NONE # run: # - \"broadcast <party_leader>'s party completed <dungeon_name>\" Set `enabled: true` and uncomment the entries you want to run. Executor: `CONSOLE`: runs command as console. `PLAYER`: runs command as the event player. Party events use the online party leader when available. Audience: `NONE`: no plugin targeting. The command runs once. Example: `executor: CONSOLE`, `audience: NONE`, and `say ...` broadcasts globally because Minecraft's `say` command is global. `PLAYER`: targets the event player and fills `<target>` with that player. `PARTY`: runs once per online dungeon party member and fills `<target>` for each member. External spectators are not included. `ALIVE_PARTY`: runs once per online non-eliminated dungeon player. `DEAD_PARTY`: runs once per online eliminated death spectator. `LEADER`: targets the party leader. Command format: Leading `/` is optional. Commands are skipped when the event is not configured. Run `/dungeon reload` after editing event commands. The `commands:` list may contain the same `event` more than once. This is the recommended way to run separate command groups or run the same trigger with different executor/audience combinations. Each entry can use its own `executor`; otherwise it uses `default-executor`. If `audience` is omitted, it defaults to `NONE`. If an audience other than `NONE` has no online targets, that command entry is skipped. Audience does not change how Minecraft commands behave. `say` is still global. Use commands such as `msg <target> ...` or `tell <target> ...` when you want only the selected audience to see a message. Player event keys: | `on-player-create-party-command` | Once for the player who creates a party with `/dungeon open <id>`. | | `on-player-join-party-command` | Once for the player who joins a party with `/dungeon join <code>`. | | `on-player-start-dungeon-command` | For each dungeon player when the instance starts and players enter the dungeon. | | `on-player-complete-dungeon-command` | For each active dungeon player when a single dungeon completes, or when the last tower dungeon completes. | | `on-player-abandon-dungeon-command` | For a player who leaves through an external/abandon flow before completion. | | `on-player-exit-dungeon-command` | When a player exits with `/dungeon exit`. | | `on-player-death-command` | When a dungeon player dies inside an active instance. | | `on-player-kill-mob-command` | When a dungeon player kills a regular dungeon mob. | | `on-player-kill-boss-command` | When a dungeon player kills the boss and Bukkit can resolve the killer. | | `on-player-complete-stage-command` | For each active dungeon player when the active stage is completed. | | `on-player-open-gate-command` | For each active dungeon player when a stage gate opens. | | `on-player-fail-dungeon-command` | For each active dungeon player when the dungeon or tower fails. | Party event keys: | `on-party-create-command` | Once when a party is created. | | `on-party-player-join-command` | Once when any player joins the party. Use this for party-wide scripts. | | `on-party-start-dungeon-command` | Once when the party enters the dungeon instance. | | `on-party-complete-dungeon-command` | Once when a single dungeon completes. In towers, this runs on the final dungeon only. | | `on-party-abandon-dungeon-command` | Reserved for full-party abandon flows before completion. | | `on-party-fail-dungeon-command` | Once when the dungeon or whole tower fails. | | `on-party-complete-stage-command` | Once when a stage is completed. | | `on-party-open-gate-command` | Once when a stage gate opens. | | `on-party-enter-tower-stage-command` | Once when the party enters the next tower dungeon after a transition. | | `on-party-complete-tower-command` | Once when the final tower dungeon completes. | Event placeholder reference: | `<player>` | Event player name. | | `<player_uuid>` | Event player UUID. | | `<executor>` | Configured command executor, `CONSOLE` or `PLAYER`. | | `<executor_player>` | Player executing the command when using `PLAYER`. | | `<executor_uuid>` | Executor player UUID when using `PLAYER`. | | `<audience>` | Configured audience. | | `<target>` | Current audience target player name. Empty when `audience: NONE`. | | `<target_uuid>` | Current audience target player UUID. Empty when `audience: NONE`. | | `<party_leader>` | Party leader name. | | `<party_code>` | Party code. | | `<party_size>` | Number of players in the party or active instance. | | `<dungeon_id>` | Dungeon folder ID. | | `<dungeon_name>` | Dungeon display name. | | `<template_id>` | Template world name. | | `<stage_id>` | Stage ID when the event is stage-related. | | `<stage_order>` | Stage order when available. | | `<tower_id>` | Tower context ID. | | `<mob_id>` | Killed mob type or ID when available. | | `<boss_id>` | Boss ID placeholder when available. | | `<world>` | Event player's current world. | | `<instance_world>` | Active instance world name when available. | | `<x>`, `<y>`, `<z>` | Event player's block coordinates. | Duplicate rules: Player events run once per affected player. Party events run once per party/run. `/dungeon exit` fires the exit event, not the abandon event. External teleports/leaves can fire abandon events. Stage gate open and stage complete are separate hooks so admins can script either moment.", "url": "complete-reference/index.html#event-commands"}, {"group": "Configuration", "title": "Complete Reference", "section": "Messages and Placeholders", "snippet": "Main messages file: plugins/InstancedDungeons/messages.yml Important placeholder styles: Messages use `%placeholder%`. Event commands use `&lt;placeholder&gt;`. The `missi...", "text": "Main messages file: plugins/InstancedDungeons/messages.yml Important placeholder styles: Messages use `%placeholder%`. Event commands use `<placeholder>`. The `mission-names` section controls player-facing mission labels used in mission completion messages, mission GUI names, hologram mission hints, and mission lore placeholders. Keep using mission IDs such as `KILL_MOBS` in configs and commands. New installations receive messages grouped by purpose, such as dungeon, instance and editor messages. Updates append missing new messages to existing files under: # Messages added by plugin updates will appear below. Existing messages are never overwritten. Existing messages, comments, order, and translations are preserved. Limit notices use fixed English text and are not configurable in `messages.yml`. `messages.yml` also includes a placeholder reference comment at the bottom.", "url": "complete-reference/index.html#messages-and-placeholders"}, {"group": "Configuration", "title": "Complete Reference", "section": "Validation", "snippet": "Use: /dungeon validate &lt;id&gt; /dungeon validate all /dungeon reload Validation checks include: Config version compatibility. Missing spawn/exit locations. Invalid obje...", "text": "Use: /dungeon validate <id> /dungeon validate all /dungeon reload Validation checks include: Config version compatibility. Missing spawn/exit locations. Invalid objective files. Invalid tower chain setup. Unsupported costs on final tower stages. Invalid spawner locations. Unknown mob IDs where they can be resolved. Unknown or unavailable custom item provider entries. Stage ordering and free-limit warnings. Loot chest and boss reward item definitions. `commands.yml` syntax, event keys, executors, audiences, command lists, and risky audience/global command combinations. Validation output: Console always receives validation output. Online admins receive chat validation warnings unless disabled per dungeon. Normal players do not receive free-version limit or validation warnings. If chat output is shortened, check the console because it may contain more validation details.", "url": "complete-reference/index.html#validation"}, {"group": "Configuration", "title": "Complete Reference", "section": "Free Version Limits", "snippet": "| Global active instances | 6 maximum, even if config is higher. | | Dungeon templates | 6 maximum. | | Managed template worlds (`/dg world create`) | 6 maximum (`fl...", "text": "| Global active instances | 6 maximum, even if config is higher. | | Dungeon templates | 6 maximum. | | Managed template worlds (`/dg world create`) | 6 maximum (`flat` generator without structures). | | Tower length | 2 dungeons: `FIRST -> LAST`. | | Stages per dungeon | 2. | | Missions per stage | 2. | | Lever mission blocks | 3 per stage. | | Button mission blocks | 3 per stage. | | Pressure plate mission blocks | 2 per stage. | | Required keys | 1 per stage. | | Sacrifice missions | 1 per dungeon. | | Money payment missions | 1 per dungeon. | | Item payment missions | 1 per dungeon. | | Item payment item types | 3 per mission. | | Region missions | 1 per dungeon. | Free-version limit notices are visible only to admins.", "url": "complete-reference/index.html#free-version-limits"}, {"group": "Configuration", "title": "Complete Reference", "section": "Optional RAM Analysis", "snippet": "`/dungeon ram analysis` toggles memory reports and requires `instanceddungeons.admin`. Reports estimate plugin and active-instance memory. See [RAM Analysis](ram-ana...", "text": "`/dungeon ram analysis` toggles memory reports and requires `instanceddungeons.admin`. Reports estimate plugin and active-instance memory. See [RAM Analysis](ram-analysis.md) for settings and report fields.", "url": "complete-reference/index.html#optional-ram-analysis"}, {"group": "Configuration", "title": "Complete Reference", "section": "Compatibility Notes", "snippet": "One universal JAR supports both Paper 1.21.x and Paper 26.1 / 26.2 / 26.3. Template world gamerules, WorldBorder settings, and WorldGuard regions/flags copy automati...", "text": "One universal JAR supports both Paper 1.21.x and Paper 26.1 / 26.2 / 26.3. Template world gamerules, WorldBorder settings, and WorldGuard regions/flags copy automatically to each dungeon instance. The update checker ignores Modrinth releases that do not list this server/API target in their game versions. Recreate dungeons that use the 1.x config format before using them with 2.x.", "url": "complete-reference/index.html#compatibility-notes"}, {"group": "Configuration", "title": "Complete Reference", "section": "Troubleshooting", "snippet": "Mobs do not spawn: Run `/dungeon validate &lt;id&gt;`. Check spawner location and trigger. Verify MythicMobs IDs if using `MYTHIC`. Ensure the template world is loaded. Lo...", "text": "Mobs do not spawn: Run `/dungeon validate <id>`. Check spawner location and trigger. Verify MythicMobs IDs if using `MYTHIC`. Ensure the template world is loaded. Loot chests are empty: Check `min-items-per-drop` and `max-items-per-drop`. Verify item provider and item IDs. Check chance values. Run `/dungeon reload` after edits. Dungeon will not start: Run `/dungeon validate <id>`. Check `v: 2.0`. Check spawn and exit locations. Check max instance limits. Check party size and offline members. Tower does not transition: Confirm `dungeon-type: tower`. Confirm `tower-stage-type`. Confirm `next-dungeon` points to a loaded dungeon. In the free version, use only `FIRST -> LAST`. Stage gate does not open: Confirm stage order is valid. Confirm all missions are complete. Confirm the hologram belongs to the same stage. Check that the gate was saved with `/dungeon gate save`. Custom items fail validation: Confirm the provider plugin is installed and enabled. Confirm the item ID exactly matches the provider ID. For potions and enchanted books, confirm the ID follows the special vanilla formats above.", "url": "complete-reference/index.html#troubleshooting"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Spawners and Mobs", "snippet": "Spawner files control regular dungeon mob waves. Boss-objective dungeons use the same mob pool format inside `boss.yml`. Spawner files live in: dungeons/&lt;id&gt;/spawner...", "text": "Spawner files control regular dungeon mob waves. Boss-objective dungeons use the same mob pool format inside `boss.yml`. Spawner files live in: dungeons/<id>/spawners/<spawner_id>.yml Create a spawner while editing a dungeon: /dungeon edit <dungeon_id> /dungeon addspawner <spawner_id> /dungeon save The command creates the spawner file at the admin's current location in the template world.", "url": "spawners-and-mobs/index.html"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Basic Spawner", "snippet": "location: world: dragon_template x: 100.5 y: 64.0 z: 200.5 trigger: ON_PLAYER_NEAR trigger-distance: 20 trigger-time: 5 lifetime-behavior: PERSIST lifetime-seconds: ...", "text": "location: world: dragon_template x: 100.5 y: 64.0 z: 200.5 trigger: ON_PLAYER_NEAR trigger-distance: 20 trigger-time: 5 lifetime-behavior: PERSIST lifetime-seconds: 0 mob-pools: - type: VANILLA mob-id: ZOMBIE count: 5 chance: 100.0 - type: MYTHIC mob-id: SkeletonKing count: 1 chance: 35.0", "url": "spawners-and-mobs/index.html#basic-spawner"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Trigger Modes", "snippet": "| `ON_START` | Spawns when the instance starts. This is usually not recommended for regular spawners because every configured mob can spawn immediately at dungeon st...", "text": "| `ON_START` | Spawns when the instance starts. This is usually not recommended for regular spawners because every configured mob can spawn immediately at dungeon startup. | | `ON_PLAYER_NEAR` | Spawns when a player enters `trigger-distance`. | | `ON_DELAY` | Spawns after `trigger-time`. | | `ON_PLAYER_NEAR_ON_DELAY` | Starts `trigger-time` after a player enters `trigger-distance`. | Spawners default to `ON_PLAYER_NEAR` with `trigger-distance: 20`. The selected trigger determines whether `trigger-distance`, `trigger-time`, or both apply.", "url": "spawners-and-mobs/index.html#trigger-modes"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Mob Lifetime", "snippet": "lifetime-behavior: PERSIST lifetime-seconds: 0 `PERSIST` and `PERSIST_UNTIL_DUNGEON_END` prevent natural distance despawning during the instance. This also applies t...", "text": "lifetime-behavior: PERSIST lifetime-seconds: 0 `PERSIST` and `PERSIST_UNTIL_DUNGEON_END` prevent natural distance despawning during the instance. This also applies to `ON_START` mobs spawned far from players. Entities are saved across chunk unloading and reloading. Both modes still remove mobs when the instance is cleaned up or its world is deleted; neither keeps an instance running after it ends. `DESPAWN_AFTER_TIME` removes the mob after a positive `lifetime-seconds` duration. Its deadline is retained through chunk unloading and mob transformations. Keep `lifetime-seconds` positive when using this mode. These settings cover Vanilla and MythicMobs spawned by the dungeon. Another plugin that explicitly removes an entity can still remove it.", "url": "spawners-and-mobs/index.html#mob-lifetime"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Mob Pools", "snippet": "Mob pools can mix vanilla and MythicMobs entries in the same spawner: mob-pools: - type: VANILLA mob-id: SKELETON count: 3 chance: 100.0 - type: MYTHIC mob-id: Dunge...", "text": "Mob pools can mix vanilla and MythicMobs entries in the same spawner: mob-pools: - type: VANILLA mob-id: SKELETON count: 3 chance: 100.0 - type: MYTHIC mob-id: DungeonKnight count: 1 chance: 25.0 | `type` | `VANILLA` or `MYTHIC`. | | `mob-id` | Bukkit entity type for vanilla mobs, MythicMobs mob ID for Mythic mobs. | | `count` | How many mobs this pool spawns when selected. | | `chance` | Percent chance from `0.0` to `100.0`. | Use `/dungeon mythicmob [mobId]` to list or check MythicMobs IDs when MythicMobs is installed.", "url": "spawners-and-mobs/index.html#mob-pools"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Boss Spawners", "snippet": "Boss dungeons use `/dungeon setboss` instead of `/dungeon addspawner`. /dungeon edit dragon_lair /dungeon setboss /dungeon save This creates or updates the boss spaw...", "text": "Boss dungeons use `/dungeon setboss` instead of `/dungeon addspawner`. /dungeon edit dragon_lair /dungeon setboss /dungeon save This creates or updates the boss spawner data for the boss objective. Boss mob pools use the same `VANILLA` and `MYTHIC` entry format as regular spawners.", "url": "spawners-and-mobs/index.html#boss-spawners"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Validation", "snippet": "Run validation after changing spawner files: /dungeon validate &lt;dungeon_id&gt; /dungeon validate all Validation checks spawner locations, trigger settings, mob pool dat...", "text": "Run validation after changing spawner files: /dungeon validate <dungeon_id> /dungeon validate all Validation checks spawner locations, trigger settings, mob pool data, and unavailable MythicMobs IDs where possible. Console output may contain more detail than chat.", "url": "spawners-and-mobs/index.html#validation"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Troubleshooting", "snippet": "If mobs do not spawn: Run `/dungeon validate &lt;dungeon_id&gt;`. Check that the spawner location is inside the template world. Check `trigger`, `trigger-distance`, and `t...", "text": "If mobs do not spawn: Run `/dungeon validate <dungeon_id>`. Check that the spawner location is inside the template world. Check `trigger`, `trigger-distance`, and `trigger-time`. Verify MythicMobs IDs if the pool uses `type: MYTHIC`. Make sure the template world is loaded.", "url": "spawners-and-mobs/index.html#troubleshooting"}, {"group": "Systems", "title": "Stages and Gates", "section": "Stages and Gates", "snippet": "Stages are optional progression gates inside a dungeon. Stage files live in: dungeons/&lt;id&gt;/stages/&lt;stage_id&gt;.yml dungeons/&lt;id&gt;/stages/&lt;stage_id&gt;-hologram.yml", "text": "Stages are optional progression gates inside a dungeon. Stage files live in: dungeons/<id>/stages/<stage_id>.yml dungeons/<id>/stages/<stage_id>-hologram.yml", "url": "stages/index.html"}, {"group": "Systems", "title": "Stages and Gates", "section": "Create a Stage", "snippet": "/dungeon edit dragon_lair /dungeon stage create entrance /dungeon stage entrance gate create # select gate blocks in the template world /dungeon gate save", "text": "/dungeon edit dragon_lair /dungeon stage create entrance /dungeon stage entrance gate create # select gate blocks in the template world /dungeon gate save", "url": "stages/index.html#create-a-stage"}, {"group": "Systems", "title": "Stages and Gates", "section": "Stage Order", "snippet": "Every stage has an order: stage-id: entrance stage-order: 1 Order `1` unlocks first. Higher orders unlock only after every lower-order stage opens. Multiple stages c...", "text": "Every stage has an order: stage-id: entrance stage-order: 1 Order `1` unlocks first. Higher orders unlock only after every lower-order stage opens. Multiple stages can share the same order. Shared-order stages run in parallel. /dungeon stage list /dungeon stage entrance order 2", "url": "stages/index.html#stage-order"}, {"group": "Systems", "title": "Stages and Gates", "section": "Gate Editing", "snippet": "Use gate mode to select existing blocks from the template world. /dungeon stage entrance gate create /dungeon stage entrance gate stick /dungeon gate save Gate stick...", "text": "Use gate mode to select existing blocks from the template world. /dungeon stage entrance gate create /dungeon stage entrance gate stick /dungeon gate save Gate stick controls: | Left-click | Adds one existing block. | | Right-click | Removes one selected block. | | Sneak-left-click | Adds connected same-material blocks. | | Sneak-right-click | Removes connected same-material blocks. |", "url": "stages/index.html#gate-editing"}, {"group": "Systems", "title": "Stages and Gates", "section": "Holograms", "snippet": "/dungeon stage entrance gate hologram create /dungeon stage entrance gate hologram delete You can create multiple holograms for the same stage. Delete removes the ne...", "text": "/dungeon stage entrance gate hologram create /dungeon stage entrance gate hologram delete You can create multiple holograms for the same stage. Delete removes the nearest hologram for that stage within 3 blocks. Runtime holograms show live mission progress. Locked higher-order holograms show which earlier stages still need to open.", "url": "stages/index.html#holograms"}, {"group": "Systems", "title": "Stages and Gates", "section": "Mission Types", "snippet": "| `REGION` | Enter or remain in a selected cuboid, individually or as a party. | | `KILL_MOBS` | Party must kill a configured number of mobs. | | `LEVER` | Party mus...", "text": "| `REGION` | Enter or remain in a selected cuboid, individually or as a party. | | `KILL_MOBS` | Party must kill a configured number of mobs. | | `LEVER` | Party must pull all mission levers. | | `BUTTON` | Party must press all mission buttons at the same time. | | `PRESSURE_PLATE` | Party must activate all mission plates at the same time. | | `REQUIRED_KEY` | Players submit mission keys by right-clicking the gate. | | `TIME` | Waits a configured number of seconds. | | `SACRIFICE` | Selects players to eliminate through the mission GUI. | | `MONEY_PAYMENT` | Requires a Vault money payment. | | `ITEM_PAYMENT` | Requires configured items through a GUI editor. | Mission levers belonging to locked future stages cannot be pulled. They become available when their stage unlocks.", "url": "stages/index.html#mission-types"}, {"group": "Systems", "title": "Stages and Gates", "section": "Region Missions", "snippet": "A REGION mission uses a cuboid selected by two opposite block corners in the dungeon template. The corner blocks are included, and either selection order is accepted...", "text": "A REGION mission uses a cuboid selected by two opposite block corners in the dungeon template. The corner blocks are included, and either selection order is accepted. Progress starts only after the stage unlocks. /dg edit <dungeon_id> /dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 # move to the opposite corner in the template world /dg stage <stage_id> mission region pos2 Run `/dg stage <stage_id> mission region` first to add the mission. The confirmation shows the two commands for selecting its corners. Then stand at each corner in the template world and run `pos1` or `pos2`; each command saves your current block as that corner. Running the creation command again preserves the existing corners and settings. Do not use the generated instance world name in the stage config. In editor mode, cyan particles mark `pos1` and pink particles mark `pos2`. Markers are visible only to the editing admin within 50 blocks of a corner. missions: - type: REGION region: mode: ENTER_ONCE whole-party: false pos1: {x: 10, y: 60, z: 10} pos2: {x: 20, y: 70, z: 20} | `ENTER_ONCE` | Any participant enters once. | Each required participant enters once; their visits may happen at different times. | | `STAY_UNTIL_COMPLETE` | At least one participant is currently inside until all stage missions complete. | All required participants are inside at the same time until all stage missions complete. | Spectators do not count. A dead or offline participant does not count as currently inside. For the stay mode, the same player does not have to remain throughout: the configured number of participants must currently satisfy the condition. Leaving before the gate opens makes the stay condition incomplete again. Opening the gate finishes the stage permanently. With `whole-party: true`, the requirement uses the actual participants in the run, not the dungeon's maximum capacity. A solo run in a dungeon configured for 1–5 players requires only that solo player. In `STAY_UNTIL_COMPLETE`, the hologram shows the region as complete while the required participants are inside and returns to pending if they leave before the stage opens. The mission completion message and sound occur only when all stage missions are satisfied and the gate opens. In `ENTER_ONCE`, completion is announced as soon as the required visits are recorded and stays complete after players leave. Set `region.mode` and `region.whole-party` in the stage YAML. These settings have no command variants. Use `/dg stage <stage_id> mission region delete` to remove the mission. Validation rejects missing corners or invalid settings. One REGION mission is supported across the entire dungeon, including all its stages. Other mission limits still apply. Extra REGION missions in manually edited configs are reported by validation; files are not deleted.", "url": "stages/index.html#region-missions"}, {"group": "Systems", "title": "Stages and Gates", "section": "Mission Commands", "snippet": "/dg stage &lt;stage_id&gt; mission region /dg stage &lt;stage_id&gt; mission region pos1 /dg stage &lt;stage_id&gt; mission region pos2 /dg stage &lt;stage_id&gt; mission region delete /dun...", "text": "/dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 /dg stage <stage_id> mission region pos2 /dg stage <stage_id> mission region delete /dungeon stage <stage_id> mission kill_mobs <amount> /dungeon stage <stage_id> mission lever /dungeon stage <stage_id> mission button <button_material> /dungeon stage <stage_id> mission pressure_plate <plate_material> /dungeon stage <stage_id> mission required_key <amount> /dungeon stage <stage_id> mission time <seconds> /dungeon stage <stage_id> mission sacrifice [mode] [drop_items] /dungeon stage <stage_id> mission money_payment <amount> [ANY_PLAYER|LEADER_ONLY] /dungeon stage <stage_id> mission item_payment /dungeon stage <stage_id> mission <type> delete `SACRIFICE`, `MONEY_PAYMENT`, and `ITEM_PAYMENT` are opened during a run by right-clicking a gate block.", "url": "stages/index.html#mission-commands"}, {"group": "Systems", "title": "Stages and Gates", "section": "Kill Mobs Filters", "snippet": "New `KILL_MOBS` missions include both options: missions: - type: KILL_MOBS required: 20 only-dungeon-spawner-mobs: true count-baby-variants: true `only-dungeon-spawn...", "text": "New `KILL_MOBS` missions include both options: missions: - type: KILL_MOBS required: 20 only-dungeon-spawner-mobs: true count-baby-variants: true `only-dungeon-spawner-mobs` counts only mobs spawned by this dungeon instance's configured spawners, including vanilla and MythicMobs pools. Friendly summons from enchantments or other plugins, natural mobs, and mobs already stored in the template do not count. Bosses remain excluded from stage kill missions. Dungeon-spawned mobs still count after transformations, such as a zombie becoming a drowned. Set `only-dungeon-spawner-mobs: false` to count mobs from other sources inside the instance. Kills must be credited to a player. Mobs summoned separately by a Mythic skill are not automatically treated as dungeon spawner mobs. `count-baby-variants` includes baby versions of eligible mobs, including zombies, drowned, piglins, and other ageable mobs. Set it to `false` to exclude babies. The spawner-source filter still applies. To control which variants spawn, use the spawner settings. Both options default to `true` when omitted, including in existing missions. Changing the required amount through a command or the editor preserves these filters. Save the mission to write the fields, or add them manually and reload.", "url": "stages/index.html#kill-mobs-filters"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Loot and Rewards", "snippet": "InstancedDungeons supports loot chests, mission keys, boss rewards, trigger rewards, and custom item providers.", "text": "InstancedDungeons supports loot chests, mission keys, boss rewards, trigger rewards, and custom item providers.", "url": "loot-and-rewards/index.html"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Loot Chests", "snippet": "Create a loot chest config: /dungeon edit dragon_lair /dungeon addlootchest treasure_room /dungeon lootchest give treasure_room Add the item in your main hand to the...", "text": "Create a loot chest config: /dungeon edit dragon_lair /dungeon addlootchest treasure_room /dungeon lootchest give treasure_room Add the item in your main hand to the loot table: /dungeon lootchest loot treasure_room add Loot chest files live in: dungeons/<id>/lootchests/<loot_chest_id>.yml Example: loot-table: - type: VANILLA item: DIAMOND min-amount: 1 max-amount: 4 chance: 50.0", "url": "loot-and-rewards/index.html#loot-chests"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Mission Keys", "snippet": "Mission keys use the `MISSION` type and are guaranteed supply entries. loot-table: - type: MISSION item: KEY stage: 1 quantity: 1 lore: - &quot;&amp;7A key used to unlock a d...", "text": "Mission keys use the `MISSION` type and are guaranteed supply entries. loot-table: - type: MISSION item: KEY stage: 1 quantity: 1 lore: - \"&7A key used to unlock a dungeon stage.\" Mission keys are bound to the instance where they dropped and are removed when the player leaves that instance.", "url": "loot-and-rewards/index.html#mission-keys"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Boss Rewards", "snippet": "Open the boss reward editor: /dungeon boss reward edit Boss and trigger delivery is controlled by `reward-logic`: reward-logic: delivery: INVENTORY recipients: EVERY...", "text": "Open the boss reward editor: /dungeon boss reward edit Boss and trigger delivery is controlled by `reward-logic`: reward-logic: delivery: INVENTORY recipients: EVERY_ALIVE `delivery` accepts `INVENTORY` or `GROUND`. | `PARTY_SHARED` | Boss or trigger | `GROUND` only | | `LEADER` | Boss or trigger | `INVENTORY` only | | `KILLER` | Boss only | `INVENTORY` only | | `ACTIVATOR` | Trigger only | `INVENTORY` only | | `EVERY_ALIVE` | Boss or trigger | `INVENTORY` or `GROUND` | Invalid combinations block the dungeon from opening and are reported by validation. `GROUND + EVERY_ALIVE` makes one independent reward roll for every eligible player and creates one public pile at the boss or trigger location. Inventory overflow drops at the recipient's location. Only online, alive party members inside the instance world count for `EVERY_ALIVE`. Supported custom items follow the same delivery rules as vanilla items. For existing dungeons, boss rewards keep `GROUND + PARTY_SHARED` and trigger rewards keep `INVENTORY + EVERY_ALIVE` unless an administrator changes them. Reward entries are independent. If you place 4 diamonds in one GUI slot and 2 diamonds in another slot, the plugin saves two separate reward entries.", "url": "loot-and-rewards/index.html#boss-rewards"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Trigger Rewards", "snippet": "Open the trigger reward editor: /dungeon trigger reward edit Trigger rewards are saved in: dungeons/&lt;id&gt;/trigger.yml They are given when the configured trigger compl...", "text": "Open the trigger reward editor: /dungeon trigger reward edit Trigger rewards are saved in: dungeons/<id>/trigger.yml They are given when the configured trigger completes the dungeon. Example: rewards: enabled: true items: - type: VANILLA item: DIAMOND amount: 2 chance: 100.0", "url": "loot-and-rewards/index.html#trigger-rewards"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Supported Item Types", "snippet": "| `VANILLA` | Standard Minecraft item material or special vanilla ID. | | `MYTHIC_ITEM` | MythicMobs item ID. | | `ITEMSADDER` | ItemsAdder item ID. | | `ORAXEN` | O...", "text": "| `VANILLA` | Standard Minecraft item material or special vanilla ID. | | `MYTHIC_ITEM` | MythicMobs item ID. | | `ITEMSADDER` | ItemsAdder item ID. | | `ORAXEN` | Oraxen item ID. | | `NEXO` | Nexo item ID. | | `MISSION` | Dungeon mission key entry. |", "url": "loot-and-rewards/index.html#supported-item-types"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Special Vanilla Item IDs", "snippet": "Special vanilla IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. Supported examples include potions, splash poti...", "text": "Special vanilla IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. Supported examples include potions, splash potions, lingering potions, tipped arrows, and enchanted books. - type: VANILLA item: POTION_LONG_POISON amount: 1", "url": "loot-and-rewards/index.html#special-vanilla-item-ids"}, {"group": "Systems", "title": "Event Commands", "section": "Event Commands", "snippet": "Event commands let admins run server commands when dungeon events happen. Each dungeon can have: plugins/InstancedDungeons/dungeons/&lt;dungeon_id&gt;/commands.yml", "text": "Event commands let admins run server commands when dungeon events happen. Each dungeon can have: plugins/InstancedDungeons/dungeons/<dungeon_id>/commands.yml", "url": "event-commands/index.html"}, {"group": "Systems", "title": "Event Commands", "section": "Basic Structure", "snippet": "commands: - event: on-party-complete-dungeon-command enabled: true executor: CONSOLE audience: PARTY commands: - &quot;broadcast &lt;party_leader&gt;&#x27;s party completed &lt;dungeon...", "text": "commands: - event: on-party-complete-dungeon-command enabled: true executor: CONSOLE audience: PARTY commands: - \"broadcast <party_leader>'s party completed <dungeon_name>\"", "url": "event-commands/index.html#basic-structure"}, {"group": "Systems", "title": "Event Commands", "section": "Executors", "snippet": "| `CONSOLE` | Runs commands as console. | | `PLAYER` | Runs commands as player. |", "text": "| `CONSOLE` | Runs commands as console. | | `PLAYER` | Runs commands as player. |", "url": "event-commands/index.html#executors"}, {"group": "Systems", "title": "Event Commands", "section": "Audiences", "snippet": "| `NONE` | Runs once with no player target. | | `PLAYER` | Runs for the event player. | | `PARTY` | Runs for each party member. | | `GLOBAL` | Runs for all online pl...", "text": "| `NONE` | Runs once with no player target. | | `PLAYER` | Runs for the event player. | | `PARTY` | Runs for each party member. | | `GLOBAL` | Runs for all online players. |", "url": "event-commands/index.html#audiences"}, {"group": "Systems", "title": "Event Commands", "section": "Player Events", "snippet": "| `on-player-create-party-command` | Player creates a party with `/dungeon open &lt;id&gt;`. | | `on-player-join-party-command` | Player joins a party. | | `on-player-star...", "text": "| `on-player-create-party-command` | Player creates a party with `/dungeon open <id>`. | | `on-player-join-party-command` | Player joins a party. | | `on-player-start-dungeon-command` | Player starts the dungeon. | | `on-player-complete-dungeon-command` | Single dungeon completes, or final tower dungeon completes. | | `on-player-abandon-dungeon-command` | Player abandons the dungeon. | | `on-player-exit-dungeon-command` | Player exits with `/dungeon exit`. | | `on-player-death-command` | Player dies inside a dungeon. | | `on-player-kill-mob-command` | Player kills a dungeon mob. | | `on-player-kill-boss-command` | Player kills the boss. | | `on-player-complete-stage-command` | Active stage completes. | | `on-player-open-gate-command` | Stage gate opens. | | `on-player-fail-dungeon-command` | Dungeon or tower fails. |", "url": "event-commands/index.html#player-events"}, {"group": "Systems", "title": "Event Commands", "section": "Party Events", "snippet": "| `on-party-create-command` | Party is created. | | `on-party-player-join-command` | Player joins a party. | | `on-party-start-dungeon-command` | Party starts the du...", "text": "| `on-party-create-command` | Party is created. | | `on-party-player-join-command` | Player joins a party. | | `on-party-start-dungeon-command` | Party starts the dungeon. | | `on-party-complete-dungeon-command` | Single dungeon completes. In towers, final dungeon only. | | `on-party-abandon-dungeon-command` | Party abandons the dungeon. | | `on-party-fail-dungeon-command` | Dungeon or whole tower fails. | | `on-party-complete-stage-command` | Stage completes. | | `on-party-open-gate-command` | Stage gate opens. | | `on-party-enter-tower-stage-command` | Party enters the next tower dungeon. | | `on-party-complete-tower-command` | Final tower dungeon completes. |", "url": "event-commands/index.html#party-events"}, {"group": "Systems", "title": "Event Commands", "section": "Common Placeholders", "snippet": "| `&lt;player&gt;` | Event player name. | | `&lt;party_leader&gt;` | Party leader name. | | `&lt;party_code&gt;` | Party code. | | `&lt;dungeon_id&gt;` | Dungeon ID. | | `&lt;dungeon_name&gt;` | ...", "text": "| `<player>` | Event player name. | | `<party_leader>` | Party leader name. | | `<party_code>` | Party code. | | `<dungeon_id>` | Dungeon ID. | | `<dungeon_name>` | Display name. | | `<stage_id>` | Stage ID for stage events. | | `<stage_order>` | Stage order where available. | | `<tower_id>` | Tower context ID. | | `<reason>` | Failure reason where available. | Be careful with `GLOBAL` audiences and commands that give items, money, or permissions. Validation warns about risky combinations.", "url": "event-commands/index.html#common-placeholders"}, {"group": "Item ID Reference", "title": "Potions and Arrows", "section": "Potions and Tipped Arrows", "snippet": "Special potion IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. They can also be captured automatically from the...", "text": "Special potion IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. They can also be captured automatically from the cost editor GUI, reward editor GUI, and `/dungeon lootchest loot <id> add`. Use this format: <ITEM_TYPE>_<POTION_EFFECT> Available item types: POTION SPLASH_POTION LINGERING_POTION TIPPED_ARROW Example loot entries: - type: VANILLA item: POTION_LONG_POISON min-amount: 1 max-amount: 3 chance: 100.0 - type: VANILLA item: SPLASH_POTION_STRONG_HEALING min-amount: 1 max-amount: 1 chance: 100.0 - type: VANILLA item: TIPPED_ARROW_SLOW_FALLING min-amount: 4 max-amount: 8 chance: 50.0 `LONG_` variants use Minecraft's extended-duration potion type. `STRONG_` variants use Minecraft's upgraded stronger potion type where vanilla provides one. Available effect names: NIGHT_VISION LONG_NIGHT_VISION INVISIBILITY LONG_INVISIBILITY LEAPING LONG_LEAPING STRONG_LEAPING FIRE_RESISTANCE LONG_FIRE_RESISTANCE SWIFTNESS LONG_SWIFTNESS STRONG_SWIFTNESS SLOWNESS LONG_SLOWNESS STRONG_SLOWNESS WATER_BREATHING LONG_WATER_BREATHING HEALING STRONG_HEALING HARMING STRONG_HARMING POISON LONG_POISON STRONG_POISON REGENERATION LONG_REGENERATION STRONG_REGENERATION STRENGTH LONG_STRENGTH STRONG_STRENGTH WEAKNESS LONG_WEAKNESS LUCK SLOW_FALLING LONG_SLOW_FALLING TURTLE_MASTER LONG_TURTLE_MASTER STRONG_TURTLE_MASTER INFESTED OOZING WEAVING WIND_CHARGED Special potion and arrow drops follow their vanilla stack limits. Potions, splash potions, and lingering potions are split into one-item stacks, while tipped arrows can stack normally up to their item stack limit.", "url": "item-ids/potions-and-arrows/index.html"}, {"group": "Item ID Reference", "title": "Enchanted Books", "section": "Enchanted Books", "snippet": "Enchanted book IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. They can also be captured automatically from the...", "text": "Enchanted book IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. They can also be captured automatically from the cost editor GUI, reward editor GUI, and `/dungeon lootchest loot <id> add`. Use this format: ENCHANTED_BOOK_<ENCHANTMENT>_<LEVEL> Example: - type: VANILLA item: ENCHANTED_BOOK_SHARPNESS_4 min-amount: 1 max-amount: 1 chance: 100.0 The level cannot be higher than the vanilla maximum level of that enchantment. For example, `ENCHANTED_BOOK_SHARPNESS_5` is valid, but `ENCHANTED_BOOK_SHARPNESS_6` is rejected by validation. Common enchanted book IDs: ENCHANTED_BOOK_SHARPNESS_5 ENCHANTED_BOOK_PROTECTION_4 ENCHANTED_BOOK_EFFICIENCY_5 ENCHANTED_BOOK_UNBREAKING_3 ENCHANTED_BOOK_MENDING_1 ENCHANTED_BOOK_FORTUNE_3 ENCHANTED_BOOK_LOOTING_3 ENCHANTED_BOOK_POWER_5 ENCHANTED_BOOK_PIERCING_4 ENCHANTED_BOOK_DENSITY_5 Supported enchantment names are taken from the server enchantment registry. On the Paper 26.x build line this includes: PROTECTION FIRE_PROTECTION FEATHER_FALLING BLAST_PROTECTION PROJECTILE_PROTECTION RESPIRATION AQUA_AFFINITY THORNS DEPTH_STRIDER FROST_WALKER BINDING_CURSE SHARPNESS SMITE BANE_OF_ARTHROPODS KNOCKBACK FIRE_ASPECT LOOTING SWEEPING_EDGE EFFICIENCY SILK_TOUCH UNBREAKING FORTUNE POWER PUNCH FLAME INFINITY LUCK_OF_THE_SEA LURE LOYALTY IMPALING RIPTIDE CHANNELING MULTISHOT QUICK_CHARGE PIERCING DENSITY BREACH WIND_BURST MENDING VANISHING_CURSE SOUL_SPEED SWIFT_SNEAK LUNGE When an enchanted book drops with an amount above `1`, the plugin creates separate one-item stacks because enchanted books do not stack. The cost and reward editors save enchanted non-book items as their base vanilla material.", "url": "item-ids/enchanted-books/index.html"}, {"group": "Help", "title": "Help Center", "section": "Diagnostic Workflow", "snippet": "Validate the dungeon configuration and inspect any reported file/field errors: /dungeon validate &lt;id&gt; /dungeon validate all Check active integrations (Vault, MythicM...", "text": "Validate the dungeon configuration and inspect any reported file/field errors: /dungeon validate <id> /dungeon validate all Check active integrations (Vault, MythicMobs, ItemsAdder, Oraxen, Nexo, WorldGuard): /dungeon status Review the [Troubleshooting](troubleshooting.md) guide and [Complete Reference](complete-reference.md). When updating from an earlier release, follow the [Updating](updating.md) checklist.", "url": "help/index.html#diagnostic-workflow"}, {"group": "Help", "title": "Help Center", "section": "Official Links", "snippet": "**Modrinth:** [modrinth.com/plugin/instanced-dungeon](https://modrinth.com/plugin/instanced-dungeon) **GET PRO:** [BuiltByBit](https://builtbybit.com/resources/insta...", "text": "**Modrinth:** [modrinth.com/plugin/instanced-dungeon](https://modrinth.com/plugin/instanced-dungeon) **GET PRO:** [BuiltByBit](https://builtbybit.com/resources/instanceddungeons-pro.112271/) **Discord Support:** [discord.com/invite/sD4HvQh8P4](https://discord.com/invite/sD4HvQh8P4)", "url": "help/index.html#official-links"}, {"group": "Help", "title": "RAM Analysis", "section": "RAM Analysis", "snippet": "Use this command to turn memory reports on or off: /dungeon ram analysis Requires `instanceddungeons.admin`. Analysis is disabled by default. The file `plugins/Insta...", "text": "Use this command to turn memory reports on or off: /dungeon ram analysis Requires `instanceddungeons.admin`. Analysis is disabled by default. The file `plugins/InstancedDungeons/ram-analysis.yml` is created only after the command is enabled for the first time.", "url": "ram-analysis/index.html"}, {"group": "Help", "title": "RAM Analysis", "section": "Settings", "snippet": "enabled: true settings: report-interval-minutes: 10 sample-interval-seconds: 30 max-stored-reports: 144 Reports are stored newest first, with timestamps in the serve...", "text": "enabled: true settings: report-interval-minutes: 10 sample-interval-seconds: 30 max-stored-reports: 144 Reports are stored newest first, with timestamps in the server's local time zone. | `enabled` | Turns analysis on or off. | | `report-interval-minutes` | Minutes between saved reports. | | `sample-interval-seconds` | Seconds between memory samples. | | `max-stored-reports` | Maximum number of reports to keep. |", "url": "ram-analysis/index.html#settings"}, {"group": "Help", "title": "RAM Analysis", "section": "Reported memory", "snippet": "Each period contains: The estimated InstancedDungeons core memory. The estimated memory of active dungeon instances. The combined plugin and instance estimate. Total...", "text": "Each period contains: The estimated InstancedDungeons core memory. The estimated memory of active dungeon instances. The combined plugin and instance estimate. Total instance launches and launches grouped by dungeon ID. Estimated instance-world usage grouped by dungeon. These are estimates for the plugin and its instances, not measurements of total server RAM.", "url": "ram-analysis/index.html#reported-memory"}, {"group": "Help", "title": "Troubleshooting", "section": "Troubleshooting", "snippet": "Start here whenever something does not work: /dungeon validate &lt;id&gt; /dungeon validate all /dungeon reload Also check the server console. Validation warnings in chat ...", "text": "Start here whenever something does not work: /dungeon validate <id> /dungeon validate all /dungeon reload Also check the server console. Validation warnings in chat are shorter than the console output.", "url": "troubleshooting/index.html"}, {"group": "Help", "title": "Troubleshooting", "section": "Dungeon Will Not Open", "snippet": "Check: `dungeons/&lt;id&gt;/config.yml` exists. The config uses the current format marker. The template world exists and is loaded. Spawn and exit are set. Min/max players...", "text": "Check: `dungeons/<id>/config.yml` exists. The config uses the current format marker. The template world exists and is loaded. Spawn and exit are set. Min/max players are valid. The dungeon passes `/dungeon validate <id>`. Dungeons using the 1.x config format must be recreated for 2.x.", "url": "troubleshooting/index.html#dungeon-will-not-open"}, {"group": "Help", "title": "Troubleshooting", "section": "Boss Dungeon Does Not Complete", "snippet": "Check: The dungeon was created as `boss`. `boss.yml` exists. The boss location is valid. `boss.must-die-to-complete` is `true` if boss death should complete the run....", "text": "Check: The dungeon was created as `boss`. `boss.yml` exists. The boss location is valid. `boss.must-die-to-complete` is `true` if boss death should complete the run. The boss entity spawned inside the instance world.", "url": "troubleshooting/index.html#boss-dungeon-does-not-complete"}, {"group": "Help", "title": "Troubleshooting", "section": "Trigger Dungeon Does Not Complete", "snippet": "Check: The dungeon was created as `trigger`. `trigger.yml` exists. The trigger was placed with `/dungeon settrigger &lt;material&gt;`. The trigger block still exists in th...", "text": "Check: The dungeon was created as `trigger`. `trigger.yml` exists. The trigger was placed with `/dungeon settrigger <material>`. The trigger block still exists in the template or instance. The material is a supported button or pressure plate.", "url": "troubleshooting/index.html#trigger-dungeon-does-not-complete"}, {"group": "Help", "title": "Troubleshooting", "section": "Tower Does Not Continue", "snippet": "Check: `dungeon-type: tower`. `tower-stage-type` is correct. `next-dungeon` points to an existing dungeon. The next dungeon passes validation. Only the `FIRST` stage...", "text": "Check: `dungeon-type: tower`. `tower-stage-type` is correct. `next-dungeon` points to an existing dungeon. The next dungeon passes validation. Only the `FIRST` stage has entry costs. Free version towers are only `FIRST -> LAST`.", "url": "troubleshooting/index.html#tower-does-not-continue"}, {"group": "Help", "title": "Troubleshooting", "section": "Stage Gate Does Not Open", "snippet": "Check: Stage files are in `dungeons/&lt;id&gt;/stages/`. Stage orders are continuous: `1`, `2`, `3`. The gate was saved with `/dungeon gate save`. Active missions are comp...", "text": "Check: Stage files are in `dungeons/<id>/stages/`. Stage orders are continuous: `1`, `2`, `3`. The gate was saved with `/dungeon gate save`. Active missions are complete. Later stages do not progress until earlier gates open.", "url": "troubleshooting/index.html#stage-gate-does-not-open"}, {"group": "Help", "title": "Troubleshooting", "section": "Loot Chests Are Empty", "snippet": "Check: The loot chest config has loot entries. Chances are above `0`. The placed chest was created with `/dungeon lootchest give &lt;id&gt;`. Custom item provider plugins ...", "text": "Check: The loot chest config has loot entries. Chances are above `0`. The placed chest was created with `/dungeon lootchest give <id>`. Custom item provider plugins are loaded.", "url": "troubleshooting/index.html#loot-chests-are-empty"}, {"group": "Help", "title": "Troubleshooting", "section": "Players Get Removed From Instance Worlds", "snippet": "In the Free Paper 1.21.x build 2.3.1, startup verifies that all participants reach the instance before starting the run. A failed entry cancels startup and refunds e...", "text": "In the Free Paper 1.21.x build 2.3.1, startup verifies that all participants reach the instance before starting the run. A failed entry cancels startup and refunds entry costs. Respawning is tracked separately from leaving the dungeon. For that build, set `debug: true` in the main `config.yml` and run `/dungeon reload` to investigate teleport problems. Keep the complete console log from preparation through cleanup. `[Teleport]` lines include the requested destination, API result, event cancellation, player state, and actual world after the event. `eventSeen=false` means no teleport event was observed for that attempt. `[Respawn]` lines record respawn destinations and arrival checks. Registered listeners are diagnostic candidates; the list does not prove which plugin cancelled a teleport. Active instance worlds reject players who are not part of the dungeon run. This prevents outside players from entering temporary worlds. If this happens to real dungeon players, check: They did not leave the party. They did not disconnect during start. The party is still active. They did not use external teleport commands into another instance.", "url": "troubleshooting/index.html#players-get-removed-from-instance-worlds"}, {"group": "Help", "title": "Troubleshooting", "section": "Custom Items Fail", "snippet": "Check: The integration plugin is installed and loaded. The item ID is correct. Run `/dungeon status`. Use the integration lookup command when available: /dungeon myt...", "text": "Check: The integration plugin is installed and loaded. The item ID is correct. Run `/dungeon status`. Use the integration lookup command when available: /dungeon mythicitem [itemId] /dungeon itemsadder [itemId] /dungeon oraxen [itemId] /dungeon nexo [itemId]", "url": "troubleshooting/index.html#custom-items-fail"}], "pro": [{"group": "Start", "title": "Overview", "section": "InstancedDungeons Pro", "snippet": "InstancedDungeons Pro is the full-featured dungeon engine for Paper 1.21.x and 26.x servers. Each party run clones a template world into an isolated instance with mu...", "text": "InstancedDungeons Pro is the full-featured dungeon engine for Paper 1.21.x and 26.x servers. Each party run clones a template world into an isolated instance with multi-stage progression, ordered checkpoints, custom mob equipment, multi-floor tower chains, custom sound profiles, and full in-game GUI management.", "url": "pro/index.html"}, {"group": "Start", "title": "Overview", "section": "Quick Start", "snippet": "Create a void or flat template world via `/dg gui` (**Template Worlds**) or command, create a dungeon, set spawn/exit/objective points, and validate: /dg world creat...", "text": "Create a void or flat template world via `/dg gui` (**Template Worlds**) or command, create a dungeon, set spawn/exit/objective points, and validate: /dg world create dragon_template void normal 500 /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon setexit /dungeon setboss /dungeon save /dungeon reload /dungeon validate dragon_lair", "url": "pro/index.html#quick-start"}, {"group": "Start", "title": "Overview", "section": "Documentation Overview", "snippet": "| [Getting Started &amp;amp; Admin GUI](getting-started.md) | Set up template worlds (`void`, `flat`, `normal`), manage worlds in the **Template Worlds** browser, and co...", "text": "| [Getting Started &amp; Admin GUI](getting-started.md) | Set up template worlds (`void`, `flat`, `normal`), manage worlds in the **Template Worlds** browser, and configure dungeons through `/dg gui`. | | [Dungeon Config &amp; Cooldowns](configuration.md) | Configure party sizes, player/team lives, item restrictions, TNT behavior, timer bossbars, and per-dungeon or global player cooldowns. | | [Stages, Gates &amp; After-Open Logic](stages.md) | Build sequential or parallel stages with multi-target `KILL_MOBS`, `REGION` cuboids, after-open party teleports, gate closing, emergency return plates, and `/dg skip`. | | [Ordered Checkpoints](checkpoints.md) | Set respawn checkpoints triggered by opening a gate, pressing a button, or stepping on a pressure plate, with optional party teleports and gate closing. | | [Spawners, Bosses &amp; Equipment](spawners-and-mobs.md) | Configure Vanilla and MythicMobs spawners, boss stage requirements (`DISABLED`, `STAGE`, `ALL`), and full mob armor/weapon equipment with per-slot drop chances. | | [Loot, Keys &amp; Enchanted Gear](loot-and-rewards.md) | Distribute stage keys across multiple chests, preserve enchantments on vanilla gear in costs/loot/rewards, and customize reward delivery (`GROUND` / `INVENTORY`) and recipients. | | [Multi-Floor Towers](towers.md) | Chain unlimited dungeon floors (`FIRST -> MIDDLE -> ... -> LAST`) into a continuous run. | | [Dungeon Sounds &amp; Event Commands](sounds.md) | Customize per-dungeon sound profiles in `sounds.yml` and automate console/player actions in `commands.yml`. |", "url": "pro/index.html#documentation-overview"}, {"group": "Start", "title": "Getting Started", "section": "Getting Started", "snippet": "This guide creates a working dungeon from a template world.", "text": "This guide creates a working dungeon from a template world.", "url": "pro/getting-started/index.html"}, {"group": "Start", "title": "Getting Started", "section": "Requirements", "snippet": "| Paper 1.21.x | 21+ | Built-in (`/dg world` and Admin GUI) | | Paper 26.1.x / 26.2.x / 26.3.x | 25+ | Built-in (`/dg world` and Admin GUI) | One universal plugin JA...", "text": "| Paper 1.21.x | 21+ | Built-in (`/dg world` and Admin GUI) | | Paper 26.1.x / 26.2.x / 26.3.x | 25+ | Built-in (`/dg world` and Admin GUI) | One universal plugin JAR supports both Paper 1.21.x and Paper 26.1.x / 26.2.x / 26.3.x. Optional integrations: WorldGuard for copying template world regions and flags into dungeon instances. MythicMobs for custom mobs and bosses. MythicMobs items through `MYTHIC_ITEM`. ItemsAdder, Oraxen, or Nexo for custom item IDs. Vault plus an economy plugin for money costs and payment missions. Multiverse-Core for optional compatibility with external server worlds.", "url": "pro/getting-started/index.html#requirements"}, {"group": "Start", "title": "Getting Started", "section": "Install", "snippet": "Stop the server. Put the plugin `.jar` into the `plugins` folder. Start the server once. Configure dungeons in `plugins/InstancedDungeons/dungeons/`. Run `/dungeon r...", "text": "Stop the server. Put the plugin `.jar` into the `plugins` folder. Start the server once. Configure dungeons in `plugins/InstancedDungeons/dungeons/`. Run `/dungeon reload` after YAML edits. Current dungeons use the 2.0 config format. Older 1.0.x dungeons should be recreated or kept with the legacy documentation.", "url": "pro/getting-started/index.html#install"}, {"group": "Start", "title": "Getting Started", "section": "Create a Boss Dungeon", "snippet": "Create a template world with `/dg world create` or **Create Template World** in `/dg gui` (when outside edit mode). Example: /dg world create dragon_template void no...", "text": "Create a template world with `/dg world create` or **Create Template World** in `/dg gui` (when outside edit mode). Example: /dg world create dragon_template void normal 500 Then configure the dungeon: /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon setexit /dungeon setboss /dungeon save /dungeon reload Validate before players use it: /dungeon validate dragon_lair", "url": "pro/getting-started/index.html#create-a-boss-dungeon"}, {"group": "Start", "title": "Getting Started", "section": "Create a Trigger Dungeon", "snippet": "Trigger dungeons complete when players activate one configured button or pressure plate. /dg world create puzzle_template flat /dungeon create puzzle_room puzzle_tem...", "text": "Trigger dungeons complete when players activate one configured button or pressure plate. /dg world create puzzle_template flat /dungeon create puzzle_room puzzle_template trigger /dungeon edit puzzle_room /dungeon setspawn /dungeon setexit /dungeon settrigger STONE_BUTTON /dungeon trigger reward edit /dungeon save /dungeon reload", "url": "pro/getting-started/index.html#create-a-trigger-dungeon"}, {"group": "Start", "title": "Getting Started", "section": "Start as a Player", "snippet": "/dungeon open dragon_lair /dungeon join &lt;code&gt; /dungeon start `/dungeon open` only suggests standalone dungeons and tower `FIRST` stages. Middle and last tower stage...", "text": "/dungeon open dragon_lair /dungeon join <code> /dungeon start `/dungeon open` only suggests standalone dungeons and tower `FIRST` stages. Middle and last tower stage IDs are entered through tower progression.", "url": "pro/getting-started/index.html#start-as-a-player"}, {"group": "Start", "title": "Updating", "section": "Before Updating", "snippet": "Stop the server. Back up `plugins/InstancedDungeons/dungeons/`, `config.yml`, `messages.yml`, and `data/`. Replace the plugin JAR in `plugins/` (one JAR supports bot...", "text": "Stop the server. Back up `plugins/InstancedDungeons/dungeons/`, `config.yml`, `messages.yml`, and `data/`. Replace the plugin JAR in `plugins/` (one JAR supports both Paper 1.21.x and Paper 26.x). Start the server, check `/dg status`, and run `/dg validate all`. Test a dungeon before allowing players to enter. InstancedDungeons does not create automatic backups.", "url": "pro/updating/index.html#before-updating"}, {"group": "Start", "title": "Updating", "section": "Automatic Config and Message Updates", "snippet": "**Configs (`config.yml` and `dungeons/&lt;id&gt;/config.yml`)**: Missing settings are added automatically beside related options with safe defaults. Existing administrator...", "text": "**Configs (`config.yml` and `dungeons/<id>/config.yml`)**: Missing settings are added automatically beside related options with safe defaults. Existing administrator values, unknown keys, unrelated sections, and comments are preserved. **Messages (`messages.yml`)**: Missing message keys are appended to the update section at the end of existing files without overwriting your custom translations. **Internal Data (`plugins/InstancedDungeons/data/`)**: Runtime data files (`template-worlds.dat`, `instance-worlds.dat`, and `player-cooldowns.dat`) are stored under `data/` and migrated automatically from legacy root `.yml` files on startup. Administrators joining during the first few minutes after an update receive a one-time notice if any configuration files should be reviewed. Validation (`/dg validate all`) reports the exact file and field whenever manual attention is needed.", "url": "pro/updating/index.html#automatic-config-and-message-updates"}, {"group": "Start", "title": "Examples", "section": "Examples", "snippet": "Examples for boss dungeons, trigger puzzles, towers, stage keys, and event commands.", "text": "Examples for boss dungeons, trigger puzzles, towers, stage keys, and event commands.", "url": "pro/examples/index.html"}, {"group": "Start", "title": "Examples", "section": "Example 1: Simple Boss Dungeon", "snippet": "Use this when you want a classic dungeon that ends after a boss dies. /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /d...", "text": "Use this when you want a classic dungeon that ends after a boss dies. /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon setexit /dungeon setboss /dungeon boss reward edit /dungeon save /dungeon reload /dungeon validate dragon_lair Recommended flow: Build the template world. Set spawn near the entrance. Set exit in your server hub or dungeon lobby. Set boss spawn in the final room. Add rewards with `/dungeon boss reward edit`. Validate before letting players start the run. Minimal boss behavior in `config.yml`: completion-objective: BOSS fire-spread: false boss: must-die-to-complete: true countdown-after-death: 30", "url": "pro/examples/index.html#example-1-simple-boss-dungeon"}, {"group": "Start", "title": "Examples", "section": "Example 2: Trigger Puzzle Dungeon", "snippet": "Use this for puzzle rooms, parkour endings, escape rooms, or dungeons that complete from a button or pressure plate. /dungeon create puzzle_room puzzle_template trig...", "text": "Use this for puzzle rooms, parkour endings, escape rooms, or dungeons that complete from a button or pressure plate. /dungeon create puzzle_room puzzle_template trigger /dungeon edit puzzle_room /dungeon setspawn /dungeon setexit /dungeon settrigger STONE_BUTTON /dungeon trigger reward edit /dungeon save /dungeon reload /dungeon validate puzzle_room Trigger reward example: rewards: enabled: true items: - type: VANILLA item: DIAMOND amount: 2 chance: 100.0 Trigger blocks work even when normal dungeon interactions are blocked.", "url": "pro/examples/index.html#example-2-trigger-puzzle-dungeon"}, {"group": "Start", "title": "Examples", "section": "Example 3: Two-Stage Tower", "snippet": "Use this when one party should clear a first dungeon and then automatically enter a final dungeon. First dungeon: dungeon-type: tower tower-stage-type: first next-du...", "text": "Use this when one party should clear a first dungeon and then automatically enter a final dungeon. First dungeon: dungeon-type: tower tower-stage-type: first next-dungeon: \"tower_final\" announce-complete: true announce-fail: true Final dungeon: dungeon-type: tower tower-stage-type: last next-dungeon: \"\" Rules to remember: Players open only the `FIRST` stage directly. `/dungeon list` hides the final stage as a public dungeon. Final completion broadcasts use the final dungeon name. Announcement settings come from the entry dungeon.", "url": "pro/examples/index.html#example-3-two-stage-tower"}, {"group": "Start", "title": "Examples", "section": "Example 4: Stage Gate With a Key", "snippet": "Use this when players must find a mission key before a gate opens. /dungeon edit dragon_lair /dungeon stage create entrance_gate /dungeon stage entrance_gate gate cr...", "text": "Use this when players must find a mission key before a gate opens. /dungeon edit dragon_lair /dungeon stage create entrance_gate /dungeon stage entrance_gate gate create /dungeon gate save /dungeon stage entrance_gate mission required_key 1 /dungeon stage entrance_gate gate hologram create Add a mission key to a loot chest: loot-table: - type: MISSION item: KEY stage: 1 quantity: 1 lore: - \"&7A key used to unlock a dungeon stage.\"", "url": "pro/examples/index.html#example-4-stage-gate-with-a-key"}, {"group": "Start", "title": "Examples", "section": "Example 5: Event Command Reward Broadcast", "snippet": "Use this when you want automation after completion. commands: - event: on-party-complete-dungeon-command enabled: true executor: CONSOLE audience: NONE commands: - &quot;...", "text": "Use this when you want automation after completion. commands: - event: on-party-complete-dungeon-command enabled: true executor: CONSOLE audience: NONE commands: - \"broadcast <party_leader>'s party completed <dungeon_name>\" For towers, use: commands: - event: on-party-complete-tower-command enabled: true executor: CONSOLE audience: NONE commands: - \"broadcast <party_leader>'s party completed the tower\"", "url": "pro/examples/index.html#example-5-event-command-reward-broadcast"}, {"group": "Start", "title": "Examples", "section": "Validation Checklist", "snippet": "Before publishing a dungeon to players: Run `/dungeon validate &lt;id&gt;`. Confirm the template world exists and is loaded. Confirm spawn and exit are set. Confirm boss o...", "text": "Before publishing a dungeon to players: Run `/dungeon validate <id>`. Confirm the template world exists and is loaded. Confirm spawn and exit are set. Confirm boss or trigger objective exists. Confirm tower `next-dungeon` links are valid. Confirm loot chest IDs match placed loot chest items. Confirm stage order is continuous.", "url": "pro/examples/index.html#validation-checklist"}, {"group": "Start", "title": "Commands", "section": "Commands", "snippet": "Use `/dungeon` or its alias `/dg`.", "text": "Use `/dungeon` or its alias `/dg`.", "url": "pro/commands/index.html"}, {"group": "Start", "title": "Commands", "section": "Player Commands", "snippet": "| `/dungeon help` | Shows player and admin help. | | `/dungeon list` | Lists available dungeons. Tower middle/last stage dungeons are hidden. | | `/dungeon open &lt;id&gt;...", "text": "| `/dungeon help` | Shows player and admin help. | | `/dungeon list` | Lists available dungeons. Tower middle/last stage dungeons are hidden. | | `/dungeon open <id>` | Creates a party for a standalone dungeon or tower `FIRST` stage. | | `/dungeon join <code>` | Joins an open party. | | `/dungeon leave` | Leaves an open party. | | `/dg kick <player>` | Removes another member before the dungeon starts. | | `/dungeon start` | Starts the dungeon as party leader. | | `/dungeon exit` | Leaves the active dungeon instance. | | `/dungeon spectate <leader>` | Spectates the active dungeon led by that party leader. | | `/dungeon spectator exit` | Leaves external spectator mode and restores inventory and gamemode. | `/dg kick <player>` removes a member from the leader's open party. Tab completion suggests only other members of that party. The leader cannot kick themselves, players outside the party, or anyone after dungeon preparation has begun. The removed player and the remaining party receive configurable messages. No extra permission is required beyond being that party's leader. Kicking removes the current membership; it does not ban the player from joining an open party again.", "url": "pro/commands/index.html#player-commands"}, {"group": "Start", "title": "Commands", "section": "World Management Commands", "snippet": "| `/dg world create &lt;name&gt; [void\\|flat\\|normal] [normal\\|nether\\|the_end] [worldborder]` | Creates a template world (`flat` by default, `void` with a bedrock block a...", "text": "| `/dg world create <name> [void\\|flat\\|normal] [normal\\|nether\\|the_end] [worldborder]` | Creates a template world (`flat` by default, `void` with a bedrock block at `0, 64, 0`, or `normal` terrain) with an optional environment and initial world border size (default `500`). | | `/dg world list` | Lists available server and template worlds (excludes active dungeon instances) and highlights worlds created by the plugin. | | `/dg world tp <name>` | Teleports to a template or server world. | | `/dg world delete <name>` | Deletes a plugin-created template world after confirmation if no dungeon uses it. | Template worlds created by the plugin can also be managed from the admin dashboard (`/dg gui` when outside edit mode) using **Template Worlds**, which opens a browser listing all plugin-created template worlds. From there you can teleport to a world (left click), delete an unused world (right click), or click **Create Template World** to enter a world name in chat and choose `FLAT`, `VOID`, or `NORMAL`. When creating a dungeon from the GUI, available worlds are listed in chat (`1.`, `2.`, `3.`) excluding active instances, with plugin-created template worlds highlighted.", "url": "pro/commands/index.html#world-management-commands"}, {"group": "Start", "title": "Commands", "section": "Core Admin Commands", "snippet": "| `/dungeon create &lt;id&gt; &lt;template-world&gt; &lt;boss\\|trigger&gt;` | Creates a dungeon using the current config format. | | `/dungeon edit &lt;id&gt;` | Enters editor mode. | | `/d...", "text": "| `/dungeon create <id> <template-world> <boss\\|trigger>` | Creates a dungeon using the current config format. | | `/dungeon edit <id>` | Enters editor mode. | | `/dungeon gui` | Opens the admin GUI (or run `/dg` as an admin). | | `/dungeon save` | Exits editor mode. | | `/dungeon reload` | Reloads configs and validation. | | `/dungeon validate <id>` | Validates one dungeon. | | `/dungeon validate all` | Validates every dungeon. | | `/dungeon delete <id>` | Deletes a dungeon after confirmation. | | `/dungeon instances` | Shows active parties and instances. | | `/dungeon status` | Shows detected integration and economy status. |", "url": "pro/commands/index.html#core-admin-commands"}, {"group": "Start", "title": "Commands", "section": "Objective Commands", "snippet": "| `/dungeon setspawn` | Sets the dungeon spawn at your location. | | `/dungeon setexit` | Sets the dungeon exit at your location. | | `/dungeon setboss` | Sets the b...", "text": "| `/dungeon setspawn` | Sets the dungeon spawn at your location. | | `/dungeon setexit` | Sets the dungeon exit at your location. | | `/dungeon setboss` | Sets the boss spawn for boss-objective dungeons. | | `/dungeon boss reward edit` | Opens the boss reward editor GUI. | | `/dungeon settrigger <button\\|pressure_plate>` | Gives the trigger item for trigger-objective dungeons. | | `/dungeon trigger reward edit` | Opens the trigger reward editor GUI. |", "url": "pro/commands/index.html#objective-commands"}, {"group": "Start", "title": "Commands", "section": "Loot Commands", "snippet": "| `/dungeon addlootchest &lt;id&gt;` | Creates a loot chest config at your location. | | `/dungeon lootchest give &lt;id&gt;` | Gives a placeable loot chest item. | | `/dungeon ...", "text": "| `/dungeon addlootchest <id>` | Creates a loot chest config at your location. | | `/dungeon lootchest give <id>` | Gives a placeable loot chest item. | | `/dungeon lootchest loot <id> add` | Adds the item in your main hand to the loot chest config. |", "url": "pro/commands/index.html#loot-commands"}, {"group": "Start", "title": "Commands", "section": "Stage Commands", "snippet": "| `/dungeon stage create &lt;stage_id&gt;` | Creates a stage file. | | `/dungeon stage list` | Lists stages in the current editor dungeon. | | `/dungeon stage &lt;stage_id&gt; o...", "text": "| `/dungeon stage create <stage_id>` | Creates a stage file. | | `/dungeon stage list` | Lists stages in the current editor dungeon. | | `/dungeon stage <stage_id> order <number>` | Moves a stage to another order. Equal orders run in parallel. | | `/dungeon stage <stage_id> delete` | Deletes a stage after confirmation. | | `/dungeon stage <stage_id> gate create` | Starts gate block creation mode. | | `/dungeon stage <stage_id> gate edit` | Edits existing gate blocks. | | `/dungeon stage <stage_id> gate delete` | Deletes a gate after confirmation. | | `/dungeon stage <stage_id> gate stick` | Gives the gate edit stick. | | `/dungeon gate save` | Saves the active gate edit session. | | `/dungeon stage <stage_id> gate hologram create` | Adds a stage hologram. | | `/dungeon stage <stage_id> gate hologram delete` | Removes the nearest hologram within 3 blocks. |", "url": "pro/commands/index.html#stage-commands"}, {"group": "Start", "title": "Commands", "section": "Advanced Gate Commands", "snippet": "| `/dungeon stage &lt;stage_id&gt; gate afteropen teleport set` | Sets and enables the after-open party teleport. | | `/dungeon stage &lt;stage_id&gt; gate afteropen teleport cl...", "text": "| `/dungeon stage <stage_id> gate afteropen teleport set` | Sets and enables the after-open party teleport. | | `/dungeon stage <stage_id> gate afteropen teleport clear` | Clears the after-open teleport. | | `/dungeon stage <stage_id> gate afteropen close add <target_stage_id>` | Adds a gate to close after this gate opens. | | `/dungeon stage <stage_id> gate afteropen close remove <target_stage_id>` | Removes a gate from the after-open close list. | | `/dungeon stage <stage_id> gate emergency enable` | Enables Emergency Return for the gate. | | `/dungeon stage <stage_id> gate emergency disable` | Disables Emergency Return. | | `/dungeon stage <stage_id> gate emergency plate set [material]` | Gives the configured emergency plate for placement. | | `/dungeon stage <stage_id> gate emergency destination set` | Sets its return destination to your location. |", "url": "pro/commands/index.html#advanced-gate-commands"}, {"group": "Start", "title": "Commands", "section": "Checkpoint Commands", "snippet": "| `/dungeon checkpoint create &lt;id&gt;` | Creates a checkpoint. | | `/dungeon checkpoint list` | Lists checkpoints in the edited dungeon. | | `/dungeon checkpoint &lt;id&gt; s...", "text": "| `/dungeon checkpoint create <id>` | Creates a checkpoint. | | `/dungeon checkpoint list` | Lists checkpoints in the edited dungeon. | | `/dungeon checkpoint <id> setlocation` | Sets the checkpoint respawn location. | | `/dungeon checkpoint <id> order <number>` | Sets checkpoint progression order. | | `/dungeon checkpoint <id> trigger gate <stage_id>` | Activates the checkpoint when a gate opens. | | `/dungeon checkpoint <id> trigger block` | Uses the targeted button or pressure plate as its trigger. | | `/dungeon checkpoint <id> teleport <true\\|false>` | Toggles teleporting the alive party after activation. | | `/dungeon checkpoint <id> closegate add\\|remove <stage_id>` | Changes the gates closed after activation. | | `/dungeon checkpoint <id> delete` | Deletes the checkpoint. |", "url": "pro/commands/index.html#checkpoint-commands"}, {"group": "Start", "title": "Commands", "section": "Stage Mission Commands", "snippet": "/dg stage &lt;stage_id&gt; mission region /dg stage &lt;stage_id&gt; mission region pos1 /dg stage &lt;stage_id&gt; mission region pos2 /dg stage &lt;stage_id&gt; mission region delete /dun...", "text": "/dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 /dg stage <stage_id> mission region pos2 /dg stage <stage_id> mission region delete /dungeon stage <stage_id> mission kill_mobs <amount> /dungeon stage <stage_id> mission lever /dungeon stage <stage_id> mission button <button_material> /dungeon stage <stage_id> mission pressure_plate <plate_material> /dungeon stage <stage_id> mission required_key <amount> /dungeon stage <stage_id> mission time <seconds> /dungeon stage <stage_id> mission sacrifice [LEADER_SELECTS|PARTY_VOTE|FIRST_PLAYER_DECISION] [drop_items] /dungeon stage <stage_id> mission money_payment <amount> [ANY_PLAYER|LEADER_ONLY] /dungeon stage <stage_id> mission item_payment /dungeon stage <stage_id> mission <type> delete /dg skip <stage_id> mission all /dg skip <stage_id> mission <mission_type> Run `region` to create the mission, then stand at each corner in the template world and run `pos1` or `pos2`. `delete` removes the mission. Configure `region.mode` and `region.whole-party` in the stage YAML or the Region Mission submenu in the admin GUI. See [Region Missions](stages.md#region-missions). `/dg skip` requires `instanceddungeons.admin` or `instanceddungeons.skip.mission`. It applies only to an unlocked, unfinished stage in the player's active run. See [Skipping Missions](stages.md#skipping-missions). Dungeon IDs, template worlds, stage IDs, loot chest IDs, trigger materials, mission materials, validation targets, and integration item IDs are tab-completed where supported.", "url": "pro/commands/index.html#stage-mission-commands"}, {"group": "Start", "title": "Commands", "section": "RAM Analysis", "snippet": "`/dungeon ram analysis` toggles memory reports. Requires `instanceddungeons.admin`. See [RAM Analysis](ram-analysis.md).", "text": "`/dungeon ram analysis` toggles memory reports. Requires `instanceddungeons.admin`. See [RAM Analysis](ram-analysis.md).", "url": "pro/commands/index.html#ram-analysis"}, {"group": "Start", "title": "Permissions", "section": "Permissions", "snippet": "| `instanceddungeons.admin` | op | Allows all admin setup commands. | | `instanceddungeons.skip.mission` | op | Allows skipping missions in the active stage without ...", "text": "| `instanceddungeons.admin` | op | Allows all admin setup commands. | | `instanceddungeons.skip.mission` | op | Allows skipping missions in the active stage without full admin access. | | `instanceddungeons.open` | true | Allows `/dungeon open`. | | `instanceddungeons.open.<dungeon_id>` | true | Allows opening one specific dungeon. | | `instanceddungeons.join` | true | Allows `/dungeon join`. | | `instanceddungeons.join.<dungeon_id>` | true | Allows joining one specific dungeon. | | `instanceddungeons.spectate` | true | Allows spectator commands. | | `instanceddungeons.bypass.limit` | op | Bypasses instance limits. | | `instanceddungeons.bypass.cost` | op | Bypasses dungeon entry costs. | Both global and dungeon-specific permissions must allow the action. Example: instanceddungeons.open instanceddungeons.open.dragon_lair", "url": "pro/permissions/index.html"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Dungeon Config", "snippet": "Every dungeon has a main config file: plugins/InstancedDungeons/dungeons/&lt;dungeon_id&gt;/config.yml The current dungeon format requires: v: 2.0 Dungeons without this ma...", "text": "Every dungeon has a main config file: plugins/InstancedDungeons/dungeons/<dungeon_id>/config.yml The current dungeon format requires: v: 2.0 Dungeons without this marker are blocked from opening. The optional `ram-analysis.yml` is a plugin-level diagnostic file, not a dungeon config. It is created only after an administrator runs `/dungeon ram analysis`; see [RAM Analysis](ram-analysis.md).", "url": "pro/configuration/index.html"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Core Fields", "snippet": "dungeon-type: single tower-stage-type: first next-dungeon: &quot;&quot; completion-objective: BOSS display-name: &quot;Dragon Lair&quot; template-world: &quot;dragon_template&quot; min-players: 1...", "text": "dungeon-type: single tower-stage-type: first next-dungeon: \"\" completion-objective: BOSS display-name: \"Dragon Lair\" template-world: \"dragon_template\" min-players: 1 max-players: 5 time-limit: 1800 | `dungeon-type` | `single` or `tower`. | | `tower-stage-type` | `first`, `middle`, or `last`. Used only for tower dungeons. | | `next-dungeon` | Next dungeon ID for tower transitions. | | `completion-objective` | `BOSS` or `TRIGGER`. | | `template-world` | Source world copied for each instance. | | `time-limit` | Run time in seconds. |", "url": "pro/configuration/index.html#core-fields"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Template World Defaults and Inheritance", "snippet": "When creating new template worlds with `/dg world create` or the **Create Template World** button in the admin GUI, the plugin applies the default rules from `plugin...", "text": "When creating new template worlds with `/dg world create` or the **Create Template World** button in the admin GUI, the plugin applies the default rules from `plugins/InstancedDungeons/config.yml`: template-worlds: freeze-ticks: true freeze-time: true freeze-weather: true natural-mob-spawning: false `freeze-ticks: true` sets the template world's random tick speed to `0` so leaves, ice, and crops do not decay or grow while building or running the dungeon. `freeze-time: true`, `freeze-weather: true`, and `natural-mob-spawning: false` disable daylight progression, weather changes, and natural mob spawns on newly created template worlds. All gamerules, the `WorldBorder` center/size/damage settings, and any **WorldGuard** regions and flags configured on the template world are automatically copied to every dungeon instance and cleaned up when the instance ends.", "url": "pro/configuration/index.html#template-world-defaults-and-inheritance"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Spawn and Exit", "snippet": "Spawn and exit are normally set in-game: /dungeon edit &lt;id&gt; /dungeon setspawn /dungeon setexit Players enter the instance at the dungeon spawn. Players are sent to t...", "text": "Spawn and exit are normally set in-game: /dungeon edit <id> /dungeon setspawn /dungeon setexit Players enter the instance at the dungeon spawn. Players are sent to the exit when they leave, fail, or complete the run.", "url": "pro/configuration/index.html#spawn-and-exit"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Announcements", "snippet": "announce-start: false announce-complete: false announce-fail: false `announce-start` broadcasts when a run starts. `announce-complete` broadcasts when a standalone d...", "text": "announce-start: false announce-complete: false announce-fail: false `announce-start` broadcasts when a run starts. `announce-complete` broadcasts when a standalone dungeon completes. In towers, this is controlled by the entry dungeon and is broadcast only after the final tower stage completes. `announce-fail` broadcasts when a standalone dungeon or whole tower fails. Tower complete/fail announcements use the entry dungeon's `announce-*` settings. Middle and last tower stage configs do not control global tower announcements.", "url": "pro/configuration/index.html#announcements"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Entry Costs", "snippet": "costs: money: 1000 items: - type: VANILLA item: DIAMOND amount: 2 If `require-all-players-pay` is `false`, only the leader pays. If it is `true`, every party member ...", "text": "costs: money: 1000 items: - type: VANILLA item: DIAMOND amount: 2 If `require-all-players-pay` is `false`, only the leader pays. If it is `true`, every party member must meet the cost. Tower rule: only `FIRST` tower stages may have entry costs.", "url": "pro/configuration/index.html#entry-costs"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Player Cooldowns", "snippet": "Configure this section in each **dungeon&#x27;s** `config.yml`, or open **Settings → Player Cooldown** in the admin GUI: player-cooldown: trigger: START recipients: LEADE...", "text": "Configure this section in each **dungeon's** `config.yml`, or open **Settings → Player Cooldown** in the admin GUI: player-cooldown: trigger: START recipients: LEADER dungeon-seconds: 0 global-seconds: 0 block-joining: false | `trigger` | `START`: successful run start; `END`: success or failure; `WIN`: success only. | | `recipients` | `LEADER`: leader captured at run start; `PARTY`: all party members captured at run start. | | `dungeon-seconds` | Blocks new entry to this dungeon ID for this many seconds. `0` grants no new dungeon cooldown. | | `global-seconds` | Blocks new entry to every dungeon for this many seconds. `0` grants no new global cooldown. | | `block-joining` | `false`: restricts creating/starting a new run as leader; `true`: also restricts joining another party. | The default durations are zero, so existing dungeons gain no restrictions after updating. Creating a party or failing to prepare a world does not grant a cooldown. Pending starts are checked before charges and preparation. Durations are wall-clock seconds, not server ticks. A join blocked by cooldown shows only the cooldown message and remaining seconds. Cooldowns belong to player UUIDs and survive relogging, reloads and server restarts in `plugins/InstancedDungeons/data/player-cooldowns.dat`. Back up that file when moving the server. A global cooldown also applies when the target dungeon has zero configured durations. When both an existing dungeon-specific and global deadline apply, entry stays blocked until both expire.", "url": "pro/configuration/index.html#player-cooldowns"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Towers and Replacement", "snippet": "Every tower floor may grant its own cooldown using its own config and trigger. Successfully clearing a non-final floor counts as that floor&#x27;s success for `END` and `...", "text": "Every tower floor may grant its own cooldown using its own config and trigger. Successfully clearing a non-final floor counts as that floor's success for `END` and `WIN`. Automatic transfer to the next floor bypasses entry checks, including global cooldowns. New deadlines **replace** old deadlines of the same scope; they are never added or compared to keep the maximum. For example, a new global cooldown of 800 seconds replaces an entry-floor global cooldown of 600 seconds. If 700 seconds remain and the next floor grants 300 seconds, 300 seconds remain from that new event. Dungeon-specific cooldowns remain separate by dungeon ID. A duration of zero grants no new cooldown and does not clear an already active one.", "url": "pro/configuration/index.html#towers-and-replacement"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Global Instance Limit", "snippet": "Configure how many dungeon instances may run globally. instances: max-active-global: 0 | `0` | No global active-instance ceiling. | | `1+` | Exact global active inst...", "text": "Configure how many dungeon instances may run globally. instances: max-active-global: 0 | `0` | No global active-instance ceiling. | | `1+` | Exact global active instance maximum. | Per-dungeon `max-instances` still controls the limit for that dungeon template.", "url": "pro/configuration/index.html#global-instance-limit"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Dungeon Scale", "snippet": "Dungeons support multiple stages, missions, key requirements, and payment items per dungeon.", "text": "Dungeons support multiple stages, missions, key requirements, and payment items per dungeon.", "url": "pro/configuration/index.html#dungeon-scale"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Protection", "snippet": "allow-block-break: false allow-block-place: false allow-fluid-place: false allow-fluid-take: false allow-interactions: true allow-party-pvp: true allow-fly: false fi...", "text": "allow-block-break: false allow-block-place: false allow-fluid-place: false allow-fluid-take: false allow-interactions: true allow-party-pvp: true allow-fly: false fire-spread: false `allow-fly: true` leaves flight already granted by a game mode, permission, or another plugin untouched. It never grants flight by itself. `false` forces flight off for active Survival and Adventure dungeon players and restores their previous flight state when they leave the dungeon. Creative and Spectator modes are exempt. This setting is also available under **Gameplay Rules** in the admin GUI. Trigger objectives and mission blocks can still work when normal interactions are blocked. `fire-spread: false` disables fire spreading in the template world and copied instances. Set it to `true` to allow spreading. Older 1.21.x uses `doFireTick`; from 1.21.11 the plugin uses `minecraft:fire_spread_radius_around_player`, with zero to disable spreading. The same toggle is available under **Settings → World Rules** in the admin GUI.", "url": "pro/configuration/index.html#protection"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Item Restrictions", "snippet": "Dungeons can block movement, teleport, combat, and consumable items inside their active instance: item-restrictions: block-elytra: false block-ender-pearls: false bl...", "text": "Dungeons can block movement, teleport, combat, and consumable items inside their active instance: item-restrictions: block-elytra: false block-ender-pearls: false block-chorus-fruit: false block-enchanted-golden-apples: false block-wind-charges: false block-firework-rockets: false block-mace: false block-trident: false All restrictions default to `false`, which keeps vanilla behavior. | `block-elytra` | Starting or continuing elytra flight. | | `block-ender-pearls` | Throwing an ender pearl and the resulting teleport. | | `block-chorus-fruit` | Eating chorus fruit and the resulting teleport. | | `block-enchanted-golden-apples` | Consuming enchanted golden apples. | | `block-wind-charges` | Using or launching wind charges. | | `block-firework-rockets` | Using, launching, or firing firework rockets from a crossbow. | | `block-mace` | Using a mace in melee combat. | | `block-trident` | Using a trident in melee combat or throwing it. | Restrictions apply only while the player belongs to an active dungeon instance and is physically inside that instance world. They can be edited from the dungeon settings GUI under **Item Restrictions**. New dungeons generate the complete section automatically. Missing restriction settings default to `false`. GUI changes are saved without altering other dungeon settings.", "url": "pro/configuration/index.html#item-restrictions"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Death Behavior", "snippet": "lives: scope: PLAYER amount: 1 death-behavior: ELIMINATE_AS_SPECTATOR fail-if-all-players-dead: true | `ELIMINATE_AS_SPECTATOR` | Eliminated players become dungeon s...", "text": "lives: scope: PLAYER amount: 1 death-behavior: ELIMINATE_AS_SPECTATOR fail-if-all-players-dead: true | `ELIMINATE_AS_SPECTATOR` | Eliminated players become dungeon spectators. | | `ELIMINATE_TO_EXIT` | Eliminated players are sent to the dungeon exit. | `scope: PLAYER` gives each player their own lives. `scope: TEAM` makes lives shared by the party.", "url": "pro/configuration/index.html#death-behavior"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Timer Bossbar", "snippet": "timer-bossbar: enabled: true color: GREEN style: SOLID show-time-left: true", "text": "timer-bossbar: enabled: true color: GREEN style: SOLID show-time-left: true", "url": "pro/configuration/index.html#timer-bossbar"}, {"group": "Configuration", "title": "Dungeon Config", "section": "Timer Alerts", "snippet": "Configure timer alert messages and sounds in `sounds.yml`. The legacy section below is ignored after migration. See [Dungeon Sounds](sounds.md). timer-alerts: 10-min...", "text": "Configure timer alert messages and sounds in `sounds.yml`. The legacy section below is ignored after migration. See [Dungeon Sounds](sounds.md). timer-alerts: 10-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 5-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 1-minute: enabled: true sound: ENTITY_EXPERIENCE_ORB_PICKUP", "url": "pro/configuration/index.html#timer-alerts"}, {"group": "Configuration", "title": "Objectives", "section": "Objectives", "snippet": "Every dungeon completes through one objective type: completion-objective: BOSS or: completion-objective: TRIGGER", "text": "Every dungeon completes through one objective type: completion-objective: BOSS or: completion-objective: TRIGGER", "url": "pro/objectives/index.html"}, {"group": "Configuration", "title": "Objectives", "section": "Boss Objective", "snippet": "Boss dungeons use: dungeons/&lt;id&gt;/boss.yml Set the boss spawn in editor mode: /dungeon edit dragon_lair /dungeon setboss Common config: boss: must-die-to-complete: tr...", "text": "Boss dungeons use: dungeons/<id>/boss.yml Set the boss spawn in editor mode: /dungeon edit dragon_lair /dungeon setboss Common config: boss: must-die-to-complete: true countdown-after-death: 30 When `must-die-to-complete` is `true`, the dungeon completion countdown starts after the boss dies.", "url": "pro/objectives/index.html#boss-objective"}, {"group": "Configuration", "title": "Objectives", "section": "Trigger Objective", "snippet": "Trigger dungeons use: dungeons/&lt;id&gt;/trigger.yml Set the trigger item and place it in the template world: /dungeon edit puzzle_room /dungeon settrigger STONE_BUTTON S...", "text": "Trigger dungeons use: dungeons/<id>/trigger.yml Set the trigger item and place it in the template world: /dungeon edit puzzle_room /dungeon settrigger STONE_BUTTON Supported trigger blocks are Minecraft buttons and pressure plates. Example: material: STONE_BUTTON location: world: \"puzzle_template\" x: 120 y: 65 z: 220 rewards: enabled: true items: - type: VANILLA item: DIAMOND amount: 2 chance: 100.0 Only one trigger can exist per dungeon. Placing a new trigger replaces the previous one. Trigger blocks ignore normal dungeon interaction blocking. They can still complete the run when regular interactions are disabled.", "url": "pro/objectives/index.html#trigger-objective"}, {"group": "Configuration", "title": "Objectives", "section": "Boss Stage Requirement", "snippet": "New `boss.yml` files include: stage-requirement: mode: DISABLED stage-id: &#x27;&#x27; | `DISABLED` | Uses the normal boss trigger without a stage requirement. This is also th...", "text": "New `boss.yml` files include: stage-requirement: mode: DISABLED stage-id: '' | `DISABLED` | Uses the normal boss trigger without a stage requirement. This is also the default for existing files. | | `STAGE` | Requires the stage named by `stage-id` to be completed. | | `ALL` | Requires every stage in the current dungeon to be completed. With no stages configured, there is nothing to wait for. | A stage is completed when all its missions are finished and its gate opens. Unlocking a stage does not complete it. Closing its gate later does not reset its completion. For example, require the `courtyard` stage before allowing the proximity trigger: trigger: ON_PLAYER_NEAR trigger-distance: 20 trigger-time: 0 stage-requirement: mode: STAGE stage-id: courtyard The stage requirement is an additional condition for every boss trigger: `ON_START`: waits until the stage requirement is met. `ON_DELAY`: starts its `trigger-time` delay after the requirement is met. `ON_PLAYER_NEAR`: requires an alive party member within range and the stage requirement to be met. `ON_PLAYER_NEAR_ON_DELAY`: starts its delay only once both conditions are met. If a player is already in range, the boss can activate as soon as the stage requirement is met. Spectators cannot trigger the boss. An invalid mode or missing stage ID in `STAGE` mode blocks spawning; `/dg validate <id>` reports the configuration error. In the admin GUI, open **Boss & Trigger**. **Boss Stage Requirement** cycles the mode; **Required Stage ID** accepts an existing stage only while `STAGE` mode is selected; it is inactive in `DISABLED` and `ALL`. Both settings are saved to `boss.yml`. Moving the boss spawn preserves them. **Test Boss Spawn** previews the boss without applying stage requirements.", "url": "pro/objectives/index.html#boss-stage-requirement"}, {"group": "Configuration", "title": "Objectives", "section": "Trigger Stage Requirement", "snippet": "Trigger objectives support the same completed-stage requirements as bosses. Add this to `trigger.yml`, or use **Trigger Stage Requirement** in the admin GUI: stage-r...", "text": "Trigger objectives support the same completed-stage requirements as bosses. Add this to `trigger.yml`, or use **Trigger Stage Requirement** in the admin GUI: stage-requirement: mode: STAGE stage-id: entrance `DISABLED`: no stage requirement. This is the default for new and existing trigger configs. `STAGE`: the named stage must be completed. `ALL`: every configured stage must be completed. With no stages configured, this requirement is satisfied. Before the requirement is met, interacting with the trigger does not complete the dungeon or give rewards. Use it again after completing the required stages. Unknown modes or missing stage IDs do not bypass the requirement; the validator reports configuration errors. The **Boss & Trigger** editor entry opens only the controls matching the dungeon's completion objective. **Required Stage ID** accepts input only in `STAGE` mode, for both objectives. Switching to `DISABLED` or `ALL` preserves the saved ID but ignores it.", "url": "pro/objectives/index.html#trigger-stage-requirement"}, {"group": "Configuration", "title": "Towers", "section": "Towers", "snippet": "Tower dungeons chain multiple dungeon templates into one run. dungeon-type: tower tower-stage-type: first next-dungeon: &quot;tower_floor_2&quot;", "text": "Tower dungeons chain multiple dungeon templates into one run. dungeon-type: tower tower-stage-type: first next-dungeon: \"tower_floor_2\"", "url": "pro/towers/index.html"}, {"group": "Configuration", "title": "Towers", "section": "Stage Types", "snippet": "| `first` | Entry point. Can be opened by command and may have entry costs. | | `middle` | Intermediate chain stage between the first and last dungeon. | | `last` | ...", "text": "| `first` | Entry point. Can be opened by command and may have entry costs. | | `middle` | Intermediate chain stage between the first and last dungeon. | | `last` | Final tower dungeon. Completing it completes the tower. |", "url": "pro/towers/index.html#stage-types"}, {"group": "Configuration", "title": "Towers", "section": "Tower Chains", "snippet": "Tower chains can be short or span several floors: FIRST -&gt; LAST FIRST -&gt; MIDDLE -&gt; LAST FIRST -&gt; MIDDLE -&gt; MIDDLE -&gt; ... -&gt; LAST `FIRST` and every `MIDDLE` stage mus...", "text": "Tower chains can be short or span several floors: FIRST -> LAST FIRST -> MIDDLE -> LAST FIRST -> MIDDLE -> MIDDLE -> ... -> LAST `FIRST` and every `MIDDLE` stage must define `next-dungeon`. `LAST` ends the chain and ignores `next-dungeon`.", "url": "pro/towers/index.html#tower-chains"}, {"group": "Configuration", "title": "Towers", "section": "Behavior", "snippet": "Players open only the `FIRST` dungeon directly. Completing `FIRST` moves the same party into `next-dungeon`. Completing a `MIDDLE` stage moves the same party into it...", "text": "Players open only the `FIRST` dungeon directly. Completing `FIRST` moves the same party into `next-dungeon`. Completing a `MIDDLE` stage moves the same party into its own `next-dungeon`. `FIRST` and `MIDDLE` use tower transition messages instead of normal completion messages. Completing `LAST` completes the tower and sends players to exit. Failure in any tower stage fails the whole tower. Entry costs are allowed only on `FIRST`.", "url": "pro/towers/index.html#behavior"}, {"group": "Configuration", "title": "Towers", "section": "Floor Cooldowns", "snippet": "Each floor may grant its own player cooldown. Automatic floor transitions are always allowed. New global deadlines replace existing ones, even when shorter; they are...", "text": "Each floor may grant its own player cooldown. Automatic floor transitions are always allowed. New global deadlines replace existing ones, even when shorter; they are not added together. See [Player Cooldowns](configuration.md#player-cooldowns) for configuration and START/END/WIN timing.", "url": "pro/towers/index.html#floor-cooldowns"}, {"group": "Configuration", "title": "Towers", "section": "Announcements", "snippet": "Tower global announcements are controlled by the entry dungeon. # In the FIRST dungeon config announce-complete: true announce-fail: true `announce-complete` is broa...", "text": "Tower global announcements are controlled by the entry dungeon. # In the FIRST dungeon config announce-complete: true announce-fail: true `announce-complete` is broadcast only after the final tower stage completes. The broadcast uses the final stage dungeon name. Set `announce-complete` in the FIRST dungeon. The same setting in MIDDLE or LAST does not control tower announcements.", "url": "pro/towers/index.html#announcements"}, {"group": "Configuration", "title": "Towers", "section": "Spectators During Tower Transitions", "snippet": "Players who become dungeon spectators through death or sacrifice stay with the party as spectators when the tower moves to the next stage. External spectators from `...", "text": "Players who become dungeon spectators through death or sacrifice stay with the party as spectators when the tower moves to the next stage. External spectators from `/dungeon spectate <leader>` move to the next stage with the party. Their original inventory and game mode are restored when they stop spectating or the run ends.", "url": "pro/towers/index.html#spectators-during-tower-transitions"}, {"group": "Configuration", "title": "Towers", "section": "Visibility", "snippet": "`/dungeon list` and `/dungeon open` tab completion hide tower middle/last stage dungeon IDs. Players reach those dungeons through tower progression.", "text": "`/dungeon list` and `/dungeon open` tab completion hide tower middle/last stage dungeon IDs. Players reach those dungeons through tower progression.", "url": "pro/towers/index.html#visibility"}, {"group": "Configuration", "title": "Complete Reference", "section": "Complete Reference", "snippet": "InstancedDungeons is a Paper plugin for creating isolated dungeon runs from template worlds. Each party gets a copied instance world, independent mobs, loot, objecti...", "text": "InstancedDungeons is a Paper plugin for creating isolated dungeon runs from template worlds. Each party gets a copied instance world, independent mobs, loot, objectives, stages, timers, protection rules, and cleanup after the run ends.", "url": "pro/complete-reference/index.html"}, {"group": "Configuration", "title": "Complete Reference", "section": "Table of Contents", "snippet": "Requirements Installation Core Concepts Quick Start Commands Permissions Dungeon Config Boss Objectives Trigger Objectives Towers Spawners Loot Chests Boss Rewards E...", "text": "Requirements Installation Core Concepts Quick Start Commands Permissions Dungeon Config Boss Objectives Trigger Objectives Towers Spawners Loot Chests Boss Rewards Entry Costs Parties and Instances Lives and Death Behavior Stages and Gates Stage Missions Event Commands Messages and Placeholders Validation Feature Limits Compatibility Notes Troubleshooting", "url": "pro/complete-reference/index.html#table-of-contents"}, {"group": "Configuration", "title": "Complete Reference", "section": "Requirements", "snippet": "| Paper 1.21.x | Java 21+ | Built-in (/dg world and Admin GUI) | | Paper 26.1.x / 26.2.x / 26.3.x | Java 25+ | Built-in (/dg world and Admin GUI) | One universal plu...", "text": "| Paper 1.21.x | Java 21+ | Built-in (/dg world and Admin GUI) | | Paper 26.1.x / 26.2.x / 26.3.x | Java 25+ | Built-in (/dg world and Admin GUI) | One universal plugin JAR supports both Paper 1.21.x and Paper 26.1.x / 26.2.x / 26.3.x. Optional integrations: WorldGuard for copying template world regions and flags into dungeon instances. MythicMobs 5.0+ for custom mobs and bosses. MythicMobs item support through `MYTHIC_ITEM` entries. ItemsAdder 3.0+ for custom items. Oraxen custom item support. Nexo custom item support. Vault plus an economy plugin for money entry costs and stage money missions.", "url": "pro/complete-reference/index.html#requirements"}, {"group": "Configuration", "title": "Complete Reference", "section": "Installation", "snippet": "Stop the server. Install the required Multiverse-Core version. Place `InstancedDungeons.jar` in `plugins/`. Start the server once so configs are generated. Configure...", "text": "Stop the server. Install the required Multiverse-Core version. Place `InstancedDungeons.jar` in `plugins/`. Start the server once so configs are generated. Configure dungeons in `plugins/InstancedDungeons/dungeons/`. Use `/dungeon reload` after YAML edits.", "url": "pro/complete-reference/index.html#installation"}, {"group": "Configuration", "title": "Complete Reference", "section": "Core Concepts", "snippet": "Template world: the original world that admins build in. It is copied for every run. Instance world: the temporary copied world used by one active party. Dungeon ID:...", "text": "Template world: the original world that admins build in. It is copied for every run. Instance world: the temporary copied world used by one active party. Dungeon ID: folder name under `dungeons/<id>`. This is used by commands, permissions, towers, and event commands. Party: players open or join a party before entering. Parties stay tracked while the run is active and close only after completion, failure, or abandonment cleanup. Objective: the condition that completes a dungeon. Supported objective types are `BOSS` and `TRIGGER`. Stage: an optional progression gate inside a dungeon. A stage can require missions before its gate opens. Tower: a chain of dungeons, from `FIRST -> LAST` to longer `FIRST -> MIDDLE -> ... -> LAST` routes.", "url": "pro/complete-reference/index.html#core-concepts"}, {"group": "Configuration", "title": "Complete Reference", "section": "Quick Start", "snippet": "Create a boss dungeon: /dg world create dragon_template void /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon se...", "text": "Create a boss dungeon: /dg world create dragon_template void /dungeon create dragon_lair dragon_template boss /dungeon edit dragon_lair /dungeon setspawn /dungeon setexit /dungeon setboss /dungeon save /dungeon reload Create a trigger dungeon: /dungeon create puzzle_room puzzle_template trigger /dungeon edit puzzle_room /dungeon setspawn /dungeon setexit /dungeon settrigger STONE_BUTTON /dungeon save /dungeon reload Start as a player: /dungeon open dragon_lair /dungeon join <code> /dungeon start", "url": "pro/complete-reference/index.html#quick-start"}, {"group": "Configuration", "title": "Complete Reference", "section": "Commands", "snippet": "Player commands: | `/dungeon help` | Shows player and admin help. | | `/dungeon list` | Lists available dungeons. Tower middle/last stage dungeons are hidden. | | `/...", "text": "Player commands: | `/dungeon help` | Shows player and admin help. | | `/dungeon list` | Lists available dungeons. Tower middle/last stage dungeons are hidden. | | `/dungeon open <id>` | Creates a party for a dungeon. Only standalone dungeons and tower `FIRST` stages are suggested/openable directly. | | `/dungeon join <code>` | Joins an open party. | | `/dungeon leave` | Leaves an open party. | | `/dungeon start` | Starts the party dungeon as the leader. | | `/dungeon exit` | Leaves the current dungeon instance. | | `/dungeon spectate <leader>` | Spectates the active dungeon led by that party leader. | | `/dungeon spectator exit` | Leaves external spectator mode and restores inventory/gamemode. | Admin commands: | `/dungeon create <id> <template-world> <boss\\|trigger>` | Creates a dungeon using the current config format. | | `/dungeon edit <id>` | Enters editor mode. Template teleport is controlled by `editor.teleport-to-template-on-edit` in `config.yml`. | | `/dungeon save` | Exits editor mode. | | `/dungeon setspawn` | Sets the dungeon spawn in editor mode. | | `/dungeon setexit` | Sets the exit location. | | `/dungeon setboss` | Sets the boss spawn for boss-objective dungeons. | | `/dungeon boss reward edit` | Opens the boss reward editor GUI. | | `/dungeon settrigger <button\\|pressure_plate>` | Gives the trigger block item for trigger-objective dungeons. | | `/dungeon trigger reward edit` | Opens the trigger reward editor GUI. | | `/dungeon addspawner <id>` | Creates a spawner config at the admin location. | | `/dungeon addlootchest <id>` | Creates a loot chest config. | | `/dungeon lootchest give <id>` | Gives a placeable loot chest item. | | `/dungeon lootchest loot <id> add` | Adds the item in your main hand to the loot chest config. Works only in editor mode. | | `/dungeon addcost` | Opens the entry cost editor. | | `/dungeon validate <id>` | Validates one dungeon and prints a summary. | | `/dungeon validate all` | Validates every dungeon. | | `/dungeon reload` | Reloads configs and validation. | | `/dungeon instances` | Shows active parties and instances. | | `/dg status` | Shows supported integration plugins, detected versions, and economy hook status. | | `/dungeon gui` | Opens the admin GUI. | | `/dungeon mythicmob [mobId]` | Lists or checks MythicMobs mob IDs. | | `/dungeon mythicitem [itemId]` | Lists or checks MythicMobs item IDs for `MYTHIC_ITEM` config entries. | | `/dungeon itemsadder [itemId]` | Lists or checks ItemsAdder IDs. | | `/dungeon oraxen [itemId]` | Lists or checks Oraxen IDs. | | `/dungeon nexo [itemId]` | Lists or checks Nexo IDs. | | `/dungeon delete <id>` | Deletes a dungeon after confirmation. | Stage commands: | `/dungeon stage create <stage_id>` | Creates a stage file. | | `/dungeon stage list` | Lists stages in the current editor dungeon with order, gate block count, and mission count. | | `/dungeon stage <stage_id> order <number>` | Moves a stage to another order. Multiple stages may share the same order and run in parallel. | | `/dungeon stage <stage_id> delete` | Deletes a stage after confirmation, including its missions, hologram config, gate blocks, and active gate edit session. | | `/dungeon stage <stage_id> gate create` | Starts gate block creation mode. | | `/dungeon stage <stage_id> gate edit` | Edits existing gate blocks. | | `/dungeon stage <stage_id> gate delete` | Deletes a gate after confirmation. | | `/dungeon stage <stage_id> gate stick` | Gives a gate edit stick during gate create/edit mode. Left-click adds one existing block, right-click removes one selected gate block, and sneak-click affects connected same-material blocks. | | `/dungeon gate save` | Saves the active gate edit session. | | `/dungeon stage <stage_id> gate hologram create` | Adds a stage hologram at your location in the dungeon template world. | | `/dungeon stage <stage_id> gate hologram delete` | Removes the nearest hologram for that stage within 3 blocks. | | `/dg stage <stage_id> mission region` | Creates the mission and shows the corner-selection commands. | | `/dg stage <stage_id> mission region pos1` | Saves your current template-world block as corner 1. | | `/dg stage <stage_id> mission region pos2` | Saves your current template-world block as corner 2. | | `/dg stage <stage_id> mission region delete` | Removes the region mission. | | `/dg skip <stage_id> mission <all\\|mission>` | Completes selected missions in an unlocked, unfinished stage. | | `/dungeon stage <stage_id> mission lever` | Gives a mission lever. | | `/dungeon stage <stage_id> mission button <material>` | Gives a mission button. | | `/dungeon stage <stage_id> mission pressure_plate <material>` | Gives a mission pressure plate. | Loot chest IDs, dungeon IDs, stage IDs, trigger materials, mission materials, and validation targets are completed where the command supports them. `/dungeon open` completion hides tower middle/last stage dungeon IDs because those stages are entered only through tower progression.", "url": "pro/complete-reference/index.html#commands"}, {"group": "Configuration", "title": "Complete Reference", "section": "Permissions", "snippet": "| `instanceddungeons.admin` | op | Admin/editor commands and admin-only warnings. | | `instanceddungeons.skip.mission` | op | Allows skipping missions in the active ...", "text": "| `instanceddungeons.admin` | op | Admin/editor commands and admin-only warnings. | | `instanceddungeons.skip.mission` | op | Allows skipping missions in the active stage without full admin access. | | `instanceddungeons.open` | true | Allows `/dungeon open`. | | `instanceddungeons.join` | true | Allows `/dungeon join`. | | `instanceddungeons.open.<dungeon_id>` | true | Allows opening a specific dungeon. | | `instanceddungeons.join.<dungeon_id>` | true | Allows joining a specific dungeon. | | `instanceddungeons.spectate` | true | Allows spectator commands. | | `instanceddungeons.bypass.cost` | op | Bypasses item and money entry costs. | | `instanceddungeons.bypass.limit` | op | Bypasses normal active-instance start checks. | Both global and dungeon-specific open/join permissions must allow the action.", "url": "pro/complete-reference/index.html#permissions"}, {"group": "Configuration", "title": "Complete Reference", "section": "Global Config", "snippet": "Main file: plugins/InstancedDungeons/config.yml Useful global options: debug: false editor: teleport-to-template-on-edit: false instances: max-active-global: 0 templ...", "text": "Main file: plugins/InstancedDungeons/config.yml Useful global options: debug: false editor: teleport-to-template-on-edit: false instances: max-active-global: 0 template-worlds: freeze-ticks: true freeze-time: true freeze-weather: true natural-mob-spawning: false `debug` enables additional console logging, including gate block add/remove messages while an admin is building gates. `editor.teleport-to-template-on-edit` controls `/dungeon edit <id>` teleport behavior. When `true`, the admin is teleported to the dungeon spawn if it is configured, otherwise to the template world's spawn. When `false`, editor mode starts without moving the admin. `instances.max-active-global: 0` disables the global instance limit. Positive values set the maximum number of active instances. Tower transitions reserve the current global instance slot while the next tower stage is being prepared. This prevents another party from taking the slot during the short handoff between tower stages. Instance world cleanup: Every dungeon run creates a temporary instance world copied from the template world. Normal completion, failure, abandon, and shutdown paths unload and delete the temporary world. The plugin marks the instance worlds it creates so cleanup can identify them. Automatic cleanup checks for leftover instance worlds in the background. Automatic cleanup deletes only worlds identified by an instance marker or an exact plugin world registration. Unmarked legacy folders are not automatically deleted. Worlds with players inside are skipped.", "url": "pro/complete-reference/index.html#global-config"}, {"group": "Configuration", "title": "Complete Reference", "section": "Dungeon Config", "snippet": "Main file: plugins/InstancedDungeons/dungeons/&lt;id&gt;/config.yml Important top-level fields: v: 2.0 dungeon-type: single tower-stage-type: first next-dungeon: &quot;&quot; comple...", "text": "Main file: plugins/InstancedDungeons/dungeons/<id>/config.yml Important top-level fields: v: 2.0 dungeon-type: single tower-stage-type: first next-dungeon: \"\" completion-objective: BOSS display-name: \"dragon_lair\" template-world: \"dragon_template\" max-players: 5 min-players: 1 time-limit: 1800 max-instances: 3 difficulty: NORMAL `dungeon-type` can be `single` or `tower`. `tower-stage-type` can be `first`, `middle`, or `last`. `MIDDLE` is an intermediate tower stage. `completion-objective` can be `BOSS` or `TRIGGER`. Protection: allow-block-break: false allow-block-place: false allow-fluid-place: false allow-fluid-take: false allow-interactions: true allow-party-pvp: true allow-fly: false fire-spread: false tnt-mode: VANILLA Allowing block breaking, block placement, or fluid placement does not remove protection from dungeon-owned gameplay blocks. Gates, mission blocks, completion/checkpoint triggers, loot chests, and emergency-return plates cannot be broken or replaced, and fluid flow is cancelled before reaching them. `allow-fly: true` leaves flight already granted by a game mode, permission, or another plugin untouched. It never grants flight by itself. `false` forces flight off for active Survival and Adventure dungeon players and restores their previous flight state when they leave the dungeon. Creative and Spectator modes are exempt. This setting is also available under **Gameplay Rules** in the admin GUI. `tnt-mode` options: `VANILLA`: normal TNT behavior. `ONLY_DMG`: TNT deals damage but does not break blocks. `DISABLED`: TNT is blocked. `fire-spread: false` disables fire spreading in the template world and copied instances. Set it to `true` to allow spreading. Older 1.21.x uses `doFireTick`; from 1.21.11 the plugin uses `minecraft:fire_spread_radius_around_player`, with zero to disable spreading. The same toggle is available under **Settings → World Rules** in the admin GUI. Item restrictions: item-restrictions: block-elytra: false block-ender-pearls: false block-chorus-fruit: false block-enchanted-golden-apples: false block-wind-charges: false block-firework-rockets: false block-mace: false block-trident: false All values default to `false`. Set a value to `true` to block that item or action while players are inside this dungeon's active instance. The same settings are available in the dungeon settings GUI under **Item Restrictions**. Existing dungeon configs do not need manual migration. Missing restriction values load as `false`, and changing a restriction in the GUI writes only this section without resetting unrelated dungeon settings. Timer: timer-bossbar: enabled: true color: GREEN style: SOLID show-time-left: true timer-alerts: 10-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 5-minutes: enabled: true sound: BLOCK_NOTE_BLOCK_PLING 1-minute: enabled: true sound: ENTITY_EXPERIENCE_ORB_PICKUP Validation warnings: validation-warnings: chat: true Console validation warnings are always logged. Chat validation warnings are sent only to admins and can be disabled per dungeon.", "url": "pro/complete-reference/index.html#dungeon-config"}, {"group": "Configuration", "title": "Complete Reference", "section": "Boss Objectives", "snippet": "Boss dungeons are created with: /dungeon create &lt;id&gt; &lt;template-world&gt; boss Use `/dungeon setboss` to create or update `boss.yml` at your location. Boss completion be...", "text": "Boss dungeons are created with: /dungeon create <id> <template-world> boss Use `/dungeon setboss` to create or update `boss.yml` at your location. Boss completion behavior: boss: must-die-to-complete: true countdown-after-death: 30 `must-die-to-complete` defaults to `true` in new configs. Boss reward editing: /dungeon boss reward edit The GUI stores every slot as an independent reward entry. For example, 4 diamonds in one slot and 2 diamonds in another slot become two separate rewards and can have different chances in config.", "url": "pro/complete-reference/index.html#boss-objectives"}, {"group": "Configuration", "title": "Complete Reference", "section": "Boss Stage Requirement", "snippet": "New `boss.yml` files include: stage-requirement: mode: DISABLED stage-id: &#x27;&#x27; | `DISABLED` | Uses the normal boss trigger without a stage requirement. This is also th...", "text": "New `boss.yml` files include: stage-requirement: mode: DISABLED stage-id: '' | `DISABLED` | Uses the normal boss trigger without a stage requirement. This is also the default for existing files. | | `STAGE` | Requires the stage named by `stage-id` to be completed. | | `ALL` | Requires every stage in the current dungeon to be completed. With no stages configured, there is nothing to wait for. | A stage is completed when all its missions are finished and its gate opens. Unlocking a stage does not complete it. Closing its gate later does not reset its completion. For example, require the `courtyard` stage before allowing the proximity trigger: trigger: ON_PLAYER_NEAR trigger-distance: 20 trigger-time: 0 stage-requirement: mode: STAGE stage-id: courtyard The stage requirement is an additional condition for every boss trigger: `ON_START`: waits until the stage requirement is met. `ON_DELAY`: starts its `trigger-time` delay after the requirement is met. `ON_PLAYER_NEAR`: requires an alive party member within range and the stage requirement to be met. `ON_PLAYER_NEAR_ON_DELAY`: starts its delay only once both conditions are met. If a player is already in range, the boss can activate as soon as the stage requirement is met. Spectators cannot trigger the boss. An invalid mode or missing stage ID in `STAGE` mode blocks spawning; `/dg validate <id>` reports the configuration error. In the admin GUI, open **Boss & Trigger**. **Boss Stage Requirement** cycles the mode; **Required Stage ID** accepts an existing stage only while `STAGE` mode is selected; it is inactive in `DISABLED` and `ALL`. Both settings are saved to `boss.yml`. Moving the boss spawn preserves them. **Test Boss Spawn** previews the boss without applying stage requirements.", "url": "pro/complete-reference/index.html#boss-stage-requirement"}, {"group": "Configuration", "title": "Complete Reference", "section": "Trigger Objectives", "snippet": "Trigger dungeons are created with: /dungeon create &lt;id&gt; &lt;template-world&gt; trigger Trigger dungeons do not generate a boss file. Instead, they use: dungeons/&lt;id&gt;/trigg...", "text": "Trigger dungeons are created with: /dungeon create <id> <template-world> trigger Trigger dungeons do not generate a boss file. Instead, they use: dungeons/<id>/trigger.yml The trigger is placed with: /dungeon settrigger <material> Supported trigger materials are Minecraft buttons and pressure plates. The trigger ignores dungeon interaction blocking so it can complete the run even when normal interactions are disabled. Only one trigger can exist per dungeon. Placing a new trigger replaces the previous one. After activation, the trigger is completed and further clicks do not run completion again. Trigger reward editing: /dungeon trigger reward edit Trigger rewards are saved in `trigger.yml` under `rewards`.", "url": "pro/complete-reference/index.html#trigger-objectives"}, {"group": "Configuration", "title": "Complete Reference", "section": "Trigger Stage Requirement", "snippet": "Trigger objectives support the same completed-stage requirements as bosses. Add this to `trigger.yml`, or use **Trigger Stage Requirement** in the admin GUI: stage-r...", "text": "Trigger objectives support the same completed-stage requirements as bosses. Add this to `trigger.yml`, or use **Trigger Stage Requirement** in the admin GUI: stage-requirement: mode: STAGE stage-id: entrance `DISABLED`: no stage requirement. This is the default for new and existing trigger configs. `STAGE`: the named stage must be completed. `ALL`: every configured stage must be completed. With no stages configured, this requirement is satisfied. Before the requirement is met, interacting with the trigger does not complete the dungeon or give rewards. Use it again after completing the required stages. Unknown modes or missing stage IDs do not bypass the requirement; the validator reports configuration errors. The **Boss & Trigger** editor entry opens only the controls matching the dungeon's completion objective. **Required Stage ID** accepts input only in `STAGE` mode, for both objectives. Switching to `DISABLED` or `ALL` preserves the saved ID but ignores it.", "url": "pro/complete-reference/index.html#trigger-stage-requirement"}, {"group": "Configuration", "title": "Complete Reference", "section": "Towers", "snippet": "Tower dungeons chain multiple dungeon templates. dungeon-type: tower tower-stage-type: first next-dungeon: &quot;tower_final&quot; Stage types: `first`: entry point. Can be op...", "text": "Tower dungeons chain multiple dungeon templates. dungeon-type: tower tower-stage-type: first next-dungeon: \"tower_final\" Stage types: `first`: entry point. Can be opened by command and may have entry costs. `middle`: intermediate chain stage between the first and last dungeon. `last`: final tower dungeon. Completing it finishes the tower. Tower chains: `FIRST -> LAST` `FIRST -> MIDDLE -> LAST` `FIRST -> MIDDLE -> MIDDLE -> ... -> LAST` `FIRST` and every `MIDDLE` stage must define `next-dungeon`. `LAST` completes the tower and ignores `next-dungeon`. Tower behavior: Completing `FIRST` teleports the same party to `next-dungeon`. `FIRST` and `MIDDLE` use tower transition messages, not normal dungeon completion messages. Global tower completion/failure announcements use the `announce-*` settings from the tower entry dungeon (`FIRST`) only. `announce-complete` is broadcast only after the final tower stage completes, and the announcement uses the final stage dungeon name. Dungeon players who became spectators through death or sacrifice stay spectators when the party moves to the next tower stage. Entry costs are allowed only on `FIRST`. Failure in any tower stage fails the whole tower and teleports players to that stage's exit.", "url": "pro/complete-reference/index.html#towers"}, {"group": "Configuration", "title": "Complete Reference", "section": "Spawners", "snippet": "Spawner files live in: dungeons/&lt;id&gt;/spawners/&lt;spawner_id&gt;.yml Example: location: world: dragon_template x: 100.5 y: 64.0 z: 200.5 trigger: ON_PLAYER_NEAR trigger-di...", "text": "Spawner files live in: dungeons/<id>/spawners/<spawner_id>.yml Example: location: world: dragon_template x: 100.5 y: 64.0 z: 200.5 trigger: ON_PLAYER_NEAR trigger-distance: 20 trigger-time: 5 lifetime-behavior: PERSIST lifetime-seconds: 0 mob-pools: - type: VANILLA mob-id: ZOMBIE count: 5 chance: 100.0 drop-vanilla-loot: false - type: MYTHIC mob-id: SkeletonKing count: 1 chance: 35.0 Trigger modes: `ON_START`: spawn when the instance starts. This mode is not recommended for regular spawners because it can spawn every configured mob immediately at dungeon startup; prefer `ON_PLAYER_NEAR` for normal gameplay. `ON_PLAYER_NEAR`: spawn when a player enters `trigger-distance`. `ON_DELAY`: spawn after `trigger-time`. `ON_PLAYER_NEAR_ON_DELAY`: start `trigger-time` after a player enters `trigger-distance`. Spawners default to `ON_PLAYER_NEAR` with `trigger-distance: 20`. The selected trigger determines whether `trigger-distance`, `trigger-time`, or both apply. Mob pools can mix vanilla and MythicMobs entries in one spawner. `drop-vanilla-loot: false` removes normal drops from spawned vanilla mobs, such as bones, arrows, rotten flesh, and evoker totems. If the same pool has configured equipment, armor and tool drop chances from the `equipment` section still work. To keep mobs such as piglins or hoglins from transforming into zombified variants outside their native dimension, manually add `prevent-zombification: true` to that mob pool: mob-pools: - type: VANILLA mob-id: PIGLIN count: 1 chance: 100.0 drop-vanilla-loot: false prevent-zombification: true To stop baby variants from spawning from a pool, manually add `prevent-baby-spawns: true`: mob-pools: - type: VANILLA mob-id: PIGLIN count: 3 chance: 100.0 drop-vanilla-loot: false prevent-zombification: true prevent-baby-spawns: true This forces supported ageable mobs into adult form, such as piglins, zombies, zombified piglins, and hoglins. Vanilla mob equipment: mob-pools: - type: VANILLA mob-id: SKELETON count: 1 chance: 100.0 equipment: helmet: item: IRON_HELMET drop-chance: 10.0 chestplate: item: IRON_CHESTPLATE drop-chance: 10.0 leggings: item: IRON_LEGGINGS drop-chance: 10.0 boots: item: IRON_BOOTS drop-chance: 10.0 main-hand: item: IRON_SWORD drop-chance: 5.0 enchants: SHARPNESS: 1 off-hand: item: SHIELD drop-chance: 0.0 Supported vanilla equipment mobs include zombies, zombie villagers, husks, drowned, skeletons, strays, wither skeletons, bogged, piglins, piglin brutes, zombified piglins, vindicators, pillagers, evokers, and illusioners. Unsupported mobs spawn without configured equipment and validation warns admins.", "url": "pro/complete-reference/index.html#spawners"}, {"group": "Configuration", "title": "Complete Reference", "section": "Mob Lifetime", "snippet": "lifetime-behavior: PERSIST lifetime-seconds: 0 `PERSIST` and `PERSIST_UNTIL_DUNGEON_END` prevent natural distance despawning during the instance. This also applies t...", "text": "lifetime-behavior: PERSIST lifetime-seconds: 0 `PERSIST` and `PERSIST_UNTIL_DUNGEON_END` prevent natural distance despawning during the instance. This also applies to `ON_START` mobs spawned far from players. Entities are saved across chunk unloading and reloading. Both modes still remove mobs when the instance is cleaned up or its world is deleted; neither keeps an instance running after it ends. `DESPAWN_AFTER_TIME` removes the mob after a positive `lifetime-seconds` duration. Its deadline is retained through chunk unloading and mob transformations. Keep `lifetime-seconds` positive when using this mode. These settings cover Vanilla and MythicMobs spawned by the dungeon. Another plugin that explicitly removes an entity can still remove it.", "url": "pro/complete-reference/index.html#mob-lifetime"}, {"group": "Configuration", "title": "Complete Reference", "section": "Loot Chests", "snippet": "Loot chest files live in: dungeons/&lt;id&gt;/loot-chests/&lt;loot_id&gt;.yml Use: /dungeon addlootchest treasure_room /dungeon lootchest give treasure_room /dungeon lootchest l...", "text": "Loot chest files live in: dungeons/<id>/loot-chests/<loot_id>.yml Use: /dungeon addlootchest treasure_room /dungeon lootchest give treasure_room /dungeon lootchest loot treasure_room add `/dungeon lootchest loot <id> add` adds the item in your main hand to the loot table. It detects vanilla items, supported custom item providers, potions, tipped arrows, and enchanted books. The new entry uses `min-amount: 1`, `max-amount: 1`, and `chance: 100.0`. Example: min-items-per-drop: 2 max-items-per-drop: 4 loot-table: - type: VANILLA item: DIAMOND min-amount: 1 max-amount: 3 chance: 75.0 - type: ITEMSADDER item: coins:bronze_coin min-amount: 1 max-amount: 3 chance: 25.0 Supported item providers: `VANILLA` `ITEMSADDER` `ORAXEN` `NEXO` `MYTHIC_ITEM` `MISSION`, for stage keys Mission key loot entry: # - type: MISSION # item: KEY # stage: 1 # quantity: 1 # lore: # - \"&7A key used to unlock a dungeon stage.\" `MISSION KEY` entries are guaranteed key supply entries, not random loot rolls. They ignore `chance` and do not count toward `min-items-per-drop` or `max-items-per-drop`. `quantity` means how many keys this loot chest definition should provide per dungeon instance. When an instance starts, the plugin chooses random physical loot chests of that loot chest ID and assigns the keys to those chests. If chunks are not loaded yet, the assignment is refreshed shortly after start and can fall back to the opened chest of the matching loot chest ID. If `quantity` is higher than the number of physical chests of that ID, selected chests can contain more than one key. Example: if a `REQUIRED_KEY` mission needs 3 keys, configure the stage mission with `required: 3`, then put `quantity: 2` in the Bronze loot chest config and `quantity: 1` in the Silver loot chest config. Mission key loot entries should normally be in loot chests reachable before the related gate. Mission keys are bound to the instance where they dropped and are removed when the player leaves that instance.", "url": "pro/complete-reference/index.html#loot-chests"}, {"group": "Configuration", "title": "Complete Reference", "section": "Boss Rewards", "snippet": "Boss rewards are configured per dungeon and support custom items from the same providers as loot where available. Reward entries are independent. Stacked items in se...", "text": "Boss rewards are configured per dungeon and support custom items from the same providers as loot where available. Reward entries are independent. Stacked items in separate GUI slots stay separate reward entries and can have separate chance values in the config. `reward-logic` controls whether rolled boss rewards go to inventories or form a public pile at the boss spawn. Recipient and delivery combinations are validated before the dungeon can open. See [Loot and Rewards](loot-and-rewards.md#boss-rewards). Edit boss rewards while editing a boss-objective dungeon: /dungeon boss reward edit Common fields: boss-rewards: enabled: true rewards: - type: VANILLA item: DIAMOND amount: 4 chance: 100.0", "url": "pro/complete-reference/index.html#boss-rewards"}, {"group": "Configuration", "title": "Complete Reference", "section": "Trigger Rewards", "snippet": "Trigger rewards are configured in `dungeons/&lt;id&gt;/trigger.yml` and are distributed according to its `reward-logic` when the trigger completes the dungeon. Edit trigge...", "text": "Trigger rewards are configured in `dungeons/<id>/trigger.yml` and are distributed according to its `reward-logic` when the trigger completes the dungeon. Edit trigger rewards while editing a trigger-objective dungeon: /dungeon trigger reward edit The trigger reward GUI follows the same independent-entry behavior as boss rewards: separate inventory slots become separate reward entries with separate chances in config.", "url": "pro/complete-reference/index.html#trigger-rewards"}, {"group": "Configuration", "title": "Complete Reference", "section": "Entry Costs", "snippet": "Entry costs are stored in the dungeon config: costs: money: 1000 items: - type: VANILLA item: DIAMOND amount: 2 If `require-all-players-pay` is `false`, the leader p...", "text": "Entry costs are stored in the dungeon config: costs: money: 1000 items: - type: VANILLA item: DIAMOND amount: 2 If `require-all-players-pay` is `false`, the leader pays. If it is `true`, every party member must meet the cost. Tower rule: only `FIRST` tower dungeons may have entry costs.", "url": "pro/complete-reference/index.html#entry-costs"}, {"group": "Configuration", "title": "Complete Reference", "section": "Player Cooldowns", "snippet": "Configure this section in each **dungeon&#x27;s** `config.yml`, or open **Settings → Player Cooldown** in the admin GUI: player-cooldown: trigger: START recipients: LEADE...", "text": "Configure this section in each **dungeon's** `config.yml`, or open **Settings → Player Cooldown** in the admin GUI: player-cooldown: trigger: START recipients: LEADER dungeon-seconds: 0 global-seconds: 0 block-joining: false | `trigger` | `START`: successful run start; `END`: success or failure; `WIN`: success only. | | `recipients` | `LEADER`: leader captured at run start; `PARTY`: all party members captured at run start. | | `dungeon-seconds` | Blocks new entry to this dungeon ID for this many seconds. `0` grants no new dungeon cooldown. | | `global-seconds` | Blocks new entry to every dungeon for this many seconds. `0` grants no new global cooldown. | | `block-joining` | `false`: restricts creating/starting a new run as leader; `true`: also restricts joining another party. | The default durations are zero, so existing dungeons gain no restrictions after updating. Creating a party or failing to prepare a world does not grant a cooldown. Pending starts are checked before charges and preparation. Durations are wall-clock seconds, not server ticks. A join blocked by cooldown shows only the cooldown message and remaining seconds. Cooldowns belong to player UUIDs and survive relogging, reloads and server restarts in `plugins/InstancedDungeons/data/player-cooldowns.dat`. Back up that file when moving the server. A global cooldown also applies when the target dungeon has zero configured durations. When both an existing dungeon-specific and global deadline apply, entry stays blocked until both expire.", "url": "pro/complete-reference/index.html#player-cooldowns"}, {"group": "Configuration", "title": "Complete Reference", "section": "Towers and Replacement", "snippet": "Every tower floor may grant its own cooldown using its own config and trigger. Successfully clearing a non-final floor counts as that floor&#x27;s success for `END` and `...", "text": "Every tower floor may grant its own cooldown using its own config and trigger. Successfully clearing a non-final floor counts as that floor's success for `END` and `WIN`. Automatic transfer to the next floor bypasses entry checks, including global cooldowns. New deadlines **replace** old deadlines of the same scope; they are never added or compared to keep the maximum. For example, a new global cooldown of 800 seconds replaces an entry-floor global cooldown of 600 seconds. If 700 seconds remain and the next floor grants 300 seconds, 300 seconds remain from that new event. Dungeon-specific cooldowns remain separate by dungeon ID. A duration of zero grants no new cooldown and does not clear an already active one.", "url": "pro/complete-reference/index.html#towers-and-replacement"}, {"group": "Configuration", "title": "Complete Reference", "section": "Special Vanilla Item IDs", "snippet": "Special vanilla item IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. They can also be captured automatically fr...", "text": "Special vanilla item IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. They can also be captured automatically from the cost editor GUI, reward editor GUI, and `/dungeon lootchest loot <id> add`. Potions, splash potions, lingering potions, and tipped arrows use: - type: VANILLA item: POTION_LONG_POISON min-amount: 1 max-amount: 3 chance: 100.0 The first part is one of: `POTION` `SPLASH_POTION` `LINGERING_POTION` `TIPPED_ARROW` The effect part is one of: `LONG_` variants use Minecraft's extended-duration potion type. `STRONG_` variants use Minecraft's upgraded stronger potion type where vanilla provides one. NIGHT_VISION LONG_NIGHT_VISION INVISIBILITY LONG_INVISIBILITY LEAPING LONG_LEAPING STRONG_LEAPING FIRE_RESISTANCE LONG_FIRE_RESISTANCE SWIFTNESS LONG_SWIFTNESS STRONG_SWIFTNESS SLOWNESS LONG_SLOWNESS STRONG_SLOWNESS WATER_BREATHING LONG_WATER_BREATHING HEALING STRONG_HEALING HARMING STRONG_HARMING POISON LONG_POISON STRONG_POISON REGENERATION LONG_REGENERATION STRONG_REGENERATION STRENGTH LONG_STRENGTH STRONG_STRENGTH WEAKNESS LONG_WEAKNESS LUCK SLOW_FALLING LONG_SLOW_FALLING TURTLE_MASTER LONG_TURTLE_MASTER STRONG_TURTLE_MASTER INFESTED OOZING WEAVING WIND_CHARGED Examples: - type: VANILLA item: SPLASH_POTION_STRONG_HEALING min-amount: 1 max-amount: 1 chance: 100.0 - type: VANILLA item: TIPPED_ARROW_SLOW_FALLING min-amount: 4 max-amount: 8 chance: 50.0 Enchanted books use: ENCHANTED_BOOK_<ENCHANTMENT>_<LEVEL> Example: - type: VANILLA item: ENCHANTED_BOOK_SHARPNESS_4 min-amount: 1 max-amount: 1 chance: 100.0 The level cannot be higher than the vanilla max level of that enchantment. For example, `ENCHANTED_BOOK_SHARPNESS_5` is valid, but `ENCHANTED_BOOK_SHARPNESS_6` is rejected by validation. Common enchanted book IDs: ENCHANTED_BOOK_SHARPNESS_5 ENCHANTED_BOOK_PROTECTION_4 ENCHANTED_BOOK_EFFICIENCY_5 ENCHANTED_BOOK_UNBREAKING_3 ENCHANTED_BOOK_MENDING_1 ENCHANTED_BOOK_FORTUNE_3 ENCHANTED_BOOK_LOOTING_3 ENCHANTED_BOOK_POWER_5 ENCHANTED_BOOK_PIERCING_4 ENCHANTED_BOOK_DENSITY_5 Supported enchantment names are taken from the server enchantment registry. On the Paper 26.x build line this includes: PROTECTION FIRE_PROTECTION FEATHER_FALLING BLAST_PROTECTION PROJECTILE_PROTECTION RESPIRATION AQUA_AFFINITY THORNS DEPTH_STRIDER FROST_WALKER BINDING_CURSE SHARPNESS SMITE BANE_OF_ARTHROPODS KNOCKBACK FIRE_ASPECT LOOTING SWEEPING_EDGE EFFICIENCY SILK_TOUCH UNBREAKING FORTUNE POWER PUNCH FLAME INFINITY LUCK_OF_THE_SEA LURE LOYALTY IMPALING RIPTIDE CHANNELING MULTISHOT QUICK_CHARGE PIERCING DENSITY BREACH WIND_BURST MENDING VANISHING_CURSE SOUL_SPEED SWIFT_SNEAK LUNGE Special vanilla drops follow their vanilla stack limits. Potions, splash potions, lingering potions, and enchanted books are split into one-item stacks, while tipped arrows can stack normally up to their item stack limit. The plugin stores enchanted armor, tools, and weapons as vanilla items with an `enchants` map. The same format works in loot chests, boss rewards, trigger rewards, entry costs, item payment missions, and mob equipment. - type: VANILLA item: DIAMOND_CHESTPLATE amount: 1 enchants: PROTECTION: 4 UNBREAKING: 3", "url": "pro/complete-reference/index.html#special-vanilla-item-ids"}, {"group": "Configuration", "title": "Complete Reference", "section": "Parties and Instances", "snippet": "Party states in 2.0: `OPEN`: players can join and the leader can start. `PREPARING_START`: instance world is being prepared and countdown is running. `IN_DUNGEON`: p...", "text": "Party states in 2.0: `OPEN`: players can join and the leader can start. `PREPARING_START`: instance world is being prepared and countdown is running. `IN_DUNGEON`: players are inside an active run. `COMPLETED`: run completed and party is closing. `ABANDONED`: run failed or was abandoned and party is closing. Parties close when the run ends, the party times out or disbands, or the server shuts down. Players who are not part of the active instance are removed if they enter an instance world through external plugins, vehicles, teleports, or other non-dungeon mechanics.", "url": "pro/complete-reference/index.html#parties-and-instances"}, {"group": "Configuration", "title": "Complete Reference", "section": "Remove a Party Member", "snippet": "`/dg kick &lt;player&gt;` removes a member from the leader&#x27;s open party. Tab completion suggests only other members of that party. The leader cannot kick themselves, playe...", "text": "`/dg kick <player>` removes a member from the leader's open party. Tab completion suggests only other members of that party. The leader cannot kick themselves, players outside the party, or anyone after dungeon preparation has begun. The removed player and the remaining party receive configurable messages. No extra permission is required beyond being that party's leader. Kicking removes the current membership; it does not ban the player from joining an open party again.", "url": "pro/complete-reference/index.html#remove-a-party-member"}, {"group": "Configuration", "title": "Complete Reference", "section": "Lives and Death Behavior", "snippet": "Lives config: lives: scope: PLAYER amount: 0 `amount: 0` means unlimited lives. `scope: PLAYER` means each player has their own death counter. `scope: TEAM` means de...", "text": "Lives config: lives: scope: PLAYER amount: 0 `amount: 0` means unlimited lives. `scope: PLAYER` means each player has their own death counter. `scope: TEAM` means deaths are shared by the whole party. Death behavior: `INFINITE_RESPAWN`: respawn at the dungeon start when lives are unlimited. `ELIMINATE_AS_SPECTATOR`: after the configured player/team lives run out, eliminated players become dungeon spectators. `ELIMINATE_TO_EXIT`: after the configured player/team lives run out, eliminated players are sent to the dungeon exit. Legacy values `ONE_LIFE_SPECTATOR` and `ONE_LIFE_KICK` are still read for compatibility, but current configs should use the names above. Death announcements follow the configured lives scope. With `scope: PLAYER`, the party sees the dead player's remaining lives. With `scope: TEAM`, the party sees the remaining shared team lives. When lives reach zero, the message also reflects whether the player became a spectator or was sent to the exit. Death spectators and external spectators are different systems: Death spectators are still dungeon participants, but they are marked as eliminated and are excluded from alive-player checks and sacrifice mission target lists. If all real dungeon players are eliminated and `fail-if-all-players-dead: true`, the dungeon or tower fails. Death spectators keep items only when the dungeon or world death rules preserve their inventory. Items lost on death are not restored at the end of the run. Death spectators and sacrificed players who were original dungeon players are sent to the dungeon exit when they leave the run or when the run ends. External spectators who joined with `/dungeon spectate <leader>` are not participants, cannot progress missions, and receive their saved inventory/gamemode back when they exit or the run ends.", "url": "pro/complete-reference/index.html#lives-and-death-behavior"}, {"group": "Configuration", "title": "Complete Reference", "section": "Stages and Gates", "snippet": "Stages live in: dungeons/&lt;id&gt;/stages/&lt;stage_id&gt;.yml dungeons/&lt;id&gt;/stages/&lt;stage_id&gt;-hologram.yml Every stage has an order: stage-id: entrance stage-order: 1 gate: di...", "text": "Stages live in: dungeons/<id>/stages/<stage_id>.yml dungeons/<id>/stages/<stage_id>-hologram.yml Every stage has an order: stage-id: entrance stage-order: 1 gate: disappear-seconds: 6 missions: - type: LEVER required: 1 # Saved at the bottom because large gates can contain many coordinates. gate-blocks: - x: 10 y: 64 z: 20 Stage orders are progression priorities. Order `1` is the lowest and unlocks first. Multiple stages may share the same order, which means they can be progressed in parallel. Higher order stages unlock only after every lower-order stage has opened. Used order groups must still be continuous: `1`, `2`, `3`, and so on. For example, using orders `1` and `3` without any order `2` is invalid. Use the stage file ID in admin commands, even when several stages share an order. For example: /dungeon stage entrance gate create Use `/dungeon stage list` in editor mode to see the current order. New stages get the next order automatically based on creation order. To change order without editing YAML, use: /dungeon stage <stage_id> order <number> If the target order is already used, the moved stage joins that order group instead of swapping. Stages with the same order can be completed in any order, but every stage in that order must open before the next order unlocks. Gate editing: /dungeon stage entrance gate create place gate blocks /dungeon gate save While gate edit mode is active, the action bar turns purple and selected gate blocks show subtle purple dust particles to admins editing that dungeon. Multiple admins can join the same stage gate edit session and work on the same gate together. During an active gate create/edit session, `/dungeon stage <stage_id> gate stick` gives an enchanted gate edit stick. Left-click adds the clicked existing block to the active gate without placing a new block. Right-click removes the clicked block from the active gate selection without breaking it. Sneak-left-click adds connected same-material blocks, and sneak-right-click removes connected same-material blocks from the selection. Split large connected-block selections into smaller operations. The final selection is still saved with `/dungeon gate save`. Manual block placement and breaking are tracked immediately. WorldEdit `//set` is also supported during active gate create/edit mode: after the command runs, the plugin reads the admin's current WorldEdit selection and adds every non-air block in that selection to the active gate selection. Split large WorldEdit selections into smaller operations. Changes made with vanilla `/setblock` and `/fill` near the gate are also detected. Replacing existing blocks with the same material through commands is still best handled by WorldEdit `//set` selection sync or the gate stick. Gate holograms: /dungeon stage entrance gate hologram create The hologram shows live mission progress. Completed missions turn green and receive the configured completed prefix. Clickable missions such as `SACRIFICE`, `MONEY_PAYMENT`, and `ITEM_PAYMENT` add an instruction line that explains who should right-click a gate block, for example `Leader must right-click a gate block for Sacrifice.` or per-mission action lines when multiple clickable missions are active. You can create multiple holograms for the same stage by running the create command again at another location. The delete command removes the nearest hologram for that stage within 3 blocks. Locked higher-order holograms show the missing previous stage names, for example `Complete Entrance first.` The create command must be run while standing in the dungeon template world. If editor mode is configured not to teleport admins automatically, move to the template world first before creating stage holograms. The hologram appears above your position. In editor mode, stage holograms are also visible in the template world. Previews show the title and configured missions, and refresh after hologram or mission changes. If the stage has no missions yet, only the hologram title is shown.", "url": "pro/complete-reference/index.html#stages-and-gates"}, {"group": "Configuration", "title": "Complete Reference", "section": "Stage Missions", "snippet": "Configure stage order, missions, key requirements, and payment items in each stage file. Mission levers belonging to locked future stages cannot be pulled. They beco...", "text": "Configure stage order, missions, key requirements, and payment items in each stage file. Mission levers belonging to locked future stages cannot be pulled. They become available when their stage unlocks. Mission types: | `REGION` | Enter or remain in a selected cuboid, individually or as a party. | | `KILL_MOBS` | Party must kill a configured number of mobs. | | `LEVER` | Party must pull all placed mission levers. | | `BUTTON` | Party must press all mission buttons at the same time. | | `PRESSURE_PLATE` | Party must activate all mission plates at the same time. | | `REQUIRED_KEY` | Players must submit mission keys by right-clicking any block of the gate with the key in hand. `required` is the number of keys needed to unlock the gate. | | `TIME` | Waits a configured number of seconds after the active stage starts. | | `SACRIFICE` | Requires selecting players to eliminate through the mission GUI. Open it by right-clicking any block of the stage gate. `sacrifice-outcome` controls whether the sacrificed player becomes a spectator or is kicked out of the dungeon, independently from dungeon death behavior. `sacrifice-drop-items: false` keeps the player's inventory; `true` drops storage, armor, and offhand items on the ground. | | `MONEY_PAYMENT` | Requires a Vault money payment. Open it by right-clicking any block of the stage gate. Cannot be added unless Vault and an economy provider are detected. | | `ITEM_PAYMENT` | Requires configured items. Open it by right-clicking any block of the stage gate during a run. Configure required items with `/dungeon stage <stage_id> mission item_payment`, which opens an editor GUI and saves the inserted supported items into the stage config. | Mission creation commands: /dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 /dg stage <stage_id> mission region pos2 /dg stage <stage_id> mission region delete /dungeon stage <stage_id> mission kill_mobs <amount> /dungeon stage <stage_id> mission lever /dungeon stage <stage_id> mission button <button_material> /dungeon stage <stage_id> mission pressure_plate <plate_material> /dungeon stage <stage_id> mission required_key <amount> /dungeon stage <stage_id> mission time <seconds> /dungeon stage <stage_id> mission sacrifice [LEADER_SELECTS|PARTY_VOTE|FIRST_PLAYER_DECISION] [drop_items] /dungeon stage <stage_id> mission money_payment <amount> [ANY_PLAYER|LEADER_ONLY] /dungeon stage <stage_id> mission item_payment /dungeon stage <stage_id> mission <type> delete The `ITEM_PAYMENT` command opens a 27-slot item editor. Add vanilla, ItemsAdder, Oraxen, Nexo, or MythicMobs items, then close it to save. Run the command again to edit the saved items. Set `payment-mode` to `ANY_PLAYER` or `LEADER_ONLY` in the stage config. Mission lever/button/pressure-plate blocks can be moved while in editor mode. Break the mission block to remove it from the stage, then place a new mission block where you want it. If the last block for that mission is removed, the mission is removed from the stage file too. Mission YAML is saved with only the fields that apply to that mission type: | `REGION` | `type`, `region`, optional `lore` | | `KILL_MOBS` | `type`, `required`, `only-dungeon-spawner-mobs`, `count-baby-variants` | | `LEVER` | `type`, `required`, `blocks` | | `BUTTON` | `type`, `required`, `blocks` | | `PRESSURE_PLATE` | `type`, `required`, `blocks` | | `REQUIRED_KEY` | `type`, `required` | | `TIME` | `type`, `duration-seconds` | | `SACRIFICE` | `type`, `required`, `sacrifice-mode`, `sacrifice-outcome`, `sacrifice-drop-items`, optional `lore` | | `MONEY_PAYMENT` | `type`, `payment-mode`, `money-amount`, optional `lore` | | `ITEM_PAYMENT` | `type`, `payment-mode`, `items`, optional `lore` | Mission GUI: Mission items cannot be moved. Sacrifice selection opens a second GUI with player heads. Sacrifice announces the chosen player. If the sacrificed player is the current leader, a random alive dungeon player becomes the new leader and the party is notified. The same leader reassignment is used when the leader loses all lives. Player-facing mission names come from `messages.yml` under `mission-names`. Config files and commands still use internal mission IDs such as `REQUIRED_KEY`. Each mission can define custom GUI icon lore with a `lore:` list in the stage file. Mission lore placeholders: `%mission%`, `%current%`, `%required%`, `%money%`, `%items%`. For `REQUIRED_KEY`, configure how many keys must be found in each loot chest type with `MISSION KEY` entries in the related loot chest configs. Example mission lore: missions: - type: MONEY_PAYMENT required: 1 payment-mode: ANY_PLAYER money-amount: 500 lore: - \"&7Pay &6500 &7coins to unlock the gate.\" - \"&8Progress: %current%/%required%\" Stage progress isolation: Only unlocked stages receive kill/time/payment progress. Stages with the same order can receive progress at the same time. Later stage holograms stay locked until every lower-order stage opens and show the missing previous stage names. If a player bypasses a gate, later holograms show the locked previous-stage message.", "url": "pro/complete-reference/index.html#stage-missions"}, {"group": "Configuration", "title": "Complete Reference", "section": "Region Missions", "snippet": "A REGION mission uses a cuboid selected by two opposite block corners in the dungeon template. The corner blocks are included, and either selection order is accepted...", "text": "A REGION mission uses a cuboid selected by two opposite block corners in the dungeon template. The corner blocks are included, and either selection order is accepted. Progress starts only after the stage unlocks. /dg edit <dungeon_id> /dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 # move to the opposite corner in the template world /dg stage <stage_id> mission region pos2 Run `/dg stage <stage_id> mission region` first to add the mission. The confirmation shows the two commands for selecting its corners. Then stand at each corner in the template world and run `pos1` or `pos2`; each command saves your current block as that corner. Running the creation command again preserves the existing corners and settings. Do not use the generated instance world name in the stage config. In editor mode, cyan particles mark `pos1` and pink particles mark `pos2`. Markers are visible only to the editing admin within 50 blocks of a corner. Toggle **Region Corners** under **Admin Settings** to show or hide them independently of other mission particles. missions: - type: REGION region: mode: ENTER_ONCE whole-party: false pos1: {x: 10, y: 60, z: 10} pos2: {x: 20, y: 70, z: 20} | `ENTER_ONCE` | Any participant enters once. | Each required participant enters once; their visits may happen at different times. | | `STAY_UNTIL_COMPLETE` | At least one participant is currently inside until all stage missions complete. | All required participants are inside at the same time until all stage missions complete. | Spectators do not count. A dead or offline participant does not count as currently inside. For the stay mode, the same player does not have to remain throughout: the configured number of participants must currently satisfy the condition. Leaving before the gate opens makes the stay condition incomplete again. Opening the gate finishes the stage permanently. With `whole-party: true`, the requirement uses the actual participants in the run, not the dungeon's maximum capacity. A solo run in a dungeon configured for 1–5 players requires only that solo player. In `STAY_UNTIL_COMPLETE`, the hologram shows the region as complete while the required participants are inside and returns to pending if they leave before the stage opens. The mission completion message and sound occur only when all stage missions are satisfied and the gate opens. In `ENTER_ONCE`, completion is announced as soon as the required visits are recorded and stays complete after players leave. Set `region.mode` and `region.whole-party` in the stage YAML or use the Region Mission submenu in the admin GUI. These settings have no command variants. Use `/dg stage <stage_id> mission region delete` to remove the mission. Validation rejects missing corners or invalid settings. One REGION mission is supported per stage, with no per-dungeon limit.", "url": "pro/complete-reference/index.html#region-missions"}, {"group": "Configuration", "title": "Complete Reference", "section": "Kill Mobs Filters", "snippet": "New `KILL_MOBS` missions include both options: missions: - type: KILL_MOBS required: 20 only-dungeon-spawner-mobs: true count-baby-variants: true `only-dungeon-spawn...", "text": "New `KILL_MOBS` missions include both options: missions: - type: KILL_MOBS required: 20 only-dungeon-spawner-mobs: true count-baby-variants: true `only-dungeon-spawner-mobs` counts only mobs spawned by this dungeon instance's configured spawners, including vanilla and MythicMobs pools. Friendly summons from enchantments or other plugins, natural mobs, and mobs already stored in the template do not count. Bosses remain excluded from stage kill missions. Dungeon-spawned mobs still count after transformations, such as a zombie becoming a drowned. Set `only-dungeon-spawner-mobs: false` to count mobs from other sources inside the instance. Kills must be credited to a player. Mobs summoned separately by a Mythic skill are not automatically treated as dungeon spawner mobs. `count-baby-variants` includes baby versions of eligible mobs, including zombies, drowned, piglins, and other ageable mobs. Set it to `false` to exclude babies. The spawner-source filter still applies. To control which variants spawn, use the spawner settings. Both options default to `true` when omitted, including in existing missions. Changing the required amount through a command or the editor preserves these filters. Save the mission to write the fields, or add them manually and reload. Both switches are available in the dedicated **Kill Mobs Mission** settings menu.", "url": "pro/complete-reference/index.html#kill-mobs-filters"}, {"group": "Configuration", "title": "Complete Reference", "section": "Specific Kill Mobs Targets", "snippet": "Open **Stages &gt; stage &gt; Missions &gt; Kill Mobs Mission** to reach the mission settings. The menu contains the required amount, **Dungeon Spawner Mobs Only**, and **Cou...", "text": "Open **Stages > stage > Missions > Kill Mobs Mission** to reach the mission settings. The menu contains the required amount, **Dungeon Spawner Mobs Only**, and **Count Baby Variants**. Click **Required Amount** to enter the mob count in chat. Click **Specific Mob Targets** to add a one-Zombie example when the mission has no targets and show the configuration path in chat: `plugins/InstancedDungeons/dungeons/<dungeon-id>/stages/<stage-id>.yml`. Edit `mob-targets` inside that file's `KILL_MOBS` entry, then reload the dungeon configuration before starting a new instance: missions: - type: KILL_MOBS required: 10 only-dungeon-spawner-mobs: true count-baby-variants: true mob-targets: - type: VANILLA mob-id: ZOMBIE count: 6 - type: VANILLA mob-id: PIG count: 2 - type: MYTHIC mob-id: Kings count: 1 - type: MYTHIC mob-id: Barbarian count: 1 With targets configured, the mission requires every listed count. Their sum replaces `required`; extra zombies cannot replace a missing pig or MythicMob. Use Bukkit entity names for vanilla targets and exact, case-sensitive MythicMobs internal IDs for Mythic targets. A Mythic zombie counts toward its Mythic ID, not the vanilla `ZOMBIE` target. Both source and baby filters still apply. The hologram shows each target's progress and remaining count. Invalid target definitions block progress and are reported by validation and in the server log. Omit `mob-targets` to use the ordinary total-count mission. The amount button is disabled while specific targets control the total; editing the filters preserves those targets.", "url": "pro/complete-reference/index.html#specific-kill-mobs-targets"}, {"group": "Configuration", "title": "Complete Reference", "section": "Skipping Missions", "snippet": "/dg skip &lt;stage_id&gt; mission all /dg skip &lt;stage_id&gt; mission &lt;mission_type&gt; Requires `instanceddungeons.admin` or `instanceddungeons.skip.mission`. The player must be...", "text": "/dg skip <stage_id> mission all /dg skip <stage_id> mission <mission_type> Requires `instanceddungeons.admin` or `instanceddungeons.skip.mission`. The player must be a participant in an active dungeon run, not a spectator. There is no skip button in the GUI. Stage tab completion lists only unlocked, unfinished stages in the player's current instance, including parallel stages with the same order. Mission tab completion lists that stage's mission types and `all`. Skipping marks the selected missions complete without charging payment costs or performing sacrifice. Skipping `KILL_MOBS` also fills every configured mob target on the hologram, such as `SKELETON: 2/2` and `ZOMBIE: 2/2`, with zero remaining. When every mission is satisfied, normal gate opening, stage events and checkpoint behavior continue. A skipped REGION stay condition cannot block the stage again. `all` affects only the named stage; it never skips a newly unlocked stage.", "url": "pro/complete-reference/index.html#skipping-missions"}, {"group": "Configuration", "title": "Complete Reference", "section": "Event Commands", "snippet": "Event commands let server owners run commands when dungeon events happen. They are per dungeon and disabled by default. Admins configure them in each dungeon&#x27;s comma...", "text": "Event commands let server owners run commands when dungeon events happen. They are per dungeon and disabled by default. Admins configure them in each dungeon's command file: plugins/InstancedDungeons/dungeons/<dungeon_id>/commands.yml Default file: enabled: false default-executor: CONSOLE commands: # - event: on-player-death-command # executor: CONSOLE # audience: NONE # run: # - \"say <player> died in <dungeon_name>\" # # - event: on-player-death-command # executor: CONSOLE # audience: PARTY # run: # - \"tell <target> <player> died in <dungeon_name>\" # # - event: on-player-death-command # executor: CONSOLE # audience: ALIVE_PARTY # run: # - \"msg <target> <player> has died.\" # # - event: on-party-complete-dungeon-command # executor: CONSOLE # audience: NONE # run: # - \"broadcast <party_leader>'s party completed <dungeon_name>\" Set `enabled: true` and uncomment the entries you want to run. Executor: `CONSOLE`: runs command as console. `PLAYER`: runs command as the event player. Party events use the online party leader when available. Audience: `NONE`: no plugin targeting. The command runs once. Example: `executor: CONSOLE`, `audience: NONE`, and `say ...` broadcasts globally because Minecraft's `say` command is global. `PLAYER`: targets the event player and fills `<target>` with that player. `PARTY`: runs once per online dungeon party member and fills `<target>` for each member. External spectators are not included. `ALIVE_PARTY`: runs once per online non-eliminated dungeon player. `DEAD_PARTY`: runs once per online eliminated death spectator. `LEADER`: targets the party leader. Command format: Leading `/` is optional. Commands are skipped when the event is not configured. Run `/dungeon reload` after editing event commands. The `commands:` list may contain the same `event` more than once. This is the recommended way to run separate command groups or run the same trigger with different executor/audience combinations. Each entry can use its own `executor`; otherwise it uses `default-executor`. If `audience` is omitted, it defaults to `NONE`. If an audience other than `NONE` has no online targets, that command entry is skipped. Audience does not change how Minecraft commands behave. `say` is still global. Use commands such as `msg <target> ...` or `tell <target> ...` when you want only the selected audience to see a message. Player event keys: | `on-player-create-party-command` | Once for the player who creates a party with `/dungeon open <id>`. | | `on-player-join-party-command` | Once for the player who joins a party with `/dungeon join <code>`. | | `on-player-start-dungeon-command` | For each dungeon player when the instance starts and players enter the dungeon. | | `on-player-complete-dungeon-command` | For each active dungeon player when a single dungeon completes, or when the last tower dungeon completes. | | `on-player-abandon-dungeon-command` | For a player who leaves through an external/abandon flow before completion. | | `on-player-exit-dungeon-command` | When a player exits with `/dungeon exit`. | | `on-player-death-command` | When a dungeon player dies inside an active instance. | | `on-player-kill-mob-command` | When a dungeon player kills a regular dungeon mob. | | `on-player-kill-boss-command` | When a dungeon player kills the boss and Bukkit can resolve the killer. | | `on-player-complete-stage-command` | For each active dungeon player when the active stage is completed. | | `on-player-open-gate-command` | For each active dungeon player when a stage gate opens. | | `on-player-fail-dungeon-command` | For each active dungeon player when the dungeon or tower fails. | Party event keys: | `on-party-create-command` | Once when a party is created. | | `on-party-player-join-command` | Once when any player joins the party. Use this for party-wide scripts. | | `on-party-start-dungeon-command` | Once when the party enters the dungeon instance. | | `on-party-complete-dungeon-command` | Once when a single dungeon completes. In towers, this runs on the final dungeon only. | | `on-party-abandon-dungeon-command` | Reserved for full-party abandon flows before completion. | | `on-party-fail-dungeon-command` | Once when the dungeon or whole tower fails. | | `on-party-complete-stage-command` | Once when a stage is completed. | | `on-party-open-gate-command` | Once when a stage gate opens. | | `on-party-enter-tower-stage-command` | Once when the party enters the next tower dungeon after a transition. | | `on-party-complete-tower-command` | Once when the final tower dungeon completes. | Event placeholder reference: | `<player>` | Event player name. | | `<player_uuid>` | Event player UUID. | | `<executor>` | Configured command executor, `CONSOLE` or `PLAYER`. | | `<executor_player>` | Player executing the command when using `PLAYER`. | | `<executor_uuid>` | Executor player UUID when using `PLAYER`. | | `<audience>` | Configured audience. | | `<target>` | Current audience target player name. Empty when `audience: NONE`. | | `<target_uuid>` | Current audience target player UUID. Empty when `audience: NONE`. | | `<party_leader>` | Party leader name. | | `<party_code>` | Party code. | | `<party_size>` | Number of players in the party or active instance. | | `<dungeon_id>` | Dungeon folder ID. | | `<dungeon_name>` | Dungeon display name. | | `<template_id>` | Template world name. | | `<stage_id>` | Stage ID when the event is stage-related. | | `<stage_order>` | Stage order when available. | | `<tower_id>` | Tower context ID. | | `<mob_id>` | Killed mob type or ID when available. | | `<boss_id>` | Boss ID placeholder when available. | | `<world>` | Event player's current world. | | `<instance_world>` | Active instance world name when available. | | `<x>`, `<y>`, `<z>` | Event player's block coordinates. | Duplicate rules: Player events run once per affected player. Party events run once per party/run. `/dungeon exit` fires the exit event, not the abandon event. External teleports/leaves can fire abandon events. Stage gate open and stage complete are separate hooks so admins can script either moment.", "url": "pro/complete-reference/index.html#event-commands"}, {"group": "Configuration", "title": "Complete Reference", "section": "Messages and Placeholders", "snippet": "Main messages file: plugins/InstancedDungeons/messages.yml Important placeholder styles: Messages use `%placeholder%`. Event commands use `&lt;placeholder&gt;`. The `missi...", "text": "Main messages file: plugins/InstancedDungeons/messages.yml Important placeholder styles: Messages use `%placeholder%`. Event commands use `<placeholder>`. The `mission-names` section controls player-facing mission labels used in mission completion messages, mission GUI names, hologram mission hints, and mission lore placeholders. Keep using mission IDs such as `KILL_MOBS` in configs and commands. New installations receive messages grouped by purpose, such as dungeon, instance and editor messages. Updates append missing new messages to existing files under: # Messages added by plugin updates will appear below. Existing messages are never overwritten. Existing messages, comments, order, and translations are preserved. Admin menu titles, button labels, icon descriptions and the Region/Cooldown settings input prompts use fixed English text. `messages.yml` controls chat messages and player-facing mission labels, including the existing `mission-names` section. `item-use-blocked-in-dungeon` uses `%item%` for the blocked item name. `messages.yml` also includes a placeholder reference comment at the bottom.", "url": "pro/complete-reference/index.html#messages-and-placeholders"}, {"group": "Configuration", "title": "Complete Reference", "section": "Validation", "snippet": "Use: /dungeon validate &lt;id&gt; /dungeon validate all /dungeon reload Validation checks include: Config version compatibility. Missing spawn/exit locations. Invalid obje...", "text": "Use: /dungeon validate <id> /dungeon validate all /dungeon reload Validation checks include: Config version compatibility. Missing spawn/exit locations. Invalid objective files. Invalid tower chain setup. Unsupported costs on middle/last tower stages. Invalid spawner locations. Unknown mob IDs where they can be resolved. Unknown or unavailable custom item provider entries. Stage ordering and feature validation warnings. Loot chest and boss reward item definitions. `commands.yml` syntax, event keys, executors, audiences, command lists, and risky audience/global command combinations. Validation output: Console always receives validation output. Online admins receive chat validation warnings unless disabled per dungeon. Normal players do not receive validation warnings. If chat output is shortened, check the console because it may contain more validation details.", "url": "pro/complete-reference/index.html#validation"}, {"group": "Configuration", "title": "Complete Reference", "section": "Feature Limits", "snippet": "| Global active instances | `0` disables the global active-instance ceiling. Positive values set the exact maximum. | | Tower length | Supports `FIRST -&gt; LAST` and l...", "text": "| Global active instances | `0` disables the global active-instance ceiling. Positive values set the exact maximum. | | Tower length | Supports `FIRST -> LAST` and longer `FIRST -> MIDDLE -> ... -> LAST` chains. | | Tower middle stage | Fully supported. | | Stages per dungeon | Uses all configured stages. | | Missions per stage | Uses all configured missions. | | Lever mission blocks | Uses all configured blocks. | | Button mission blocks | Uses all configured blocks. | | Pressure plate mission blocks | Uses all configured blocks. | | Required keys | Uses the configured `required` amount. | | Sacrifice missions | Multiple sacrifice mission entries are supported. | | Money payment missions | Multiple money payment mission entries are supported. | | Item payment missions | Multiple item payment mission entries are supported. | | Item payment item types | Multiple item payment item types are supported. | | Region missions | One per stage, with no per-dungeon limit. |", "url": "pro/complete-reference/index.html#feature-limits"}, {"group": "Configuration", "title": "Complete Reference", "section": "Admin GUI and RAM Analysis", "snippet": "The admin GUI provides dungeon settings, gate and mission editing, checkpoints, reward previews and test rolls, and sound previews. **Boss &amp; Trigger** shows the cont...", "text": "The admin GUI provides dungeon settings, gate and mission editing, checkpoints, reward previews and test rolls, and sound previews. **Boss & Trigger** shows the controls for the selected objective. **After-Open Logic** and **Emergency Return** configure gate teleports and return plates. See [Event Commands](event-commands.md) for checkpoint and gate actions. `/dungeon ram analysis` toggles memory reports and requires `instanceddungeons.admin`. Reports estimate plugin and active-instance memory. See [RAM Analysis](ram-analysis.md) for settings and report fields.", "url": "pro/complete-reference/index.html#admin-gui-and-ram-analysis"}, {"group": "Configuration", "title": "Complete Reference", "section": "Compatibility Notes", "snippet": "One universal JAR supports both Paper 1.21.x and Paper 26.1 / 26.2 / 26.3. Template world gamerules, WorldBorder settings, and WorldGuard regions/flags copy automati...", "text": "One universal JAR supports both Paper 1.21.x and Paper 26.1 / 26.2 / 26.3. Template world gamerules, WorldBorder settings, and WorldGuard regions/flags copy automatically to each dungeon instance. No update checker is included in this build. Recreate dungeons that use the 1.x config format before using them with 2.x.", "url": "pro/complete-reference/index.html#compatibility-notes"}, {"group": "Configuration", "title": "Complete Reference", "section": "Troubleshooting", "snippet": "Mobs do not spawn: Run `/dungeon validate &lt;id&gt;`. Check spawner location and trigger. Verify MythicMobs IDs if using `MYTHIC`. Ensure the template world is loaded. Lo...", "text": "Mobs do not spawn: Run `/dungeon validate <id>`. Check spawner location and trigger. Verify MythicMobs IDs if using `MYTHIC`. Ensure the template world is loaded. Loot chests are empty: Check `min-items-per-drop` and `max-items-per-drop`. Verify item provider and item IDs. Check chance values. Run `/dungeon reload` after edits. Dungeon will not start: Run `/dungeon validate <id>`. Check `v: 2.0`. Check spawn and exit locations. Check max instance limits. Check party size and offline members. Tower does not transition: Confirm `dungeon-type: tower`. Confirm `tower-stage-type`. Confirm `next-dungeon` points to a loaded dungeon. `FIRST` can point to `MIDDLE`, and `MIDDLE` can point to another `MIDDLE` or `LAST`. Stage gate does not open: Confirm stage order is valid. Confirm all missions are complete. Confirm the hologram belongs to the same stage. Check that the gate was saved with `/dungeon gate save`. Custom items fail validation: Confirm the provider plugin is installed and enabled. Confirm the item ID exactly matches the provider ID. For potions and enchanted books, confirm the ID follows the special vanilla formats above.", "url": "pro/complete-reference/index.html#troubleshooting"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Spawners and Mobs", "snippet": "Configure mob spawning, equipment, and drops for each dungeon. Spawner files live in: dungeons/&lt;id&gt;/spawners/&lt;spawner_id&gt;.yml Boss spawners use the same mob pool for...", "text": "Configure mob spawning, equipment, and drops for each dungeon. Spawner files live in: dungeons/<id>/spawners/<spawner_id>.yml Boss spawners use the same mob pool format inside `boss.yml`.", "url": "pro/spawners-and-mobs/index.html"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Basic Spawner", "snippet": "location: world: dragon_template x: 100.5 y: 64.0 z: 200.5 trigger: ON_PLAYER_NEAR trigger-distance: 20 trigger-time: 5 lifetime-behavior: PERSIST lifetime-seconds: ...", "text": "location: world: dragon_template x: 100.5 y: 64.0 z: 200.5 trigger: ON_PLAYER_NEAR trigger-distance: 20 trigger-time: 5 lifetime-behavior: PERSIST lifetime-seconds: 0 mob-pools: - type: VANILLA mob-id: ZOMBIE count: 5 chance: 100.0 drop-vanilla-loot: false - type: MYTHIC mob-id: SkeletonKing count: 1 chance: 35.0", "url": "pro/spawners-and-mobs/index.html#basic-spawner"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Trigger Modes", "snippet": "| `ON_START` | Spawns when the instance starts. Not recommended for regular spawners because it can spawn every configured mob immediately at dungeon startup. | | `O...", "text": "| `ON_START` | Spawns when the instance starts. Not recommended for regular spawners because it can spawn every configured mob immediately at dungeon startup. | | `ON_PLAYER_NEAR` | Spawns when a player enters `trigger-distance`. | | `ON_DELAY` | Spawns after `trigger-time`. | | `ON_PLAYER_NEAR_ON_DELAY` | Starts `trigger-time` after a player enters `trigger-distance`. | Spawners default to `ON_PLAYER_NEAR` with `trigger-distance: 20`. The selected trigger determines whether `trigger-distance`, `trigger-time`, or both apply.", "url": "pro/spawners-and-mobs/index.html#trigger-modes"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Mob Lifetime", "snippet": "lifetime-behavior: PERSIST lifetime-seconds: 0 `PERSIST` and `PERSIST_UNTIL_DUNGEON_END` prevent natural distance despawning during the instance. This also applies t...", "text": "lifetime-behavior: PERSIST lifetime-seconds: 0 `PERSIST` and `PERSIST_UNTIL_DUNGEON_END` prevent natural distance despawning during the instance. This also applies to `ON_START` mobs spawned far from players. Entities are saved across chunk unloading and reloading. Both modes still remove mobs when the instance is cleaned up or its world is deleted; neither keeps an instance running after it ends. `DESPAWN_AFTER_TIME` removes the mob after a positive `lifetime-seconds` duration. Its deadline is retained through chunk unloading and mob transformations. Keep `lifetime-seconds` positive when using this mode. These settings cover Vanilla and MythicMobs spawned by the dungeon. Another plugin that explicitly removes an entity can still remove it.", "url": "pro/spawners-and-mobs/index.html#mob-lifetime"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Mob Pools", "snippet": "Spawner pools can mix vanilla and MythicMobs entries: mob-pools: - type: VANILLA mob-id: SKELETON count: 3 chance: 100.0 - type: MYTHIC mob-id: DungeonKnight count: ...", "text": "Spawner pools can mix vanilla and MythicMobs entries: mob-pools: - type: VANILLA mob-id: SKELETON count: 3 chance: 100.0 - type: MYTHIC mob-id: DungeonKnight count: 1 chance: 25.0 | `type` | `VANILLA` or `MYTHIC`. | | `mob-id` | Bukkit entity type for vanilla mobs, MythicMobs mob ID for Mythic mobs. | | `count` | How many mobs this pool spawns when selected. | | `chance` | Percent chance from `0.0` to `100.0`. | | `drop-vanilla-loot` | Optional. `false` removes normal mob loot such as bones, arrows, rotten flesh, or totems. Generated spawners include this as `false`. | | `prevent-zombification` | Optional. `true` prevents spawned mobs such as piglins and hoglins from zombifying in normal worlds. Add this manually only when needed. | | `prevent-baby-spawns` | Optional. `true` forces spawned ageable mobs into their adult form, preventing baby variants such as baby piglins or baby zombies from spawning from that pool. |", "url": "pro/spawners-and-mobs/index.html#mob-pools"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Vanilla Mob Drops", "snippet": "Generated spawners include: drop-vanilla-loot: false When this is `false`, vanilla mob loot is removed from mobs spawned by that pool. For example: skeletons do not ...", "text": "Generated spawners include: drop-vanilla-loot: false When this is `false`, vanilla mob loot is removed from mobs spawned by that pool. For example: skeletons do not drop bones or arrows, zombies do not drop rotten flesh, evokers do not drop totems or emeralds. This does not block configured equipment drop chances. If the pool has an `equipment` section, the configured armor, weapons, and tools still use their own `drop-chance` values. Set it to `true` if you want vanilla mob loot to remain enabled for that pool.", "url": "pro/spawners-and-mobs/index.html#vanilla-mob-drops"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Prevent Zombification", "snippet": "Some mobs transform outside their native dimension, such as piglins or hoglins becoming zombified in the overworld. To keep a spawned mob in its original form, add t...", "text": "Some mobs transform outside their native dimension, such as piglins or hoglins becoming zombified in the overworld. To keep a spawned mob in its original form, add this manually to the related mob pool: mob-pools: - type: VANILLA mob-id: PIGLIN count: 1 chance: 100.0 drop-vanilla-loot: false prevent-zombification: true Use this only for mobs that need it. It is supported in normal spawner files and in `boss.yml` mob pools.", "url": "pro/spawners-and-mobs/index.html#prevent-zombification"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Prevent Baby Spawns", "snippet": "To stop a pool from producing baby variants, add: prevent-baby-spawns: true Example: mob-pools: - type: VANILLA mob-id: PIGLIN count: 3 chance: 100.0 drop-vanilla-lo...", "text": "To stop a pool from producing baby variants, add: prevent-baby-spawns: true Example: mob-pools: - type: VANILLA mob-id: PIGLIN count: 3 chance: 100.0 drop-vanilla-loot: false prevent-zombification: true prevent-baby-spawns: true This forces supported spawned mobs into adult form. It is useful for piglins, zombies, zombified piglins, hoglins, and other ageable mobs where baby variants should not appear in dungeon combat.", "url": "pro/spawners-and-mobs/index.html#prevent-baby-spawns"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Vanilla Mob Equipment", "snippet": "Dungeon spawners can equip supported vanilla mobs with armor, hand items, enchantments, and per-slot drop chance. mob-pools: - type: VANILLA mob-id: SKELETON count: ...", "text": "Dungeon spawners can equip supported vanilla mobs with armor, hand items, enchantments, and per-slot drop chance. mob-pools: - type: VANILLA mob-id: SKELETON count: 1 chance: 100.0 equipment: helmet: item: IRON_HELMET drop-chance: 10.0 chestplate: item: IRON_CHESTPLATE drop-chance: 10.0 leggings: item: IRON_LEGGINGS drop-chance: 10.0 boots: item: IRON_BOOTS drop-chance: 10.0 main-hand: item: IRON_SWORD drop-chance: 5.0 enchants: SHARPNESS: 1 off-hand: item: SHIELD drop-chance: 0.0 If a vanilla mob normally spawns with a weapon, the configured `main-hand` item replaces it. For example, a skeleton configured with `IRON_SWORD` spawns with the sword instead of its default bow.", "url": "pro/spawners-and-mobs/index.html#vanilla-mob-equipment"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Equipment Slots", "snippet": "| `helmet` | `head` | | `chestplate` | `chest` | | `leggings` | `legs` | | `boots` | `feet` | | `main-hand` | `main_hand`, `mainhand`, `hand` | | `off-hand` | `off_h...", "text": "| `helmet` | `head` | | `chestplate` | `chest` | | `leggings` | `legs` | | `boots` | `feet` | | `main-hand` | `main_hand`, `mainhand`, `hand` | | `off-hand` | `off_hand`, `offhand` | `drop-chance` is a percentage from `0.0` to `100.0`.", "url": "pro/spawners-and-mobs/index.html#equipment-slots"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Supported Equipment Mobs", "snippet": "Equipment is applied only to vanilla mobs that can normally wear or hold equipment: `ZOMBIE` `ZOMBIE_VILLAGER` `HUSK` `DROWNED` `SKELETON` `STRAY` `WITHER_SKELETON` ...", "text": "Equipment is applied only to vanilla mobs that can normally wear or hold equipment: `ZOMBIE` `ZOMBIE_VILLAGER` `HUSK` `DROWNED` `SKELETON` `STRAY` `WITHER_SKELETON` `BOGGED` `PIGLIN` `PIGLIN_BRUTE` `ZOMBIFIED_PIGLIN` `VINDICATOR` `PILLAGER` `EVOKER` `ILLUSIONER` `WITCH` does not support configured equipment. Unsupported mobs, such as `GHAST` or `BLAZE`, still spawn normally. Their configured equipment is ignored, and validation warns admins that the mob cannot wear armor or hold equipment.", "url": "pro/spawners-and-mobs/index.html#supported-equipment-mobs"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Enchanted Equipment", "snippet": "Equipment uses the same vanilla enchantment format as rewards and costs: main-hand: item: DIAMOND_AXE drop-chance: 2.5 enchants: SHARPNESS: 5 UNBREAKING: 3 This work...", "text": "Equipment uses the same vanilla enchantment format as rewards and costs: main-hand: item: DIAMOND_AXE drop-chance: 2.5 enchants: SHARPNESS: 5 UNBREAKING: 3 This works for armor, tools, weapons, shields, and enchanted books.", "url": "pro/spawners-and-mobs/index.html#enchanted-equipment"}, {"group": "Systems", "title": "Spawners and Mobs", "section": "Boss Stage Requirement", "snippet": "New `boss.yml` files include: stage-requirement: mode: DISABLED stage-id: &#x27;&#x27; | `DISABLED` | Uses the normal boss trigger without a stage requirement. This is also th...", "text": "New `boss.yml` files include: stage-requirement: mode: DISABLED stage-id: '' | `DISABLED` | Uses the normal boss trigger without a stage requirement. This is also the default for existing files. | | `STAGE` | Requires the stage named by `stage-id` to be completed. | | `ALL` | Requires every stage in the current dungeon to be completed. With no stages configured, there is nothing to wait for. | A stage is completed when all its missions are finished and its gate opens. Unlocking a stage does not complete it. Closing its gate later does not reset its completion. For example, require the `courtyard` stage before allowing the proximity trigger: trigger: ON_PLAYER_NEAR trigger-distance: 20 trigger-time: 0 stage-requirement: mode: STAGE stage-id: courtyard The stage requirement is an additional condition for every boss trigger: `ON_START`: waits until the stage requirement is met. `ON_DELAY`: starts its `trigger-time` delay after the requirement is met. `ON_PLAYER_NEAR`: requires an alive party member within range and the stage requirement to be met. `ON_PLAYER_NEAR_ON_DELAY`: starts its delay only once both conditions are met. If a player is already in range, the boss can activate as soon as the stage requirement is met. Spectators cannot trigger the boss. An invalid mode or missing stage ID in `STAGE` mode blocks spawning; `/dg validate <id>` reports the configuration error. In the admin GUI, open **Boss & Trigger**. **Boss Stage Requirement** cycles the mode; **Required Stage ID** accepts an existing stage only while `STAGE` mode is selected; it is inactive in `DISABLED` and `ALL`. Both settings are saved to `boss.yml`. Moving the boss spawn preserves them. **Test Boss Spawn** previews the boss without applying stage requirements.", "url": "pro/spawners-and-mobs/index.html#boss-stage-requirement"}, {"group": "Systems", "title": "Stages and Gates", "section": "Stages and Gates", "snippet": "Stages are optional progression gates inside a dungeon. Use the stage GUI to edit gates and missions. **After-Open Logic** configures party teleports and gate closin...", "text": "Stages are optional progression gates inside a dungeon. Use the stage GUI to edit gates and missions. **After-Open Logic** configures party teleports and gate closing; **Emergency Return** configures the return plate and destination. Runtime gate blocks, mission blocks, triggers, loot chests, and emergency plates are protected from player breaking, replacement, water, and lava even when the dungeon otherwise allows those actions. Ordered respawn points are documented separately under [Checkpoints](checkpoints.md). Stage files live in: dungeons/<id>/stages/<stage_id>.yml dungeons/<id>/stages/<stage_id>-hologram.yml", "url": "pro/stages/index.html"}, {"group": "Systems", "title": "Stages and Gates", "section": "Create a Stage", "snippet": "/dungeon edit dragon_lair /dungeon stage create entrance /dungeon stage entrance gate create # select gate blocks in the template world /dungeon gate save", "text": "/dungeon edit dragon_lair /dungeon stage create entrance /dungeon stage entrance gate create # select gate blocks in the template world /dungeon gate save", "url": "pro/stages/index.html#create-a-stage"}, {"group": "Systems", "title": "Stages and Gates", "section": "Stage Order", "snippet": "Every stage has an order: stage-id: entrance stage-order: 1 Order `1` unlocks first. Higher orders unlock only after every lower-order stage opens. Multiple stages c...", "text": "Every stage has an order: stage-id: entrance stage-order: 1 Order `1` unlocks first. Higher orders unlock only after every lower-order stage opens. Multiple stages can share the same order. Shared-order stages run in parallel. /dungeon stage list /dungeon stage entrance order 2", "url": "pro/stages/index.html#stage-order"}, {"group": "Systems", "title": "Stages and Gates", "section": "Gate Editing", "snippet": "Use gate mode to select existing blocks from the template world. /dungeon stage entrance gate create /dungeon stage entrance gate stick /dungeon gate save Gate stick...", "text": "Use gate mode to select existing blocks from the template world. /dungeon stage entrance gate create /dungeon stage entrance gate stick /dungeon gate save Gate stick controls: | Left-click | Adds one existing block. | | Right-click | Removes one selected block. | | Sneak-left-click | Adds connected same-material blocks. | | Sneak-right-click | Removes connected same-material blocks. |", "url": "pro/stages/index.html#gate-editing"}, {"group": "Systems", "title": "Stages and Gates", "section": "After-Open Logic", "snippet": "A gate can teleport the alive party after it finishes opening and can close earlier gates without a closing animation: gate: after-open: teleport: enabled: false loc...", "text": "A gate can teleport the alive party after it finishes opening and can close earlier gates without a closing animation: gate: after-open: teleport: enabled: false location: world: dungeon_template x: 20.5 y: 70.0 z: 12.5 yaw: 0.0 pitch: 0.0 close-gates: - entrance_gate Only online, alive party members inside the instance world are teleported. A gate cannot close itself, and every target in `close-gates` must have an equal or lower `stage-order`. Configuring both an after-open teleport and a teleporting checkpoint triggered by the same gate is a validation error. /dungeon stage <stage_id> gate afteropen teleport set|clear /dungeon stage <stage_id> gate afteropen close add|remove <target_stage_id>", "url": "pro/stages/index.html#after-open-logic"}, {"group": "Systems", "title": "Stages and Gates", "section": "Emergency Return", "snippet": "Emergency Return provides a way out for a player who remains behind a gate after it closes. Its pressure plate and hologram appear only while that gate is closed, an...", "text": "Emergency Return provides a way out for a player who remains behind a gate after it closes. Its pressure plate and hologram appear only while that gate is closed, and the plate teleports only the player who steps on it. Enable the feature, choose the pressure-plate material, and use **Get Emergency Plate** in the GUI. The tagged item is placed in the template like a mission plate. One gate can have only one emergency plate; placing another removes the previous plate and moves the editor hologram. The item cannot be placed while Emergency Return is disabled. gate: emergency-return: enabled: true plate-material: STONE_PRESSURE_PLATE plate-location: x: 10 y: 69 z: 5 destination: world: dungeon_template x: 22.5 y: 70.0 z: 12.5 yaw: 0.0 pitch: 0.0 hologram: enabled: true height-offset: 1.8 lines: - \"&c&lRETURN\" - \"&7Step on the plate to leave the closed section.\" /dungeon stage <stage_id> gate emergency enable|disable /dungeon stage <stage_id> gate emergency plate set [pressure_plate_material] /dungeon stage <stage_id> gate emergency destination set Emergency-return hologram visibility, height, and lines are configured only under `gate.emergency-return.hologram` in the stage YAML. They cannot be edited in the GUI or through an in-game command. The editor has independent particle toggles for gate teleport destinations and emergency-return locations.", "url": "pro/stages/index.html#emergency-return"}, {"group": "Systems", "title": "Stages and Gates", "section": "Holograms", "snippet": "/dungeon stage entrance gate hologram create /dungeon stage entrance gate hologram delete You can create multiple holograms for the same stage. Delete removes the ne...", "text": "/dungeon stage entrance gate hologram create /dungeon stage entrance gate hologram delete You can create multiple holograms for the same stage. Delete removes the nearest hologram for that stage within 3 blocks. Runtime holograms show live mission progress. Locked higher-order holograms show which earlier stages still need to open. Emergency-return holograms support `%dungeon%`, `%dungeon_name%`, `%instance%`, `%party_leader%`, `%party_size%`, `%alive_players%`, `%gate%`, `%stage%`, `%stage_order%`, `%destination_x%`, `%destination_y%`, and `%destination_z%`.", "url": "pro/stages/index.html#holograms"}, {"group": "Systems", "title": "Stages and Gates", "section": "Mission Types", "snippet": "| `REGION` | Enter or remain in a selected cuboid, individually or as a party. | | `KILL_MOBS` | Party must kill a configured number of mobs. | | `LEVER` | Party mus...", "text": "| `REGION` | Enter or remain in a selected cuboid, individually or as a party. | | `KILL_MOBS` | Party must kill a configured number of mobs. | | `LEVER` | Party must pull all mission levers. | | `BUTTON` | Party must press all mission buttons at the same time. | | `PRESSURE_PLATE` | Party must activate all mission plates at the same time. | | `REQUIRED_KEY` | Players submit mission keys by right-clicking the gate. | | `TIME` | Waits a configured number of seconds. | | `SACRIFICE` | Selects players to eliminate through the mission GUI. | | `MONEY_PAYMENT` | Requires a Vault money payment. | | `ITEM_PAYMENT` | Requires configured items through a GUI editor. | Mission levers belonging to locked future stages cannot be pulled. They become available when their stage unlocks.", "url": "pro/stages/index.html#mission-types"}, {"group": "Systems", "title": "Stages and Gates", "section": "Region Missions", "snippet": "A REGION mission uses a cuboid selected by two opposite block corners in the dungeon template. The corner blocks are included, and either selection order is accepted...", "text": "A REGION mission uses a cuboid selected by two opposite block corners in the dungeon template. The corner blocks are included, and either selection order is accepted. Progress starts only after the stage unlocks. /dg edit <dungeon_id> /dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 # move to the opposite corner in the template world /dg stage <stage_id> mission region pos2 Run `/dg stage <stage_id> mission region` first to add the mission. The confirmation shows the two commands for selecting its corners. Then stand at each corner in the template world and run `pos1` or `pos2`; each command saves your current block as that corner. Running the creation command again preserves the existing corners and settings. Do not use the generated instance world name in the stage config. In editor mode, cyan particles mark `pos1` and pink particles mark `pos2`. Markers are visible only to the editing admin within 50 blocks of a corner. Toggle **Region Corners** under **Admin Settings** to show or hide them independently of other mission particles. missions: - type: REGION region: mode: ENTER_ONCE whole-party: false pos1: {x: 10, y: 60, z: 10} pos2: {x: 20, y: 70, z: 20} | `ENTER_ONCE` | Any participant enters once. | Each required participant enters once; their visits may happen at different times. | | `STAY_UNTIL_COMPLETE` | At least one participant is currently inside until all stage missions complete. | All required participants are inside at the same time until all stage missions complete. | Spectators do not count. A dead or offline participant does not count as currently inside. For the stay mode, the same player does not have to remain throughout: the configured number of participants must currently satisfy the condition. Leaving before the gate opens makes the stay condition incomplete again. Opening the gate finishes the stage permanently. With `whole-party: true`, the requirement uses the actual participants in the run, not the dungeon's maximum capacity. A solo run in a dungeon configured for 1–5 players requires only that solo player. In `STAY_UNTIL_COMPLETE`, the hologram shows the region as complete while the required participants are inside and returns to pending if they leave before the stage opens. The mission completion message and sound occur only when all stage missions are satisfied and the gate opens. In `ENTER_ONCE`, completion is announced as soon as the required visits are recorded and stays complete after players leave. Set `region.mode` and `region.whole-party` in the stage YAML or use the Region Mission submenu in the admin GUI. These settings have no command variants. Use `/dg stage <stage_id> mission region delete` to remove the mission. Validation rejects missing corners or invalid settings. One REGION mission is supported per stage with no per-dungeon region mission limit. In the mission GUI, click Region Mission to create it and open its corner and logic settings. Right-click its mission icon to remove it.", "url": "pro/stages/index.html#region-missions"}, {"group": "Systems", "title": "Stages and Gates", "section": "Mission Commands", "snippet": "/dg stage &lt;stage_id&gt; mission region /dg stage &lt;stage_id&gt; mission region pos1 /dg stage &lt;stage_id&gt; mission region pos2 /dg stage &lt;stage_id&gt; mission region delete /dun...", "text": "/dg stage <stage_id> mission region /dg stage <stage_id> mission region pos1 /dg stage <stage_id> mission region pos2 /dg stage <stage_id> mission region delete /dungeon stage <stage_id> mission kill_mobs <amount> /dungeon stage <stage_id> mission lever /dungeon stage <stage_id> mission button <button_material> /dungeon stage <stage_id> mission pressure_plate <plate_material> /dungeon stage <stage_id> mission required_key <amount> /dungeon stage <stage_id> mission time <seconds> /dungeon stage <stage_id> mission sacrifice [mode] [drop_items] /dungeon stage <stage_id> mission money_payment <amount> [ANY_PLAYER|LEADER_ONLY] /dungeon stage <stage_id> mission item_payment /dungeon stage <stage_id> mission <type> delete `SACRIFICE`, `MONEY_PAYMENT`, and `ITEM_PAYMENT` are opened during a run by right-clicking a gate block.", "url": "pro/stages/index.html#mission-commands"}, {"group": "Systems", "title": "Stages and Gates", "section": "Skipping Missions", "snippet": "/dg skip &lt;stage_id&gt; mission all /dg skip &lt;stage_id&gt; mission &lt;mission_type&gt; Requires `instanceddungeons.admin` or `instanceddungeons.skip.mission`. The player must be...", "text": "/dg skip <stage_id> mission all /dg skip <stage_id> mission <mission_type> Requires `instanceddungeons.admin` or `instanceddungeons.skip.mission`. The player must be a participant in an active dungeon run, not a spectator. There is no skip button in the GUI. Stage tab completion lists only unlocked, unfinished stages in the player's current instance, including parallel stages with the same order. Mission tab completion lists that stage's mission types and `all`. Skipping marks the selected missions complete without charging payment costs or performing sacrifice. Skipping `KILL_MOBS` also fills every configured mob target on the hologram, such as `SKELETON: 2/2` and `ZOMBIE: 2/2`, with zero remaining. When every mission is satisfied, normal gate opening, stage events and checkpoint behavior continue. A skipped REGION stay condition cannot block the stage again. `all` affects only the named stage; it never skips a newly unlocked stage.", "url": "pro/stages/index.html#skipping-missions"}, {"group": "Systems", "title": "Stages and Gates", "section": "Required Keys", "snippet": "For `REQUIRED_KEY`, set the required amount directly: missions: - type: REQUIRED_KEY required: 3", "text": "For `REQUIRED_KEY`, set the required amount directly: missions: - type: REQUIRED_KEY required: 3", "url": "pro/stages/index.html#required-keys"}, {"group": "Systems", "title": "Stages and Gates", "section": "Kill Mobs Filters", "snippet": "New `KILL_MOBS` missions include both options: missions: - type: KILL_MOBS required: 20 only-dungeon-spawner-mobs: true count-baby-variants: true `only-dungeon-spawn...", "text": "New `KILL_MOBS` missions include both options: missions: - type: KILL_MOBS required: 20 only-dungeon-spawner-mobs: true count-baby-variants: true `only-dungeon-spawner-mobs` counts only mobs spawned by this dungeon instance's configured spawners, including vanilla and MythicMobs pools. Friendly summons from enchantments or other plugins, natural mobs, and mobs already stored in the template do not count. Bosses remain excluded from stage kill missions. Dungeon-spawned mobs still count after transformations, such as a zombie becoming a drowned. Set `only-dungeon-spawner-mobs: false` to count mobs from other sources inside the instance. Kills must be credited to a player. Mobs summoned separately by a Mythic skill are not automatically treated as dungeon spawner mobs. `count-baby-variants` includes baby versions of eligible mobs, including zombies, drowned, piglins, and other ageable mobs. Set it to `false` to exclude babies. The spawner-source filter still applies. To control which variants spawn, use the spawner settings. Both options default to `true` when omitted, including in existing missions. Changing the required amount through a command or the editor preserves these filters. Save the mission to write the fields, or add them manually and reload. Both switches are available in the dedicated **Kill Mobs Mission** settings menu.", "url": "pro/stages/index.html#kill-mobs-filters"}, {"group": "Systems", "title": "Stages and Gates", "section": "Specific Kill Mobs Targets", "snippet": "Open **Stages &gt; stage &gt; Missions &gt; Kill Mobs Mission** to reach the mission settings. The menu contains the required amount, **Dungeon Spawner Mobs Only**, and **Cou...", "text": "Open **Stages > stage > Missions > Kill Mobs Mission** to reach the mission settings. The menu contains the required amount, **Dungeon Spawner Mobs Only**, and **Count Baby Variants**. Click **Required Amount** to enter the mob count in chat. Click **Specific Mob Targets** to add a one-Zombie example when the mission has no targets and show the configuration path in chat: `plugins/InstancedDungeons/dungeons/<dungeon-id>/stages/<stage-id>.yml`. Edit `mob-targets` inside that file's `KILL_MOBS` entry, then reload the dungeon configuration before starting a new instance: missions: - type: KILL_MOBS required: 10 only-dungeon-spawner-mobs: true count-baby-variants: true mob-targets: - type: VANILLA mob-id: ZOMBIE count: 6 - type: VANILLA mob-id: PIG count: 2 - type: MYTHIC mob-id: Kings count: 1 - type: MYTHIC mob-id: Barbarian count: 1 With targets configured, the mission requires every listed count. Their sum replaces `required`; extra zombies cannot replace a missing pig or MythicMob. Use Bukkit entity names for vanilla targets and exact, case-sensitive MythicMobs internal IDs for Mythic targets. A Mythic zombie counts toward its Mythic ID, not the vanilla `ZOMBIE` target. Both source and baby filters still apply. The hologram shows each target's progress and remaining count. Invalid target definitions block progress and are reported by validation and in the server log. Omit `mob-targets` to use the ordinary total-count mission. The amount button is disabled while specific targets control the total; editing the filters preserves those targets.", "url": "pro/stages/index.html#specific-kill-mobs-targets"}, {"group": "Systems", "title": "Checkpoints", "section": "Checkpoints", "snippet": "Checkpoints provide ordered respawn locations inside a dungeon. A checkpoint has its own ID and order, one activation trigger, a respawn location, and optional actio...", "text": "Checkpoints provide ordered respawn locations inside a dungeon. A checkpoint has its own ID and order, one activation trigger, a respawn location, and optional actions that run after activation. Checkpoint files are stored in: dungeons/<id>/checkpoints/<checkpoint_id>.yml", "url": "pro/checkpoints/index.html"}, {"group": "Systems", "title": "Checkpoints", "section": "Example", "snippet": "checkpoint-id: hall order: 2 location: world: dungeon_template x: 15.5 y: 70.0 z: 8.5 yaw: 90.0 pitch: 0.0 trigger: type: GATE_OPEN gate-id: hall_gate after-activati...", "text": "checkpoint-id: hall order: 2 location: world: dungeon_template x: 15.5 y: 70.0 z: 8.5 yaw: 90.0 pitch: 0.0 trigger: type: GATE_OPEN gate-id: hall_gate after-activation: teleport-everyone: false close-gates: - entrance_gate hologram: enabled: false height-offset: 1.8 lines: - \"&b&lCHECKPOINT\" - \"&7%checkpoint%\"", "url": "pro/checkpoints/index.html#example"}, {"group": "Systems", "title": "Checkpoints", "section": "Activation triggers", "snippet": "Available trigger types are `GATE_OPEN`, `BUTTON`, and `PRESSURE_PLATE`. One checkpoint uses one trigger. For a block trigger, look at the button or pressure plate b...", "text": "Available trigger types are `GATE_OPEN`, `BUTTON`, and `PRESSURE_PLATE`. One checkpoint uses one trigger. For a block trigger, look at the button or pressure plate before choosing **Configure Trigger** in the GUI or running the block-trigger command. Changing the trigger type clears the previous gate or block binding. The new trigger must then be configured. Older files containing a button/pressure-plate type mismatched with their saved material are corrected when loaded. Breaking a configured checkpoint button or pressure plate while editing the template removes its saved `trigger.location`. The checkpoint remains, but dungeon validation blocks entry until another trigger block is configured.", "url": "pro/checkpoints/index.html#activation-triggers"}, {"group": "Systems", "title": "Checkpoints", "section": "Progress and respawning", "snippet": "Checkpoint progress never moves backward. Activating a checkpoint with an order equal to or lower than the current checkpoint does not replace it. Players who can re...", "text": "Checkpoint progress never moves backward. Activating a checkpoint with an order equal to or lower than the current checkpoint does not replace it. Players who can respawn return to the newest active checkpoint instead of the dungeon spawn.", "url": "pro/checkpoints/index.html#progress-and-respawning"}, {"group": "Systems", "title": "Checkpoints", "section": "After activation", "snippet": "`teleport-everyone` teleports only online, alive party members currently inside the instance world. Dead players, spectators, and players outside the instance are ex...", "text": "`teleport-everyone` teleports only online, alive party members currently inside the instance world. Dead players, spectators, and players outside the instance are excluded. The `close-gates` list closes its gates immediately without a closing animation. A target gate must have an equal or lower stage order and cannot be the gate that activated the checkpoint.", "url": "pro/checkpoints/index.html#after-activation"}, {"group": "Systems", "title": "Checkpoints", "section": "Holograms", "snippet": "Checkpoint hologram visibility, height, and lines are configured only in the checkpoint YAML. They cannot be edited from the GUI or an in-game command. Supported con...", "text": "Checkpoint hologram visibility, height, and lines are configured only in the checkpoint YAML. They cannot be edited from the GUI or an in-game command. Supported context placeholders include `%dungeon%`, `%dungeon_name%`, `%instance%`, `%party_leader%`, `%party_size%`, `%alive_players%`, `%checkpoint%`, `%checkpoint_order%`, `%gate%`, `%stage%`, `%destination_x%`, `%destination_y%`, and `%destination_z%`.", "url": "pro/checkpoints/index.html#holograms"}, {"group": "Systems", "title": "Checkpoints", "section": "Commands", "snippet": "/dungeon checkpoint create &lt;id&gt; /dungeon checkpoint list /dungeon checkpoint &lt;id&gt; setlocation /dungeon checkpoint &lt;id&gt; order &lt;number&gt; /dungeon checkpoint &lt;id&gt; trigge...", "text": "/dungeon checkpoint create <id> /dungeon checkpoint list /dungeon checkpoint <id> setlocation /dungeon checkpoint <id> order <number> /dungeon checkpoint <id> trigger gate <stage_id> /dungeon checkpoint <id> trigger block /dungeon checkpoint <id> teleport <true|false> /dungeon checkpoint <id> closegate add|remove <stage_id> /dungeon checkpoint <id> delete You can also create, edit, and delete checkpoints in the admin GUI. The editor has separate particle toggles for checkpoint respawn locations and checkpoint trigger blocks.", "url": "pro/checkpoints/index.html#commands"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Loot and Rewards", "snippet": "The plugin preserves enchantments on vanilla items used in costs and rewards. InstancedDungeons supports loot chests, mission keys, boss rewards, trigger rewards, an...", "text": "The plugin preserves enchantments on vanilla items used in costs and rewards. InstancedDungeons supports loot chests, mission keys, boss rewards, trigger rewards, and custom item providers.", "url": "pro/loot-and-rewards/index.html"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Loot Chests", "snippet": "Create a loot chest config: /dungeon edit dragon_lair /dungeon addlootchest treasure_room /dungeon lootchest give treasure_room Add the item in your main hand to the...", "text": "Create a loot chest config: /dungeon edit dragon_lair /dungeon addlootchest treasure_room /dungeon lootchest give treasure_room Add the item in your main hand to the loot table: /dungeon lootchest loot treasure_room add Loot chest files live in: dungeons/<id>/lootchests/<loot_chest_id>.yml Example: loot-table: - type: VANILLA item: DIAMOND min-amount: 1 max-amount: 4 chance: 50.0", "url": "pro/loot-and-rewards/index.html#loot-chests"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Mission Keys", "snippet": "Mission keys use the `MISSION` type and are guaranteed supply entries. loot-table: - type: MISSION item: KEY stage: 1 quantity: 1 lore: - &quot;&amp;7A key used to unlock a d...", "text": "Mission keys use the `MISSION` type and are guaranteed supply entries. loot-table: - type: MISSION item: KEY stage: 1 quantity: 1 lore: - \"&7A key used to unlock a dungeon stage.\" Mission keys are bound to the instance where they dropped and are removed when the player leaves that instance.", "url": "pro/loot-and-rewards/index.html#mission-keys"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Boss Rewards", "snippet": "Open the boss reward editor: /dungeon boss reward edit Boss and trigger delivery is controlled by `reward-logic`: reward-logic: delivery: INVENTORY recipients: EVERY...", "text": "Open the boss reward editor: /dungeon boss reward edit Boss and trigger delivery is controlled by `reward-logic`: reward-logic: delivery: INVENTORY recipients: EVERY_ALIVE `delivery` accepts `INVENTORY` or `GROUND`. | `PARTY_SHARED` | Boss or trigger | `GROUND` only | | `LEADER` | Boss or trigger | `INVENTORY` only | | `KILLER` | Boss only | `INVENTORY` only | | `ACTIVATOR` | Trigger only | `INVENTORY` only | | `EVERY_ALIVE` | Boss or trigger | `INVENTORY` or `GROUND` | Invalid combinations block the dungeon from opening and are reported by validation. `GROUND + EVERY_ALIVE` makes one independent reward roll for every eligible player and creates one public pile at the boss or trigger location. Inventory overflow drops at the recipient's location. Only online, alive party members inside the instance world count for `EVERY_ALIVE`. Supported custom items follow the same delivery rules as vanilla items. For existing dungeons, boss rewards keep `GROUND + PARTY_SHARED` and trigger rewards keep `INVENTORY + EVERY_ALIVE` unless an administrator changes them. Reward entries are independent. If you place 4 diamonds in one GUI slot and 2 diamonds in another slot, the plugin saves two separate reward entries. The admin GUI exposes the matching objective's reward-logic profile under **Boss & Trigger**. The test control uses normal left-click for a non-destructive entry preview and Shift-left-click for a real random roll. A real test follows `INVENTORY`/`GROUND` delivery at the testing administrator and supports every configured custom-item provider.", "url": "pro/loot-and-rewards/index.html#boss-rewards"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Trigger Rewards", "snippet": "Open the trigger reward editor: /dungeon trigger reward edit Trigger rewards are saved in: dungeons/&lt;id&gt;/trigger.yml They are given when the configured trigger compl...", "text": "Open the trigger reward editor: /dungeon trigger reward edit Trigger rewards are saved in: dungeons/<id>/trigger.yml They are given when the configured trigger completes the dungeon. Example: rewards: enabled: true items: - type: VANILLA item: DIAMOND amount: 2 chance: 100.0", "url": "pro/loot-and-rewards/index.html#trigger-rewards"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Supported Item Types", "snippet": "| `VANILLA` | Standard Minecraft item material or special vanilla ID. | | `MYTHIC_ITEM` | MythicMobs item ID. | | `ITEMSADDER` | ItemsAdder item ID. | | `ORAXEN` | O...", "text": "| `VANILLA` | Standard Minecraft item material or special vanilla ID. | | `MYTHIC_ITEM` | MythicMobs item ID. | | `ITEMSADDER` | ItemsAdder item ID. | | `ORAXEN` | Oraxen item ID. | | `NEXO` | Nexo item ID. | | `MISSION` | Dungeon mission key entry. |", "url": "pro/loot-and-rewards/index.html#supported-item-types"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Special Vanilla Item IDs", "snippet": "Special vanilla IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. Supported examples include potions, splash poti...", "text": "Special vanilla IDs work in loot chests, entry costs, stage item payment missions, boss rewards, and trigger rewards. Supported examples include potions, splash potions, lingering potions, tipped arrows, and enchanted books. - type: VANILLA item: POTION_LONG_POISON amount: 1", "url": "pro/loot-and-rewards/index.html#special-vanilla-item-ids"}, {"group": "Systems", "title": "Loot and Rewards", "section": "Enchanted Vanilla Items", "snippet": "Enchanted vanilla items are supported in: Loot chests. Boss rewards. Trigger rewards. Entry costs. Stage item payment missions. Mob equipment, documented separately ...", "text": "Enchanted vanilla items are supported in: Loot chests. Boss rewards. Trigger rewards. Entry costs. Stage item payment missions. Mob equipment, documented separately in [Spawners and Mobs](spawners-and-mobs.md). Example: - type: VANILLA item: DIAMOND_SWORD amount: 1 enchants: SHARPNESS: 5 UNBREAKING: 3 The same `enchants` map can be used for armor, tools, weapons, and enchanted books.", "url": "pro/loot-and-rewards/index.html#enchanted-vanilla-items"}, {"group": "Systems", "title": "Sounds", "section": "Dungeon Sounds", "snippet": "Each dungeon has its own file: dungeons/&lt;id&gt;/sounds.yml It controls the sounds players hear during a run, including timer alerts, loot chests, missions, gate actions...", "text": "Each dungeon has its own file: dungeons/<id>/sounds.yml It controls the sounds players hear during a run, including timer alerts, loot chests, missions, gate actions, checkpoints, teleports, and emergency returns.", "url": "pro/sounds/index.html"}, {"group": "Systems", "title": "Sounds", "section": "Event settings", "snippet": "checkpoint-activate: enabled: true sound: BLOCK_RESPAWN_ANCHOR_CHARGE volume: 0.9 pitch: 1.2 message-enabled: true Use `enabled: false` or `sound: NONE` to silence a...", "text": "checkpoint-activate: enabled: true sound: BLOCK_RESPAWN_ANCHOR_CHARGE volume: 0.9 pitch: 1.2 message-enabled: true Use `enabled: false` or `sound: NONE` to silence an event. Namespaced custom sounds are supported. Configure timer alerts in `sounds.yml`. The old `timer-alerts` section in `config.yml` is ignored after migration.", "url": "pro/sounds/index.html#event-settings"}, {"group": "Systems", "title": "Sounds", "section": "Testing sounds", "snippet": "The dungeon admin GUI includes a paged sound-test menu. A preview is heard only by the administrator who clicks it, even if that event is disabled during normal game...", "text": "The dungeon admin GUI includes a paged sound-test menu. A preview is heard only by the administrator who clicks it, even if that event is disabled during normal gameplay.", "url": "pro/sounds/index.html#testing-sounds"}, {"group": "Systems", "title": "Event Commands", "section": "Event Commands", "snippet": "Event commands let admins run server commands when dungeon events happen. Each dungeon can have: plugins/InstancedDungeons/dungeons/&lt;dungeon_id&gt;/commands.yml", "text": "Event commands let admins run server commands when dungeon events happen. Each dungeon can have: plugins/InstancedDungeons/dungeons/<dungeon_id>/commands.yml", "url": "pro/event-commands/index.html"}, {"group": "Systems", "title": "Event Commands", "section": "Basic Structure", "snippet": "commands: - event: on-party-complete-dungeon-command enabled: true executor: CONSOLE audience: PARTY commands: - &quot;broadcast &lt;party_leader&gt;&#x27;s party completed &lt;dungeon...", "text": "commands: - event: on-party-complete-dungeon-command enabled: true executor: CONSOLE audience: PARTY commands: - \"broadcast <party_leader>'s party completed <dungeon_name>\"", "url": "pro/event-commands/index.html#basic-structure"}, {"group": "Systems", "title": "Event Commands", "section": "Executors", "snippet": "| `CONSOLE` | Runs commands as console. | | `PLAYER` | Runs commands as player. |", "text": "| `CONSOLE` | Runs commands as console. | | `PLAYER` | Runs commands as player. |", "url": "pro/event-commands/index.html#executors"}, {"group": "Systems", "title": "Event Commands", "section": "Audiences", "snippet": "| `NONE` | Runs once with no player target. | | `PLAYER` | Runs for the event player. | | `PARTY` | Runs for each party member. | | `ALIVE_PARTY` | Runs for each ali...", "text": "| `NONE` | Runs once with no player target. | | `PLAYER` | Runs for the event player. | | `PARTY` | Runs for each party member. | | `ALIVE_PARTY` | Runs for each alive party member. | | `DEAD_PARTY` | Runs for each dead party member. | | `LEADER` | Runs for the party leader. |", "url": "pro/event-commands/index.html#audiences"}, {"group": "Systems", "title": "Event Commands", "section": "Player Events", "snippet": "| `on-player-create-party-command` | Player creates a party with `/dungeon open &lt;id&gt;`. | | `on-player-join-party-command` | Player joins a party. | | `on-player-star...", "text": "| `on-player-create-party-command` | Player creates a party with `/dungeon open <id>`. | | `on-player-join-party-command` | Player joins a party. | | `on-player-start-dungeon-command` | Player starts the dungeon. | | `on-player-complete-dungeon-command` | Single dungeon completes, or final tower dungeon completes. | | `on-player-abandon-dungeon-command` | Player abandons the dungeon. | | `on-player-exit-dungeon-command` | Player exits with `/dungeon exit`. | | `on-player-death-command` | Player dies inside a dungeon. | | `on-player-kill-mob-command` | Player kills a dungeon mob. | | `on-player-kill-boss-command` | Player kills the boss. | | `on-player-complete-stage-command` | Active stage completes. | | `on-player-open-gate-command` | Stage gate opens. | | `on-player-fail-dungeon-command` | Dungeon or tower fails. | | `on-player-checkpoint-activate-command` | A checkpoint becomes the newest active checkpoint. | | `on-player-checkpoint-teleport-command` | A checkpoint teleports the alive party. | | `on-player-gate-close-command` | A configured gate closes. | | `on-player-gate-after-open-teleport-command` | A gate's after-open action teleports the alive party. | | `on-player-emergency-return-command` | One player uses an emergency-return plate. |", "url": "pro/event-commands/index.html#player-events"}, {"group": "Systems", "title": "Event Commands", "section": "Party Events", "snippet": "| `on-party-create-command` | Party is created. | | `on-party-player-join-command` | Player joins a party. | | `on-party-start-dungeon-command` | Party starts the du...", "text": "| `on-party-create-command` | Party is created. | | `on-party-player-join-command` | Player joins a party. | | `on-party-start-dungeon-command` | Party starts the dungeon. | | `on-party-complete-dungeon-command` | Single dungeon completes. In towers, final dungeon only. | | `on-party-abandon-dungeon-command` | Party abandons the dungeon. | | `on-party-fail-dungeon-command` | Dungeon or whole tower fails. | | `on-party-complete-stage-command` | Stage completes. | | `on-party-open-gate-command` | Stage gate opens. | | `on-party-enter-tower-stage-command` | Party enters the next tower dungeon. | | `on-party-complete-tower-command` | Final tower dungeon completes. | | `on-party-checkpoint-activate-command` | A checkpoint becomes active. | | `on-party-checkpoint-teleport-command` | A checkpoint teleports the alive party. | | `on-party-gate-close-command` | A configured gate closes. | | `on-party-gate-after-open-teleport-command` | A gate's after-open action teleports the alive party. |", "url": "pro/event-commands/index.html#party-events"}, {"group": "Systems", "title": "Event Commands", "section": "Common Placeholders", "snippet": "| `&lt;player&gt;` | Event player name. | | `&lt;party_leader&gt;` | Party leader name. | | `&lt;party_code&gt;` | Party code. | | `&lt;dungeon_id&gt;` | Dungeon ID. | | `&lt;dungeon_name&gt;` | ...", "text": "| `<player>` | Event player name. | | `<party_leader>` | Party leader name. | | `<party_code>` | Party code. | | `<dungeon_id>` | Dungeon ID. | | `<dungeon_name>` | Display name. | | `<stage_id>` | Stage ID for stage events. | | `<stage_order>` | Stage order where available. | | `<tower_id>` | Tower context ID. | | `<reason>` | Failure reason where available. | | `<instance_id>` | Active instance ID. | | `<instance_world>` | Active instance world. | | `<alive_players>` | Current alive-player count. | | `<checkpoint_id>` | Checkpoint ID for checkpoint events. | | `<checkpoint_order>` | Checkpoint order for checkpoint events. | | `<gate_id>` | Source/current gate ID. | | `<closed_gate_id>` | Gate that was closed. | | `<destination_x>`, `<destination_y>`, `<destination_z>` | Teleport destination block coordinates. | Existing `commands.yml` files are migrated by appending commented examples and the new placeholder reference only. Active entries, `enabled`, executors, audiences, and administrator commands are not rewritten. Be careful with broad party audiences and commands that give items, money, or permissions. One command entry runs once per selected audience target.", "url": "pro/event-commands/index.html#common-placeholders"}, {"group": "Item ID Reference", "title": "Potions and Arrows", "section": "Potions and Tipped Arrows", "snippet": "Special potion IDs work in loot chests, entry costs, stage item payment missions, boss rewards, trigger rewards, and other supported vanilla item fields. Use this fo...", "text": "Special potion IDs work in loot chests, entry costs, stage item payment missions, boss rewards, trigger rewards, and other supported vanilla item fields. Use this format: <ITEM_TYPE>_<POTION_EFFECT> Available item types: POTION SPLASH_POTION LINGERING_POTION TIPPED_ARROW Example loot entries: - type: VANILLA item: POTION_LONG_POISON min-amount: 1 max-amount: 3 chance: 100.0 - type: VANILLA item: SPLASH_POTION_STRONG_HEALING min-amount: 1 max-amount: 1 chance: 100.0 - type: VANILLA item: TIPPED_ARROW_SLOW_FALLING min-amount: 4 max-amount: 8 chance: 50.0 `LONG_` variants use Minecraft's extended-duration potion type. `STRONG_` variants use Minecraft's upgraded stronger potion type where vanilla provides one. Available effect names: NIGHT_VISION LONG_NIGHT_VISION INVISIBILITY LONG_INVISIBILITY LEAPING LONG_LEAPING STRONG_LEAPING FIRE_RESISTANCE LONG_FIRE_RESISTANCE SWIFTNESS LONG_SWIFTNESS STRONG_SWIFTNESS SLOWNESS LONG_SLOWNESS STRONG_SLOWNESS WATER_BREATHING LONG_WATER_BREATHING HEALING STRONG_HEALING HARMING STRONG_HARMING POISON LONG_POISON STRONG_POISON REGENERATION LONG_REGENERATION STRONG_REGENERATION STRENGTH LONG_STRENGTH STRONG_STRENGTH WEAKNESS LONG_WEAKNESS LUCK SLOW_FALLING LONG_SLOW_FALLING TURTLE_MASTER LONG_TURTLE_MASTER STRONG_TURTLE_MASTER INFESTED OOZING WEAVING WIND_CHARGED Special potion and arrow drops follow their vanilla stack limits. Potions, splash potions, and lingering potions are split into one-item stacks, while tipped arrows can stack normally up to their item stack limit.", "url": "pro/item-ids/potions-and-arrows/index.html"}, {"group": "Item ID Reference", "title": "Enchanted Books", "section": "Enchanted Books", "snippet": "Enchanted book IDs work in loot chests, entry costs, stage item payment missions, boss rewards, trigger rewards, and other supported vanilla item fields. Use this fo...", "text": "Enchanted book IDs work in loot chests, entry costs, stage item payment missions, boss rewards, trigger rewards, and other supported vanilla item fields. Use this format: ENCHANTED_BOOK_<ENCHANTMENT>_<LEVEL> Example: - type: VANILLA item: ENCHANTED_BOOK_SHARPNESS_4 min-amount: 1 max-amount: 1 chance: 100.0 The level cannot be higher than the vanilla maximum level of that enchantment. For example, `ENCHANTED_BOOK_SHARPNESS_5` is valid, but `ENCHANTED_BOOK_SHARPNESS_6` is rejected by validation. Common enchanted book IDs: ENCHANTED_BOOK_SHARPNESS_5 ENCHANTED_BOOK_PROTECTION_4 ENCHANTED_BOOK_EFFICIENCY_5 ENCHANTED_BOOK_UNBREAKING_3 ENCHANTED_BOOK_MENDING_1 ENCHANTED_BOOK_FORTUNE_3 ENCHANTED_BOOK_LOOTING_3 ENCHANTED_BOOK_POWER_5 ENCHANTED_BOOK_PIERCING_4 ENCHANTED_BOOK_DENSITY_5 The `<ENCHANTMENT>` part uses the same names documented in [Enchant IDs](enchant-ids.md). When an enchanted book drops with an amount above `1`, the plugin creates separate one-item stacks because enchanted books do not stack.", "url": "pro/item-ids/enchanted-books/index.html"}, {"group": "Item ID Reference", "title": "Enchant IDs", "section": "Enchant IDs", "snippet": "The plugin stores enchanted armor, tools, weapons, shields, and enchanted books as vanilla items with an `enchants` map. The same format works in loot chests, boss r...", "text": "The plugin stores enchanted armor, tools, weapons, shields, and enchanted books as vanilla items with an `enchants` map. The same format works in loot chests, boss rewards, trigger rewards, entry costs, item payment missions, and mob equipment. Example loot or reward item: - type: VANILLA item: DIAMOND_CHESTPLATE amount: 1 enchants: PROTECTION: 4 UNBREAKING: 3 Example mob equipment: equipment: main-hand: item: IRON_SWORD drop-chance: 5.0 enchants: SHARPNESS: 2 UNBREAKING: 1 Supported enchantment names are taken from the server enchantment registry. On the Paper 26.x build line this includes: PROTECTION FIRE_PROTECTION FEATHER_FALLING BLAST_PROTECTION PROJECTILE_PROTECTION RESPIRATION AQUA_AFFINITY THORNS DEPTH_STRIDER FROST_WALKER BINDING_CURSE SHARPNESS SMITE BANE_OF_ARTHROPODS KNOCKBACK FIRE_ASPECT LOOTING SWEEPING_EDGE EFFICIENCY SILK_TOUCH UNBREAKING FORTUNE POWER PUNCH FLAME INFINITY LUCK_OF_THE_SEA LURE LOYALTY IMPALING RIPTIDE CHANNELING MULTISHOT QUICK_CHARGE PIERCING DENSITY BREACH WIND_BURST MENDING VANISHING_CURSE SOUL_SPEED SWIFT_SNEAK LUNGE Validation rejects unknown enchant IDs where the plugin can check them. It also rejects enchanted book IDs above the vanilla maximum level, such as `ENCHANTED_BOOK_SHARPNESS_6`.", "url": "pro/item-ids/enchant-ids/index.html"}, {"group": "Help", "title": "Help Center", "section": "Diagnostic Workflow", "snippet": "Validate the dungeon configuration and inspect any reported file/field errors: /dungeon validate &lt;id&gt; /dungeon validate all Check active integrations (Vault, MythicM...", "text": "Validate the dungeon configuration and inspect any reported file/field errors: /dungeon validate <id> /dungeon validate all Check active integrations (Vault, MythicMobs, ItemsAdder, Oraxen, Nexo, WorldGuard): /dungeon status Review the [Troubleshooting](troubleshooting.md) guide and [Complete Reference](complete-reference.md). When updating from an earlier release, follow the [Updating](updating.md) checklist.", "url": "pro/help/index.html#diagnostic-workflow"}, {"group": "Help", "title": "Help Center", "section": "Official Links", "snippet": "**BuiltByBit:** [builtbybit.com/resources/instanceddungeons-pro.112271](https://builtbybit.com/resources/instanceddungeons-pro.112271/) **Discord Support:** [discord...", "text": "**BuiltByBit:** [builtbybit.com/resources/instanceddungeons-pro.112271](https://builtbybit.com/resources/instanceddungeons-pro.112271/) **Discord Support:** [discord.com/invite/sD4HvQh8P4](https://discord.com/invite/sD4HvQh8P4)", "url": "pro/help/index.html#official-links"}, {"group": "Help", "title": "RAM Analysis", "section": "RAM Analysis", "snippet": "Use this command to turn memory reports on or off: /dungeon ram analysis Requires `instanceddungeons.admin`. Analysis is disabled by default. The file `plugins/Insta...", "text": "Use this command to turn memory reports on or off: /dungeon ram analysis Requires `instanceddungeons.admin`. Analysis is disabled by default. The file `plugins/InstancedDungeons/ram-analysis.yml` is created only after the command is enabled for the first time.", "url": "pro/ram-analysis/index.html"}, {"group": "Help", "title": "RAM Analysis", "section": "Settings", "snippet": "enabled: true settings: report-interval-minutes: 10 sample-interval-seconds: 30 max-stored-reports: 144 Reports are stored newest first, with timestamps in the serve...", "text": "enabled: true settings: report-interval-minutes: 10 sample-interval-seconds: 30 max-stored-reports: 144 Reports are stored newest first, with timestamps in the server's local time zone. | `enabled` | Turns analysis on or off. | | `report-interval-minutes` | Minutes between saved reports. | | `sample-interval-seconds` | Seconds between memory samples. | | `max-stored-reports` | Maximum number of reports to keep. |", "url": "pro/ram-analysis/index.html#settings"}, {"group": "Help", "title": "RAM Analysis", "section": "Reported memory", "snippet": "Each period contains: The estimated InstancedDungeons core memory. The estimated memory of active dungeon instances. The combined plugin and instance estimate. Total...", "text": "Each period contains: The estimated InstancedDungeons core memory. The estimated memory of active dungeon instances. The combined plugin and instance estimate. Total instance launches and launches grouped by dungeon ID. Estimated instance-world usage grouped by dungeon. These are estimates for the plugin and its instances, not measurements of total server RAM.", "url": "pro/ram-analysis/index.html#reported-memory"}, {"group": "Help", "title": "Troubleshooting", "section": "Troubleshooting", "snippet": "Start here whenever something does not work: /dungeon validate &lt;id&gt; /dungeon validate all /dungeon reload Also check the server console. Validation warnings in chat ...", "text": "Start here whenever something does not work: /dungeon validate <id> /dungeon validate all /dungeon reload Also check the server console. Validation warnings in chat are shorter than the console output.", "url": "pro/troubleshooting/index.html"}, {"group": "Help", "title": "Troubleshooting", "section": "Dungeon Will Not Open", "snippet": "Check: `dungeons/&lt;id&gt;/config.yml` exists. The config uses the current format marker. The template world exists and is loaded. Spawn and exit are set. Min/max players...", "text": "Check: `dungeons/<id>/config.yml` exists. The config uses the current format marker. The template world exists and is loaded. Spawn and exit are set. Min/max players are valid. The dungeon passes `/dungeon validate <id>`. Dungeons using the 1.x config format must be recreated for 2.x.", "url": "pro/troubleshooting/index.html#dungeon-will-not-open"}, {"group": "Help", "title": "Troubleshooting", "section": "Boss Dungeon Does Not Complete", "snippet": "Check: The dungeon was created as `boss`. `boss.yml` exists. The boss location is valid. `boss.must-die-to-complete` is `true` if boss death should complete the run....", "text": "Check: The dungeon was created as `boss`. `boss.yml` exists. The boss location is valid. `boss.must-die-to-complete` is `true` if boss death should complete the run. The boss entity spawned inside the instance world.", "url": "pro/troubleshooting/index.html#boss-dungeon-does-not-complete"}, {"group": "Help", "title": "Troubleshooting", "section": "Trigger Dungeon Does Not Complete", "snippet": "Check: The dungeon was created as `trigger`. `trigger.yml` exists. The trigger was placed with `/dungeon settrigger &lt;material&gt;`. The trigger block still exists in th...", "text": "Check: The dungeon was created as `trigger`. `trigger.yml` exists. The trigger was placed with `/dungeon settrigger <material>`. The trigger block still exists in the template or instance. The material is a supported button or pressure plate.", "url": "pro/troubleshooting/index.html#trigger-dungeon-does-not-complete"}, {"group": "Help", "title": "Troubleshooting", "section": "Tower Does Not Continue", "snippet": "Check: `dungeon-type: tower`. `tower-stage-type` is correct. `next-dungeon` points to an existing dungeon. The next dungeon passes validation. Only the `FIRST` stage...", "text": "Check: `dungeon-type: tower`. `tower-stage-type` is correct. `next-dungeon` points to an existing dungeon. The next dungeon passes validation. Only the `FIRST` stage has entry costs. `FIRST` points to `MIDDLE` or `LAST`. `MIDDLE` points to another `MIDDLE` or `LAST`. `LAST` is the final tower dungeon.", "url": "pro/troubleshooting/index.html#tower-does-not-continue"}, {"group": "Help", "title": "Troubleshooting", "section": "Stage Gate Does Not Open", "snippet": "Check: Stage files are in `dungeons/&lt;id&gt;/stages/`. Stage orders are continuous: `1`, `2`, `3`. The gate was saved with `/dungeon gate save`. Active missions are comp...", "text": "Check: Stage files are in `dungeons/<id>/stages/`. Stage orders are continuous: `1`, `2`, `3`. The gate was saved with `/dungeon gate save`. Active missions are complete. Later stages do not progress until earlier gates open.", "url": "pro/troubleshooting/index.html#stage-gate-does-not-open"}, {"group": "Help", "title": "Troubleshooting", "section": "Loot Chests Are Empty", "snippet": "Check: The loot chest config has loot entries. Chances are above `0`. The placed chest was created with `/dungeon lootchest give &lt;id&gt;`. Custom item provider plugins ...", "text": "Check: The loot chest config has loot entries. Chances are above `0`. The placed chest was created with `/dungeon lootchest give <id>`. Custom item provider plugins are loaded.", "url": "pro/troubleshooting/index.html#loot-chests-are-empty"}, {"group": "Help", "title": "Troubleshooting", "section": "Players Get Removed From Instance Worlds", "snippet": "Active instance worlds reject players who are not part of the dungeon run. This prevents outside players from entering temporary worlds. If this happens to real dung...", "text": "Active instance worlds reject players who are not part of the dungeon run. This prevents outside players from entering temporary worlds. If this happens to real dungeon players, check: They did not leave the party. They did not disconnect during start. The party is still active. They did not use external teleport commands into another instance.", "url": "pro/troubleshooting/index.html#players-get-removed-from-instance-worlds"}, {"group": "Help", "title": "Troubleshooting", "section": "Custom Items Fail", "snippet": "Check: The integration plugin is installed and loaded. The item ID is correct. Run `/dungeon status`. Use the integration lookup command when available: /dungeon myt...", "text": "Check: The integration plugin is installed and loaded. The item ID is correct. Run `/dungeon status`. Use the integration lookup command when available: /dungeon mythicitem [itemId] /dungeon itemsadder [itemId] /dungeon oraxen [itemId] /dungeon nexo [itemId]", "url": "pro/troubleshooting/index.html#custom-items-fail"}]};
